/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230612-6","meetingId":"r05-cm06","date":"2023年6月12日","dateIso":"2023-06-12","committee":"区民委員会","time":"午後 １時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"区民まつりについてですけれども、ほかのところでも物価高騰の内容が入っていました。区民まつりは規模が大きいので、町会の負担が少なく開催ができるようにという地域の方の声に、私も含めまして、予算の拡充を考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"区民まつりに関するご質問です。各地区の実行委員会から申請をいただきまして、その申請内容に収支予算書であったり、実施計画というのを付けていただきながら、補助金を交付しています。各地区から委員ご指摘のような声というのも受けているところではあります。","voiceIndex":34,"id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"引き続き、拡充をよろしくお願いいたします。続けてよろしいですか。歩行喫煙についてなのですけれども、路上喫煙禁止・地域美化推進地区における巡回指導が平日に行われていると伺いましたが、平日の時間帯というのは何時頃に行われているのですか。","respondent":"河合生活安全担当課長","answer":"啓発につきましては２通りございまして、警察ＯＢ・ＯＧで構成していますサポート隊につきましては、朝７時半から午後１０時までの間で、状況によって、苦情等があるとき、柔軟に対応している次第です。","voiceIndex":36,"id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"私も地域の方から、結構、朝の通勤時間でしょうか、ご自宅から駅やバス停に来られる間に吸っている方が多いのではないかということをうかがいます。結構、夜です。帰ってきて、駅かバス停からか、ご自宅に帰られる間に少し喫煙をされているというのを聞いているので、そういった時間帯も考えていただければと思います。","respondent":"河合生活安全担当課長","answer":"サポート隊は午後１０時まで行っていまして、夜、客引きのパトロールなども行っているのですけれども、そういったところで苦情があった際には、実態把握のために、柔軟に対応させていただいているところです。","voiceIndex":38,"id":"exchange-003"},{"speaker":"えのした委員","kind":"確認","question":"ありがとうございました。確認が取れました。引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"次が、商業・ものづくり課。それにおいて、品川区として、どういう融資も含めて応援していくかということがあったら教えていただきたい。それでいいのかなという思いがあるので、その辺についてはいかがですか。そして、いろいろな委員会とかで、区民等のお話とか質問とか、要望をしているわけですけれども、区政協力委員会からもいろいろ要望が来ると思うのですが、区政協力委員会は町会長たちの集まりです。","respondent":"河合生活安全担当課長、小林商業・ものづくり課長、中西八潮まちづくり担当課長、宮澤地域活動課長","answer":"子どもの安全につきましては、現在、まもるっちは新たなシステム改修等をしておりますので、それを踏まえて。ほかのいろいろな助成制度なども使いながら、景気あるいは業績を上げていただきまして、その後の返済計画をしっかり予定どおり進めていただけるよう。今年度に関しましては、取組を積極的に進めながら、本委員会でのご報告等も適時行ってまいりたいと思います。平成２８年に、品川区町会および自治会の活動活性化の推進に関する条例というのを制定しております。","voiceIndex":42,"id":"exchange-005","title":"町会・自治会支援"},{"speaker":"横山委員","kind":"確認","question":"３０ページの区政協力委員会の内容のところで、区政協力委員会協議会、令和５年度よりブロック別と統合し、定期的な会議は廃止というところと、３３ページの（２）地区委員会連合会事業のの3)地域環境実態調査、こちらも令和５年度より廃止ということで、こうした廃止ですとか統合の考え方について、全体的な部分というのと、この２点に関して確認させていただけたらと思っています。","respondent":"宮澤地域活動課長","answer":"これにつきましては、東京都からの依頼があって行う事業でもありますので、品川区の地区委員会連合会の事業として実施していた地域環境実態調査については廃止したです。","voiceIndex":48,"id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"今確認させていただいた内容で、内容がかぶる部分に関してであったりとか、ほかの会議であったりとか、別のところにきちんと意見集約して、お声としてはいただける状況だということで、理解としてはよろしいでしょうか。","respondent":"宮澤地域活動課長","answer":"区政協力委員会につきまして、委員のご指摘のとおりです。地域環境実態調査につきましては、東京都と同様の調査というのがあります。そちらは引き続き行っていくところです。それを踏まえた上で、区の連合会独自の事業としては中止するという部分になっているです。","voiceIndex":50,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問","question":"地域環境実態調査につきましては、今まで都で行っている調査というのと、こちらの地域環境実態調査の内容といいますか、青少年への有害な情報ですとか、現状把握というのが、もうできない部分があるのか、それとも引き続き、都が行っている調査ですとか、その他の区の事業であったり、いろいろな情報の中で。","respondent":"宮澤地域活動課長","answer":"一方で、区独自で地域環境実態調査をしていたところもあります。地区委員自身からも、有害図書、コンビニ等を実態調査で回っていく中で、いわゆるデジタル化が進む中で、なかなか実態にそぐわない部分もあるのではないかという声もありまして、連合会で廃止をしたです。","voiceIndex":52,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"マイナポイントについてもそうですし、保険証との紐づけも、口座との紐づけもそうですけれども、本当にたくさんのトラブルが出てきてしまっていて、今朝のニュースでも、マイナンバーの拡大に不安を感じるというのが７６％という世論調査が出ている中で、区としても普及促進と、この事務事業概要に書かれていますけれども、そういった部分では、安全性が確保されるまで一旦立ち止まるとか。","respondent":"河合生活安全担当課長、中西八潮まちづくり担当課長、吉野戸籍住民課長、小林商業・ものづくり課長","answer":"警察と情報共有を図りながら、共に広報啓発活動は行っているところです。警察でできないところや補強する部分で、区でも対応しています。ただ、日程に関しましては、今年度はおまつりですとか、様々な事業が始まってまいりますので、少し前後するかなと思いますが。マイナンバーの件なのですけれども、この後、状況等をご説明させていただきたいと考えています。一つは我々のほうで金融支援として、融資あっ旋というお話も出ましたけれども、それ以外に。","voiceIndex":55,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"マイナンバーのところは、私たちもデジタル化全てに反対ではなくて、本当に住民が便利に、そして生活が豊かになるデジタル化は進めていくべきだと思うのです。一般家庭には少し軽減策が打たれましたけれども、業者にはそれがなっていないという状況だと思いますので、さらなる支援というところでは、区として直接支援をしていくということは検討していただきたいと、それは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も１点だけ。それと、３３ページ、荏原郵便局での電子証明書発行事務を新たに実施と、これはプレス発表にも載っていましたけれども、荏原郵便局というところで記載はあるのですが、これは区役所に来なくてもできるというお話だったと思います。荏原郵便局がオンラインで品川区役所とつながって確認ができるというお話なのですが、荏原郵便局だけなのでしょうか。その辺りを教えていただければと思います。","respondent":"吉野戸籍住民課長","answer":"荏原郵便局なのですけれども、当初は品川郵便局とか大崎郵便局とか、そういったところも考えたのですが、まず体制づくりといったところで、荏原郵便局がそういった対応ができますという、システムも置かなければいけないので、そういった場所なども含めて。","voiceIndex":61,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"意見","question":"前半の部分は理解できます。数があまりにも多くて滞っていると。後半の部分は、先様のある話ではあると思うのですが、できれば増やしていただかないと、都内初の試みということでしたので、ぜひそこのところはご努力を続けていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"産業振興関連で、２点質問させてください。それから２つ目が、商店街活性化支援に関わることなのですけれども、デジタル地域通貨を商店街連合会と進めている他自治体がありますが、品川区としてはどのようにお考えであったり、進めているのかという状況があれば、教えていただければと思います。","respondent":"小林商業・ものづくり課長","answer":"我々として、商店街の決済、キャッシュレスとかデジタル化というのをいろいろやっておりますけれども、そういう中で、まず商店街でもそういうことを円滑に進められるようにということで、商店街連合会ともそういうことの話というか、検討を進めてまいりたいと考えています。","voiceIndex":66,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"スタートアップ企業支援については、ほかの自治体もやっている中で、ぜひ特徴を出して、おっしゃっていただいたような形で進めていただきたい、ぜひ品川区のネットワークをうまく使った企業の支援を進めていただきたいというのと、それをぜひ発信していって、取り組んでいただきたいと考えています。これから商店街連合会の方々と、ぜひそういった話を進めていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"公園等の整備についてコメントします。スポーツ推進に関して、球技ができる公園の整備をぜひ進めていただきたいと思っていて、エリアによって少しばらつきがあるのかなと思っていまして、大崎や五反田のエリアの中では、小さい子どもたちを中心として球技ができるところが少ないと感じているところがあるのですが、そういったことに対する取組について教えていただきたいです。","respondent":"三井スポーツ推進課長","answer":"現在、球技ができる施設等について具体的に検討しているところはございませんが、公園ですと、公園課と連携しながら検討していければと思いますが、スポーツ推進計画などの見直しもありますので、そちらについては今後、考えさせていただければと思います。","voiceIndex":74,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうあります。ぜひ考えていただきたいと思います。品川区で、プロスポーツでフットサルだったり、バスケットボールだったりができているところもあります。野球やサッカーという多くの子どもたちがやっているものに加えて、こういった様々なスポーツが身近に活動できるような環境づくりを、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"体育館運営で、総合体育館と戸越体育館が出ていて、目的はスポーツということだと思うのです。スクエア荏原もスポーツを目的としてどんどん使っていいわけですよね。でも、実際にそうなっているのかなと思うと、少し疑問を感じるのですけれども、今、総合体育館というのは、スポーツ、体育という意味においてはどういう位置づけになっているか、教えてください。","respondent":"三井スポーツ推進課長、篠田文化観光課長","answer":"スクエア荏原に関しても、基本的に地域スポーツクラブで利用しているところはありますので、スクエア荏原についても、スポーツを親しめる場としてＰＲできればと考えております。ただ、様々な活用の仕方というのは常に検討しながら、今の形にとらわれることなく新たな取組ができるのであれば、そういったことも検討してまいりたいと思っているところです。","voiceIndex":78,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"もっと活用してもらいたいのです。この施設は荏原においてとても大切な施設なので、もう少し積極的に活用をＰＲしていっていただきたいという思いがあって質問しているので、答弁の中でそのように、厳しいですということではなくて、もっと前向きというか、積極的にやっていただきたいと思っていますし、位置づけ的にはスポーツもしていい施設ですよね。その辺について、もう一回答弁をいただけますか。","respondent":"篠田文化観光課長","answer":"そうなりますと、ほかのスポーツを入れてということになってしまいますと、そういった地域の皆さんの練習場所といった部分も確保していかなければいけないという観点もありますので、そういうものとうまく調和を取りながら。","voiceIndex":81,"id":"exchange-018"},{"speaker":"えのした委員","kind":"質問・要望","question":"えばら」はすごくいいイベントだなと、私も拝見させていただいて、少し広過ぎて全部回り切れなかったところがあるのですけれども、前回はまだコロナ禍がぎりぎりどうかなというところで、町会との連携がされていなくて、近隣の町会長からは、せっかくこれだけ大きくて新しいイベントをやるのに、町会を絡めてよというお話もされていたので、その辺を今回から、お考えをお聞かせいただきたいです。","respondent":"篠田文化観光課長","answer":"昨年は、開催日だけは１０月の末という形で決まっていたのですけれども、４月、年度が替わった時点では、まだコロナの状況がなかなかはっきりしていないということもあって、この状況で本当にやっていいのか、できるのかということで。","voiceIndex":84,"id":"exchange-019","title":"町会・自治会支援"},{"speaker":"えのした委員","kind":"質問","question":"ぜひ拡大して、盛り上がるようなイベントを期待しております。これは私も知らないのですが、Ｗｅｂ媒体による情報発信事業、ＳＮＳ、インフルエンサーを使ってと書いてあるのですけれども、例えばシナモロールだったりとか、インフルエンサーがＳＮＳを発信しているというのがあるのですか。","respondent":"篠田文化観光課長","answer":"特に台湾ですとか、近辺でインバウンドの需要が非常に高いところに関して情報発信していくということで、この間、続けてきているものです。","voiceIndex":86,"id":"exchange-020"},{"speaker":"えのした委員","kind":"質問","question":"立派な施設で、初めての試みなのですが、ボルダリングされる方に伺うと、初心者教室などもやっているようなのですけれども、白い粉、チョークといいますか、あれを使ってはいけないという話が入ってきていて、私もやらないものですから分からないのですけれども、やる方にとっては、お子さんでも初心者でも、それがあるほうが安全にいいのだと。そこはお聞かせいただけますでしょうか。","respondent":"三井スポーツ推進課長","answer":"理由は、粉チョークですと、実際、ボルダリング場の近くにランニングコースとかウォーキングコースがあるので、粉が舞ってしまって、ほかの方に迷惑がかかってしまうということがございまして、粉のチョークのみ禁止をさせていただいておりまして。","voiceIndex":88,"id":"exchange-021"},{"speaker":"えのした委員","kind":"意見","question":"私も初めて液体チョークというものを知りましたけれども、そういうものがあれば、区民の方が安全に使えると思います。どうもありがとうあります。続けて、しながわシティランは、まだ年度が始まったばかりなのですけれども、もし少しでも進捗状況がありましたら、お聞かせ願えれば。","respondent":"三井スポーツ推進課長","answer":"しながわシティランですが、現在、実行委員会の開催に向けて、今年度は取り組んでいるところです。しかるべき時期が来ましたら、ご報告をさせていただきたいと思いますので、よろしくお願いいたします。","voiceIndex":90,"id":"exchange-022"},{"speaker":"えのした委員","kind":"意見","question":"しかるべき時が来ましたら、お待ちしております。それから、デフスポーツの啓発イベントを予定と。こちらも、もし予定されているのであれば、お聞かせ願えればと思います。","respondent":"三井スポーツ推進課長","answer":"まだ具体的なところは決まっていないのですが、夏頃に、デフサッカーの日本代表合宿について誘致をする予定になっておりまして、そちらについて、現在準備を進めているところです。","voiceIndex":92,"id":"exchange-023"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"これらは様々、報道もされている状況ですけれども、こうしたトラブルに関して区民の方から、先ほども話がありましたが、数字で８０％を超える方がもう申請しているという状況ですので、マイナンバーカードについての不安や問い合わせというのは、区には来ているのか伺いたいのと、あと、公金受取口座や健康保険証の紐づけについては、区としてはどこまで、どれぐらいの方が紐づけされているかというのは。","respondent":"吉野戸籍住民課長","answer":"区民の方からのお問い合わせなのですけれども、電話等では実はまだ来ておりませんで、ただ、今回の件でマイナンバーカードを返納されたいという方が、３月と６月に１件ずついらっしゃいました。","voiceIndex":102,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"分かりました。それで、そういった中では、次々と、コンビニエンスストアの交付から始まって、システムが新たになっていく中では、大変ご苦労もあると思うのですけれども、先ほども言ったのですが、今後推進という形を、区としては変わらず積極的に進めていくということでいいのかということの確認と、あと、こういうトラブルが区で発生した場合の対応というのは、どのようにやっていくのか。","respondent":"吉野戸籍住民課長","answer":"国の方向性が決まりましたら、区民の方に不利益にならないように、対応には出遅れがないように、準備はしっかりしていきたいと考えているところです。","voiceIndex":104,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そういったところで、全国保険医団体連合会、保団連からは、直ちに運用停止をという声も出ています。そうしたところでは、どうしても出てしまうミスですというのが、許されない部分もあるのではないかと思いますので、そこは区としても、さらなる推進という形ではなくて、一旦立ち止まるということをするべきではないかと改めて申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"品川区では誤交付等はないというお話で、これはよかったと思いますが、当然、石田ちひろ副委員長がおっしゃるとおり、個人情報がどういう形であれ、他人のものが出てきてしまったというのは、あってはならないこと。マイナンバーカード自体から、何か個人情報が流出したなどということ自体はないと認識しておりますが、そういう認識でいいのかということ、まずその件を伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"カード自体からデータが流出したということではありません。","voiceIndex":108,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど返納の方が３月にお一人、６月にお一人、２人いらっしゃるということで、これは重く受け止めなければいけないと思うのです。これからも区としては、マイナンバーカードの普及と、こういうことの正確な情報の発信にしっかり努めていただきたいと思いますが、最後にご答弁をお願いしたいと思います。","respondent":"吉野戸籍住民課長","answer":"これまでも丁寧に対応してきたのですけれども、今回の件を踏まえまして、より一層丁寧に、区民の方には説明と対応をしていきたいと考えております。","voiceIndex":110,"id":"exchange-028"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、去年に関しては委員会ごとに、例えば１日であったりとか、日数であったりとか、そういったところを話し合うというお話が委員長会等であったというご報告をいただいたかと思うのですけれども、今回は前提条件としてどういった形なのかというところを確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、それは委員長会で、そういう委員会ごとの判断をするという話になったのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"どういったことができるのか、気持ちとしてはもちろんこれまでどおり、しっかりと勉強して先進事例から学んでいくということは、議員として、委員として、とても大切なことだと基本的に思っているところなのですけれども、まず議会全体としての部分というのも大切だと考えていますので、そちらの確認をお願いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"これは何日までに出さなければいけないと、これからアナウンスがあるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"先ほど横山委員からもあったのですけれども、１泊なのか、日帰りなのか、２泊３日なのかによって、出す項目とかも変わってくるので、確認をしていただいた上で、事務局なりを通して各委員にお知らせいただけるとありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":44531,"voices":125}},{"id":"r05-20230612-7","meetingId":"r05-cm06","date":"2023年6月12日","dateIso":"2023-06-12","committee":"厚生委員会","time":"午後 １時００分～午後 ３時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"福祉部の事務事業概要の１ページの組織図のところから伺いたいのが、福祉計画課のところで、社協と三徳会と品福とさくら会の４か所に派遣というになっているのですけど、障害者施策推進課のところでは、福栄会に派遣ということで、合計７名の職員が社会福祉法人のところに派遣されているとここに書かれているのですけど、区の職員という身分で出ているということで。","respondent":"今井福祉部長","answer":"今、ご質問がありました社会福祉法人の派遣の目的というお話でしたけど、こちらは社会福祉法人の組織または介護保険、障害者などの分野で、様々な現場での対応をしている法人になりまして、こちらの現場で区では中々得られることができない知見ですので。","voiceIndex":44,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、社会福法人のところで現場の実態を学ぶと言いますか、掴むと言いますか、それが区に戻ってきてもそれが生かせるようということで派遣しているということで確認させていただいていいでしょうか。それから、社会福祉法人から派遣については、高齢福祉課で４名となっておりますけれども、どういう目的で、何名がどこに配置されているのか教えてください。","respondent":"菅野高齢者福祉課長、今井福祉部長","answer":"わたくしの方からは高齢者福祉課のところですね、２ページのところに社会福祉法人からの派遣者４人と記載があります。こちらの質問についてお答えします。いわゆる社会福祉法人への区職員の退職された方の再就職については、こちらの方では把握しておりませんので、発言の方は差し控えします。","voiceIndex":46,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"わかりました。この５法人なのですけど、様々な社会福祉法人で、区内に品川区も様々社会福祉法人があると思うのですけど、そういったところにも派遣するということは、この５法人から変わるということはあるのか、どうなのかということも伺いたいと思います。それから、ちょっと続いて違う質問をしたいと思います。福祉部全体で何人ぐらいいるのかも教えてください。","respondent":"今井福祉部長、若生健康課長、池田国保医療年金課長、舩木生活衛生課長、坂野保健予防課長、石橋品川保健センター所長","answer":"始めに大きく２つだと思うのですが、一つは５法人ということでお話ありましたが、社会福祉協議会、三徳会さん、品福さん。保健衛生編で、会計年度任用職員の内訳ですが、まず各課でご説明させていただければと思うのですけど、資料の２ページおひらきただきまして。国保医療年金課は、すべて７名とも事務職です。以上です。生活衛生課につきましては、全て衛生監視です。保健予防課７名ということですけど、事務職が２名、他が保健師。助産師が８名、精神保健福祉士が３名、看護師が３名となっております。","voiceIndex":49,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"意見","question":"そうようにご報告いただくと、すごく専門職にかなり支えられているのだなということがわかりますので、各課の２つの枠になっていますけど、ここのところに何名と記載していただくと、職員体制というのがわかってくるな思うので、ぜひ今後に向けてご検討いただければと思います。","respondent":"今井福祉部長","answer":"申し訳ございません。本日資料がございません。","voiceIndex":57,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"かなりいらっしゃるのは、いらっしゃるのですかね。暮らし・しごと応援センターは国の法律によって新たにできた部署ですので、ここの職員体制というのが、ちょっと改善が必要なのではないかと、会計年度任用職員が分かるような形で表記をしていただきたいと思うのですが、いかがでしょうか。","respondent":"今井福祉部長","answer":"今、委員ご指摘の会計年度任用職員につきましては、わたくしども部だけでなく、それぞれの部がどのように形で人数を適正に把握すべきであるかは検討させていただきたいと思います。","voiceIndex":59,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"改めて伺いたいのですけど、保健師の数のところで、これまでわたくしは議会の中で、増員をということを要望し続けているのですけど、保健師の人口対比は、品川区の場合は２３区２２位、下から２番目、保健師が非常に少ないという状況に、ずっと改善されていない状況があるのですけど、そして、その質問をしたときに人事課長からは。","respondent":"石橋品川保健センター所長、若生健康課長","answer":"わたくしからは先ほどの会計年度任用職員についてご説明します。大変失礼いたしました。３保健センターの合計になります。助産師が８名、精神保健相談員が５名、看護師が３名、保健師が１名、事務職が３名となり合計２０名となります。保健師の人員の関係です。この間ですね保健師の業務が増えてきているなかで、２３区の中で、人口比でいくと少ないということはご指摘いただいているところです。","voiceIndex":61,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"次の質問にいきたいと思うのですけど、今年は高齢者も障害者も計画策定が集中して、計画が１０年に一回とか、３年に一回とかそういった計画が今年に集中する状況にある年になりましたけど、おおよそのスケジュール的に厚生委員会にいつごろ、どういう形で報告がされるのか伺いたいのと、先ほどの地域福祉計画の策定委員会を作って、策定について検討していくという報告、障害者の方もそうだと思うのですけど。","respondent":"東野福祉計画課長、川崎障害者施策推進課長、菅野高齢者福祉課長","answer":"各計画の策定につきましては、進めているところでございまして、進捗につきましては、例えば福祉計画課ですと。それからアンケートについてご報告する予定です。今月６月に策定委員会１回を行いまして、トータルで策定委員会としては４回行う予定です。高齢者福祉課につきましては、介護保険事業計画につきましては、推進計画と同じように１１月ぐらいに素案がまとまってきますので。","voiceIndex":64,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"第九期の介護保険事業計画の策定なのですけど、介護制度推進委員会の方で行うということで、介護制度推進委員会の議事録を読んだのですけど、１２月から１月ぐらいに第八期の検証と、第九期へ課題整理ということで、介護制度推進委員会を設けたいということで書かれていたのですけど、ちょっとその後の議事録が出ていなくて、いつごろされて、この議事録というのはアップされる予定なのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"給付費分科会の方では意見を踏まえて、部会の方に議論が移ったということで、そこについての報酬については、大体来年の７月に決定するのですけど、その前には案件と構成が秋ぐらいに見えてくることもありますので、そのあたりの国の動きを踏まえつつ、あとは区としましては。","voiceIndex":68,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"介護予防推進委員会の議事録を読んだときにですね、委員の方からエアコン要望が出されていまして、今年もすごく暑くなるという予想が出されていて、ちょっと質問させていただければと思うのですけど、この委員の方が毎日ニュースでエアコンをつけていきましょうと言われるけれども、品川区でも古いアパートに住んでいる高齢者の方が、実際にエアコンをお持ちなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"これが出てこないと思うのですけど、これからすぐに夏に向かって、ちょっと聞いておきたい。検討するということであったので、この点は聞いておきたい。思ったのですけど。何か出ます。報告か何かが。次の議会に出るということがあるのであれば。次の６月議会の厚生委員会で報告があるのであればいいのですけど。出なかったら、その場で質問してもいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"この内容が次の議会で審議できるのであればいいのですが。質問できる場があるのであれば、それでいいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"エアコンのことをつっこんで聞くのはまたの機会にしたいと思います。実際に今年は大変暑い夏になるだろうという予報も出ていますので、私はエアコンの電気代、エアコンの設置助成金なども品川区としてぜひ検討していただきたいという要望をさせていただきたいと思います。他の方もいらっしゃるので、まだ何点かあるのですけど。にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの福祉部事業概要の一番最後の公的扶助のところで、見ていてわからない点があるので、生活福祉課の９ページのところで、品川区の現況の推移というところで、こちら平成２１年度から平成２４年度まで急激に増加していると、平成３０年度以降は微減となっていると、こちらの表なのですけど、ここの列は何を表しているのですか。９ページです。表の出だしの「４」というところ。なんの「４」ですか。","respondent":"豊嶋生活福祉課長","answer":"場所はわかりました。確かに委員おっしゃるように。大変申し訳ございません。内容を後程確認させてください。","voiceIndex":82,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"今、感染者がニュースで見ると今月４日までの1週間で合わせて2,207人で、うち医療機関で5.29人ということであったのですけど、感染が続いていて、今後も十分な注意が必要だということで、厚生労働省の方からも出ていたと思うのですけど、区ではどの点に注意が必要であるかと考えているのかを伺いたいと思います。","respondent":"坂野保健予防課長","answer":"定点なのですけれども区内で１３か所前後だと思いますが、詳しい資料が手元にございません。医療機関係の資料も手元にございません。","voiceIndex":84,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国保の方も今後マイナ保険証に替わってくるかと思うのですけど、様々マスコミでも問題点が報じられていて、先日は読売新聞でもマイナ保険証の見直しは今からでも遅くはないと社説が出るくらいね、開業医の６割が加入している保険医団体連合会が毎回毎回声明を出されていますけど、区としてマイナ保険証の課題をどのように捉えているのか、確認したいと思います。","respondent":"池田国保医療年金課長","answer":"医療機関についてですけど、私共ですべての医療機関の全部を把握しているものではありませんけれども、先日、厚労省のホームページで５月現在の品川区の医療機関の登録数といたしましては、701医療機関がマイナンバーカード対応へ移行できるとしておりましたので。","voiceIndex":86,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これまでは、厚生労働省が黙っていても手元に来たわけですけど、それが来なくなってしまうわけですから、様々なトラブルが起こってくるわけですけど、厚生委員会に対してもマイナ保険証にどう対応していくか、どこかで報告を出していただきたいわけですけど、そのことについて伺いたいです。","respondent":"池田国保医療年金課長","answer":"マイナンバーカードによる保険証の廃止から１年は、有効期間というところがありますので、その辺につきましては国民健康保険証ということもありますので。来年は、後期高齢者制度の方の保険証も変わるということで、資格確認証や色々な制度的な保険証が変わってきます。","voiceIndex":88,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3660#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39191,"voices":95}},{"id":"r05-20230612-8","meetingId":"r05-cm06","date":"2023年6月12日","dateIso":"2023-06-12","committee":"建設委員会","time":"午後 １時００分～午後 ４時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"まつざわ副委員長","kind":"意見","question":"品川区議会自民党・無所属の会のまつざわと申します。私にとって初めての建設委員会ですが、新妻委員長はじめ、皆様としっかりと協力して、建設的な会議をしていきたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"再開発の事業について伺いたいと思うのですけれども、この間ずっと様々なところで進められておりますが、大崎だったり五反田だったり、武蔵小山や大井町、戸越公園と、どんどん区内各地で行われているという状況ですけれども。それと、羽田空港アクセス線新駅を要望するということで、まちづくりマスタープランにも位置づけているという説明でしたけれども、今の検討状況を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それからもう１点、羽田アクセス線につきましては、委員のほうから要望というお言葉がありましたが、要望の可能性を検討していくというところで、要望ありきで何か検討を進めているものではございません。","voiceIndex":57,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"新駅の要望の可能性の検討というところでは、そうすると、今どこがというのが検討されていると思うのですけれども、どういったところが出てきている、候補地になっているのか、そこを伺いたいと思います。そうした中で、区としてやはり都市計画というのですかね、再開発すべきでないところというのが実際あると思うのですよね。","respondent":"鈴木都市計画課長","answer":"羽田アクセス線の現在検討の、どの辺りにというところは、その検討対象箇所に何か区の施設があるとかではございませんで、それはもう本当に技術的に可能かどうかというところを民地の土地の地図上で検討している状況ですので。","voiceIndex":59,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間ちょっと難しいという話なのですけれども、ぜひそうしたことをやっていただきたいと思うのですが、区の検討状況を伺いたいのと。区内の駅のホーム柵の問題なのですけれども、徐々に今進んできて増えておりますけれども、ぜひ全ての駅に設置をしていっていただきたいと思うのですが、区のお考えと状況について伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"初めに、特定整備路線ですが、今ご紹介いただいたように、東京都、当初事業開始が平成２５年と、それから１０年間で整備を進めていくというところが、一度事業の延伸がなされたというところで、令和７年度までと事業期間が今定められているところです。","voiceIndex":61,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"特定整備路線については都と同じ考えで進めていくということですが、令和７年度が一応期限ですけれども、この間ですから１２年ぐらいやってきた中で、まだ土地の買収率も半分をいってないと。一部いっているところもありますが、多くのところがいってないという状況ですので、これはもう私はやめるべきだと。次の質問に移ります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後ではまとめて３つお聞きしますけれども、羽田の全区民アンケートが、今準備が進められていると思うのですが、その検討状況、開始時期ですとか、この間約半数ぐらい羽田の質問になるという話も出ておりますが、何問ぐらいとか、そうした状況を伺いたいと思います。","respondent":"鈴木都市計画課長、竹田住宅課長","answer":"内容等については、実施の前に議会のほうにもしかるべきタイミングでしっかりとご説明してまいりたいです。もう１点です。建築紛争ですが、要綱に沿いまして、住民の方には区にできること、区にできないことを丁寧にご説明しています。今後も住民に丁寧に説明してまいりたいと考えております。","voiceIndex":65,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"要望してはいけないのでしょうか。可能性があるのかどうか。それと、再開発のところで言いますと、再開発の組合はどういう役目のものなのでしょうかというのを改めてお聞きしたいと思います。建設委員としても、やはり公金が出ているものと民間との関係性というものをしっかりとしていきたいので、どういう感性を持って、関係性を持って再開発をされているのか、そこを教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"一方で、西山手ルートというのも計画の中で示されておりまして、渋谷・新宿方面に向かう路線ですが、その辺りは八潮の先端部分の辺りにも通るということありますが、そうした情報もしっかり入れながら、強い思いを持って今検討を進めているです。","voiceIndex":69,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"組合との関係、これあれですか、準備組合の段階で誰がメンバーになっているかというのは調べれば分かるのですか。これはびっくりしました。そうすると、本当に公園がリニューアルですてきなものにしていきたいといった場合の要望を聞くところというのがもしかしたらずれているかもしれないので、その情報を聞く方法として区外のほうにも目を向けていただきたいなと思うのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"やはりまずは区民の方々に意見を聞いて、当然いらっしゃる様々な方々の意見もないがしろにするわけではございませんが、やはり品川区民の方々からまずは意見を収集して、区民の方が誇れる水族館となるように取り組んでいくという考えです。","voiceIndex":75,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、委員長の仕切りの下、個別ではなく総論的な視点から何点かお伺いをしたいと思いますが。逆にそこを有効活用することで、商店街の方への協力いただいたことに対する支援というような形での有効活用を私はぜひすべきだと考えていますが、その一時的な未利用の公有地の活用という視点、ぜひ前向きなお考えをお聞かせいただきたいと思います。","respondent":"小川木密整備推進課長","answer":"ほかの未利用地に関しましては、なかなか周辺の状況等によって難しいところもあろうかとは思いますけれども、検討等もしながら、状況によってはなかなか難しいといった判断も出てくるおそれもありますが。","voiceIndex":78,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"例えばですが、長期にわたって比較的すぐには事業実行されなさそうなところなどでは、マイガーデンなどのような、あるいは駐車場とか、いろいろな活用方法はあるかと思いますので、そこはせっかくの用地で、恐らく財源的に、道路用地として取得された土地なので、他利用はなかなか、財政的な視点から、予算的な措置の時点から制限がかかってしまっているというところもあるのかもしれませんけれども。","respondent":"小川木密整備推進課長、竹田住宅課長","answer":"公有地の活用ですが、委員おっしゃられるとおり、なかなか道路事業地をそもそも使用すること、また財源の問題等、いろいろな課題はあろうかと思いますが、いただいたご意見をしっかりと東京都のほうに伝えてまいりたいと考えています。事例集にする形で皆さんに広くお伝えできるものがあるかどうかについての検討もしまして、可能かどうかも含めて検討していきたいと思います。","voiceIndex":80,"id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"１点だけ細かい話、水族館に関してなのですけれども、何でイルカショーが終了となってしまったのか。これは結構人気のあるものであったように感じているのですが、そこだけ、すみません、個別の話で、よろしくお願いします。","respondent":"高梨公園課長","answer":"それと、イルカを飼育するためには非常に大きな水槽であったり設備ということで、財政面でもリニューアルを考える上では、次の３０年を考えたときに、その負担を賄えるだけの規模でリニューアルすべきかどうかというような財政負担の面。","voiceIndex":83,"id":"exchange-011"},{"speaker":"田中委員","kind":"確認","question":"分かりました。ありがとうございました。それで、先ほどの委員長の仕切りの点で確認だけなのですけれども、防災のことですとか環境のことは特別委員会のほうで所管するのでということでありますが、今日の質問ということでの仕切りだったのか、もう今後の常任委員会としての事務の扱いの中で、それはもう全てそちらに委ねてしまい、建設委員会では対応しないということなのか、すみません、そこだけ確認を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、そこは決定事項だと思いますのであれですが、私は無所属で特別委員会には出る立場にありませんので。情報は区議会事務局からもらうにしても、常任委員会あっての、それを補完する意味で特別委員会の存在があるのかなとも思えますので。これは議会運営委員会の場で発言もできない立場としては、どこで申し上げていいのか分かりませんけれども。これは要望でよろしくお願いします。","respondent":"新妻委員長","answer":"分かりました。正副委員長、事務局側と検討しますのでお願いいたします。ほかにいかがでしょうか。","voiceIndex":87,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"すみません、１点だけご答弁いただいていなかったと思うので、再開発組合の名簿というのはもらえるのですかという。もらえるのか、それとも見ればもう書いてあるからそこを見なさいというのか。そのある場所を教えてもらえればありがたいのですけれども。","respondent":"中道都市開発課長","answer":"組合の名簿ですけれども、基本的にはやはり組合のほうに聞いていただいて、それが定款に沿って出せるものかどうかというのは組合のほうの判断になるです。","voiceIndex":89,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"欲しかったらこちらからその組合にアクセスをして、いただけないでしょうかと問うわけですね。でも、その聞く場所が分からないと聞けないのですけれども、その情報提供はしていただけるのですか。ここに聞くといいか悪いかの判断ができます程度の情報提供はしていただけるのでしょうか。","respondent":"中道都市開発課長","answer":"その際は都市開発課まで、まずはご連絡いただければ対応します。","voiceIndex":91,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり関係権利者でもそういった見られないという在り方はおかしいと思うので、そこは改善をしていただきたいと要望しておきたいと思います。それで、防災まちづくり部のところで伺いたいのですけれども。この間樹木が結構伐採されてしまうという問題もありますので、そこをぜひ、樹木をちゃんと保存していくというところでやっていっていただきたいと思うのですが、そこのお考えを伺いたいと思います。","respondent":"高梨公園課長、平原防災課長","answer":"そのような声が多いということは公園課としても把握していますので、先ほど述べたような形で進めてまいりたいと考えています。こういった中で、風水害対策の在り方であるとか、あるいは現在も行っておりますしながわ防災学校をはじめとした住民への啓発、さらには、先ほど防災体制整備担当課長からもお話しさせていただきましたが、備蓄物資の輸送体制の強化。","voiceIndex":94,"id":"exchange-016"}]},{"id":"topic-03","title":"品川区自転車活用推進計画策定に向けた検討状況","agenda":"品川区自転車活用推進計画策定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"第２回の協議会が行われたということで、ご説明がなかったと思うのですが、どういった議論、意見があったのかを伺いたいと思います。その下のところに、目標の案ということですけれども書かれておりまして、この中に「にぎわいを創出する」というのが書かれているのですけれども、これは具体的にはどういう意味なのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ある意味２と３はそれほど大きな順番で差をつけているわけではなくて、同格。ご指摘のとおり、１番「まもる」交通安全というのは一番という認識ですが、そうした意味合いで記載をさせていただいているところです。","voiceIndex":101,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料５の最後のページ、２５ページ、整備形態の選定ということで様々書いてあるのですけれども、この中で、住民が危険を感じる道などを参考に、道路空間の再編成も可能であれば検討するということで書かれておりますけれども、私も先ほど言いましたウォーカブルなまちづくりということであれば、車ではなくて、やはり歩行者、自転車の空間をしっかり確保していくということが必要だと考えていますけれども。","respondent":"鈴木都市計画課長","answer":"ネットワークには今回まず案の中では、例えば事例として出していただいた戸越銀座商店街のネットワーク上は案には今入ってありますが、ここについてどういう整備形態なのか、あるいはどういう安全対策のための取組をしていくかというところは。","voiceIndex":103,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"例えばどういうところがそれに当たるのかというのがあれば伺いたいと思います。それというのは、空間を再編成するということですね。今回この結果の中にも、中延とか武蔵小山の商店街は自転車の通行を禁止しているということだったのですけれども、戸越銀座商店街とかの規制とどう違うのか、何が違うのかを伺いたいと思います。","respondent":"森道路課長、鈴木都市計画課長","answer":"そういった再編成ができる区間というのはなかなか少ないとは思いますけれども、例えばこういったところがありますので、今後も自転車と歩行者の方が安全に通行できるような空間として整備を進めてまいりたいと考えています。何か各商店街で法的な違いがあるのかというところではございませんで、各商店街ごとで独自に取り組んで、区民の利用者の方にご協力をいただいている取組です。","voiceIndex":105,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、駐輪場のところなのですけれども、まず確認で、資料３のところですけれども、課題のところで様々書いてあるのですが、車種に対応した駐輪スペースの再配分が必要ということですとか、その下の大型自転車の駐輪スペース確保が必要ということとかは、これは似たような同じような印象を受けるのですが、取組として、対策として違うことをやっていくということなのか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長、工藤交通安全担当課長","answer":"資料３の自転車駐輪環境のところで、車種に応じた駐輪スペースの再配分、大型自転車等々の対応、これは資料全体にわたって非常に似たような表現。まちづくりの中での計画ですとか、そういった際に積極的に検討、ご相談をさせていただいて、設置に前向きに取り組んでいきたいと考えております。駐輪場の整備につきましても、必要なところにしっかり様々な、再開発という話、まちづくりという話もございましたが。","voiceIndex":108,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、短時間無料の件なのですけれども、今は考えていないということで、無料にするとそれ以外が増えて買物短時間利用の方が使えないというお話でしたけれども、そうであればさらに駐輪場を増やしていくということが本来の解決策だと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"駐輪場の整備の在り方は、行政だけではなくて、商店街あるいは民間、まちづくりの中で総合的に進めていくというところが重要かと思いますので、そうした記載を計画の中でもしっかり行っていきたいと思います。","voiceIndex":112,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"例えば、資料の５のところの２１ページ見ると、ネットワーク整備対象路線というのがあって、この紫というか青いところか、そこがネットワーク整備対象だと言っているのですが、だからこれをどうするのですかと。これを整備してどうするのですか。ただ、拡幅した後には無電柱化ですかね、それをやるよという話もあるのですけれども、では電灯とかどうするのとかといろいろな課題があるのですよ。","respondent":"森道路課長、鈴木都市計画課長","answer":"ソフト面につきましては、交通安全担当のほうで様々な啓発活動であったりとか、それから電柱に巻き看板をつけるとか、そういったことで整備を進めておりますので、それぞれ両課で連携しながら進めていきたいと考えております。やはり商店街のほうでまずは駐輪場の対応をしていただくというのが基本ですが、この計画の中で商店街の連合の方も入っていただいていますし、いろいろな意見交換もしておりますので、何か方向性なり考えていける対策。","voiceIndex":115,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"だって、これだけ自転車を活用していくというのはもう当たり前の生活の中の１つですから、そうなってくる。生活のために使っているということであれば、そこの分析をしなければ、何のための活動、計画策定なのですかということになってしまうので、もう少し生活実態を踏まえた計画にしていただきたいと強く要望したいと思います。それから、商店街の方々もしっかり見てほしいのですよ。１５０円出さなければ。","respondent":"鈴木都市計画課長","answer":"そこはもう方向性としてははっきり出していきたいです。それから、様々な視点でご意見いただきましたが、今後進めていく中でどう計画に反映していくかも含めて検討していきたいです。","voiceIndex":118,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません、時間も経過しているので端的にお伺いしますが、アンケートを取った時期が去年の１１月、１２月、そして今年の１月、２月という時期だったので反映されてないのは致し方ないと思いますが、ヘルメットの関係が載っておりません。あるいは努力義務期間中はなしでもいいよとしてしまうのか。ちょっとそこの視点と。すみません、その点をお聞かせいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"この計画策定が残り１年切ったところで改めてアンケートを取るという予定はございませんが、区のほうで補正予算でヘルメットの促進に向けた助成をしていますので、その利用ですとか、そうした状況を踏まえながら。","voiceIndex":121,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"補助２９号線の関連でちょうど商店街と重なってしまう、その後、その整備後の形態をどうしていくべきかという、商店街の方の声として、これは確かにそういう視点もあるのだなと思ったのが、歩道をしっかり確保してほしいと。その理由は、自転車で来るお客様が歩道に自転車をとめて買物していただきたいからとか、あるいは車道側から歩道に自転車がスムーズに乗り入れられるような形態にしてほしいという。","respondent":"鈴木都市計画課長","answer":"３回目ではそうしたご意見も紹介しながら。なかなか全てのお声を拾うというのは計画上難しいわけですが、できるだけどういう形で計画のほうに反映していくかというのはしっかり考えていきたいです。","voiceIndex":123,"id":"exchange-025"},{"speaker":"若林委員","kind":"確認","question":"今回この推進計画策定に向けてなのですが、これは誰の目線で計画をつくろうとされているのかという、そこらの考え方だけちょっと一回確認。","respondent":"鈴木都市計画課長","answer":"基本的に区民の目線でという計画です。","voiceIndex":126,"id":"exchange-026"},{"speaker":"若林委員","kind":"質問","question":"資料ナンバー１の前回協議会の補足資料というのが、今日説明はなくても結構なのですが、ご意見を一部抜粋という形で出ていますけれども、例えばこのご意見はどなたから出されているご意見ですかという。さっきの関連ですけれども、そこら辺、区民の目線というところで最終的に計画を策定しましたというところは、どういうふうにこれから進められていくかなという考え方をまたもう一回お聞きします。","respondent":"鈴木都市計画課長","answer":"学識の経験の方も他自治体で様々な計画策定に携わっているのと、それから、自転車の研究を非常に進めていただいていると、ある意味区民目線でいろいろな取組を行っていただいていると、そうした中でもご意見をいただいているというところで。","voiceIndex":128,"id":"exchange-027"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、避難場所が開設されて９人避難されたということで、この中で泊まった方がいたのかどうか。いたとすれば、以前の台風の避難所開設で飲物とか毛布とか出さなかったというのがあって、その場所の環境として悪い状況だったということで、今回そういった対応ができたのか伺いたいと思います。","respondent":"平原防災課長","answer":"今回の対応につきましては、委員ご指摘がございました水、食料でありますとか、毛布、いずれも備蓄物資をしっかりと供出させていただきまして、そちらをご利用いただいております。","voiceIndex":136,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4378#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":61585,"voices":141}},{"id":"r05-20230612-9","meetingId":"r05-cm06","date":"2023年6月12日","dateIso":"2023-06-12","committee":"文教委員会","time":"午後 １時００分～午後 ５時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"もう一つは、この教育目標などの点なのですけど、教育目標と基本方針の中に、品川教育ルネサンスという言葉は出てこないのですが、冒頭のこの目標、方針と、この７ページにある教育ルネサンスという、この関係、どんな関係性にあるのかというのをちょっと伺いたいと思います。","respondent":"中谷指導課長、米田教育次長","answer":"今回、年度初めに、４月７日に学級編制で改めて、クラスの決定というところを区として行うのですけれども、その時点で、数件、学級の増ということによって、先生が必要だという対応をした案件があったのですけれども。対しまして、品川教育ルネサンスにつきましては、特に教育委員会全体の中での学校教育の方向性について主にまとめたもので、これまでの変遷も含めて記述しているものです。","voiceIndex":38,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"その担任本来が当たるべき正規職員の方ではなく、専科ですとか非常勤とか副校長等で対応している事例は今はないということでよろしいのかという確認をさせてください。第一段落のほうなのですが、ちょっとこの記述についてお伺いしたいのです。プラン２１が子どもにとって顕著な成果を上げたというふうには、あまり教育委員会としては認識していないということなのでしょうか、伺いたいと思います。","respondent":"中谷指導課長、米田教育次長","answer":"そのようなことが年度を通じまして起きたときには、速やかに対応するということでやってまいりたいと考えています。７ページのIIの１のところですが、特に記述は前年度と変えているものではございませんけれども、品川区の教育が、いわゆる。","voiceIndex":41,"id":"exchange-002"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねします。２４ページの学事制度審議会、今年度ということですが、そのスケジュール的なところが分かれば簡単に教えてください。それはどちらの小学校あるいは中学校でしょうか。教えてください。それからあともう一つは、ページが分からないのですけど、共同の部活動について力を入れていくということなのですが、今年度、どんな感じで進めていくのかを簡単で結構ですからお願いします。","respondent":"柏木学務課長、中谷指導課長","answer":"私のほうから学事制度に関わるスケジュールの話ですが、学事制度ですが、来月７月に第１回を開催するということで現在準備を進めているところです。ですので、諮問文等についても現在検討しています。部活動の状況ということですけれども、こちらは来月の文教委員会のほうでご報告をさせていただきたいというふうに考えております。","voiceIndex":45,"id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"なぜ子育てで選ばれる品川というのを子育て支援の目的にしているのかを伺いたいというのが１点です。それと、１０ページのほうなのですけど、下から１０行目に「今後は保育施設等のあり方など保育供給体制の適正化を進める」と書いておりますが、この適正化をするというのはどういうことでしょうか、伺いたいと思います。それを確認させてください。","respondent":"柏原子ども未来部長、今井保育教育運営担当課長","answer":"安心して子育てができるといったところで、ほかの地域の方であったりとか、そういった方々も、しながわであれば安心して子育てができるというところで、安心感を持っていただける、そういった子育てを施策として進めている品川区なのだ。１点目が、適正配置についてはどういう内容を意味するのかですけれども、保育施設等のあり方など、保育供給体制の適正化を進めるというところを論点にいたしまして。","voiceIndex":60,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"子どもの数に合わせて保育園を減らすということになれば、この面積基準や戦後ずっと変わっていない保育士の配置基準など、そういう子育ての質の強化という点でも、あとその少子化対策という点でもやはり逆行するのではないかと思うのですけど、これ最後の質問なのですが、適正化の下での認可保育園を減らすということはやはりやめるべきだと思うのですけど、いかがでしょうか。","respondent":"今井保育教育運営担当課長","answer":"もう１点ですけれども、適正化というのが、保育園を減らしていくのかどうかですが、質の向上とかも含めまして、今後、保育園に求められていく役割ですとか、あとは、今後の保育需要がどう変わっていくのかというところも、もろもろ含めまして、今後。","voiceIndex":63,"id":"exchange-005"}]},{"id":"topic-02","title":"教育委員の公募","agenda":"教育委員の公募","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の選考ですが、１０月の頭で任期が切れる方が１名いらっしゃるので、１名ということの公募ということでいいのかということと、それと、選考というのは誰が行うのか、どんな基準で行うのか、選考委員会のメンバーを教えてください。何を重視するかなどの選定基準、これは決まっているのでしょうか。伺いたいと思います。","respondent":"宮尾庶務課長","answer":"１点目、今回は委員のお見込みのとおり、この１０月で任期が満了となる委員が１名おりますので、その方の後任ということで、１名の公募となります。それから、選考に関する基準、メンバー等々ですが、これはまさに今、こちらの基準を、策定を最終的にしているという段階です。","voiceIndex":69,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"メンバーについても策定中というか選考中ということなのでしょうか。これから、公募をもう６月に始めて、今後締切りと、選考は７月ですけど、このタイミングで、今日この文教委員会で選考基準何も教えられませんというのは、ちょっと、ではいつ教えてくれるのですかというか、私たちとしても意見の言いようがないというか、全く決まっていないのでしょうか。伺いたいなと思います。","respondent":"宮尾庶務課長","answer":"繰り返しのご答弁になってしまいますが、メンバーそれから選考基準等々につきましては、現在、区長部局のほうで検討中であるというふうに聞いてありますので、今お示しできるのは、この資料に記載をしています。","voiceIndex":71,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"確認したいのですけれど、今まで教育委員の方を区長がある程度選んで、議会のほうに同意を求めてきたのですが、そこに至るまでの委員の選考の過程を教えていただける範囲で教えていただきたいと思います。それが１つ。それで、保護者の方を公募するということは、今の選考の仕方、つまり選任の仕方のどこに問題があって、それをどう改善するために公募するのかということをお尋ねします。","respondent":"宮尾庶務課長","answer":"なぜこの公募に至ったかですけれども、ちょっと資料と重複をしてしまいますが、これまで以上に、様々な諸課題に対して幅広い視野、それから柔軟な思想を持った方というのをこれまで以上に取り入れていくという必要性から、今回の公募を実施するに至ったです。","voiceIndex":74,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つは、仮に適する方がいらっしゃらなかった場合はどうするのか。これは区費教員のときも一緒なのですけど、その中からどうしても人を選ぶのかというところの議論があるかと思うのですが、その辺りについて、実は文科省の公募についての課題という、いろいろなポイント整理の中に出ているのですけど、そこの点についてはいかがでしょうか。","respondent":"宮尾庶務課長","answer":"今回は、委員のお話のとおり、応募者の中から決めするということを前提に考えていると聞いております。それから、適任者がいなかった場合ですが、委員のお話ありました、その国の考え等も踏まえてやっていくものというふうに捉えているところです。","voiceIndex":76,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ、今のことに関して、これはでは、今回のこの公募について、教育委員会はどこまで関与するのでしょうか。今のご答弁を聞いていると、基本的には区長部局がやるということで、教育委員会の関与はほとんど見られないのですけど、どこまで関与しているのかだけ改めて教えてください。","respondent":"宮尾庶務課長","answer":"これもまだ、どうなるかというところはあるのですが、例えば選考の中で、あるいは教育委員会のほうに何か依頼があるということも想定はされます。まだ、この辺は、それも含めて今、区長部局のほうで検討中であるというふうに聞いてあります。","voiceIndex":79,"id":"exchange-010"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと１点確認したいのですけど、今回の教育委員の公募について、いわゆる定例の教育委員会があるではないですか。そこでこれまで議題として出たということがあったのか。それはどんな審議があったのか、なかったのか、あったとしたらどういうような意見が出たのか、ない場合はこれから審議とかの予定があるのか。そこも含めてお願いいたします。","respondent":"宮尾庶務課長","answer":"これまで、教育委員会での取扱いですけれども、これまで議題等として出たことはございません。明日開催予定の教育委員会の定例会において、ご報告という形で委員の皆様にお話をするという予定です。","voiceIndex":82,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"１点だけ確認させてください。もう６月ももうすぐ半ばというところで、どこにどう向けて公募するのでしょうか。すみません、初歩的なことなのですけれども、どうしてもその応募者の中からメンバーを決めるとなると、しかるべき方にはぜひ公募に応じていただきたいというふうに思うのですが、その辺、どのような形で公募をされるのかを知りたいです。","respondent":"宮尾庶務課長","answer":"その辺は、どのような形で公募を具体的に行っていくか、それからどのタイミングでというところも含めて、今まさに区長部局のほうで詰めているというふうに捉えておりますので、そこのところはそのようなご理解でお願いできればと思います。","voiceIndex":85,"id":"exchange-012"}]},{"id":"topic-03","title":"文化財の指定・登録","agenda":"文化財の指定・登録","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それとあと、審議会があるのですけど、この２つが具体的に、指定の対象にという候補として挙がると思うのですが、審議会の中で審議もされるのかなと思うのですけど、挙がっていく過程というのですか、どういう流れでこういう候補になっていくのか、その辺もし分かれば教えてください。","respondent":"宮尾庶務課長","answer":"それぞれここに至るまでの過程、経過ですけれども、石積護岸に関しましては、前々からこちらにこういった貴重なものがあるということは、私ども区のほうでも認識をしておりました。","voiceIndex":91,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。今後、そういうのも担当の所管とも連携していただいて、より区民の方に分かってもらえるようなことをしていただきたいと思いますので、これは要望なので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-014"},{"speaker":"吉田副委員長","kind":"質問","question":"先ほどのご説明で大体は分かったのですけども、結構これ、要は個人の所有権とか私権が制限されるのではないかということを、私の会派でも懸念の声が出たのですが、それで先ほど、補強とか、ここに影響がないような形で新築していただいたとかいうときに、全てやはり所有者さんの思いで、要は、区としても何か、これを残すための補助とかが今後もあるのかとか、それからこれからも残すとなれば、やはり。","respondent":"宮尾庶務課長","answer":"それ以前に、もちろんオーナーさんからいろいろなご相談事がおありかと思うのですが、その際は区のほうでしっかりと丁寧に対応させていただきたいというふうに考えております。","voiceIndex":98,"id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問","question":"もし、同意があれば、今後もそういう、区としての補助金とかということも想定しながら指定をお願いするということでよろしいでしょうか。それで、今後ですけど、相続とか発生しますよね。多分というか、いつか必ず発生すると思うのですが、そういうときにはまた、相続する人との協議とかということが行われると理解してよろしいのでしょうか。","respondent":"宮尾庶務課長","answer":"当然その手続の過程で、現オーナーとそれから相続をされるオーナーとの間で、もちろんそこでしっかりと引き継いでいただくのが望ましいことではあるのですが、場合によっては私どもの区のほうがご相談に入らせていただいて。","voiceIndex":100,"id":"exchange-016"}]},{"id":"topic-04","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"源氏前小について伺いたいのですが、建て替える前と後というのは、延床面積はどれぐらい変化があるものなのか。校庭の大きさというのはどんな変化があるのかというのをお伺いします。以上４点伺います。","respondent":"森学校施設担当課長","answer":"最後に一足制なのですけれども、こちらの学校はできればその一足制を導入したいというふうに考えてございまして、１階の平面のところをご覧いただきますと、昇降口の所が、今までですと下足入れの部分がかなり大きい面積を占めていたのですけれども、この辺を合理化いたしまして。","voiceIndex":106,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、ぜひ、その検討に当たっては子どもの声を聞いていただきたいと思うのですけど、いかがでしょうか。","respondent":"森学校施設担当課長","answer":"そちらにつきましてもアンケートを取りまして、実際どうなのかというところは、児童・生徒に聞いてまいりたいというふうに考えております。","voiceIndex":108,"id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２点質問をします。それで、グラウンドも広く多分使われて、とても使いやすくなるのかと考えていますが、これ、人工芝になることによって、ここは荏原第四地区の拠点になっている、夏まつりであったりとか総合防災訓練とかあると思うのですけども、今実施段階で、これからご検討なされると思うのですけども、それは実施の方向で考えていいのかということだけ、その１点お聞きしたいと思います。","respondent":"森学校施設担当課長","answer":"旧校舎だと分かっていますので、恐らく間違いなく出てくるだろうというふうに想定をしております。ですので、埋設物の撤去の期間も見込んでおりまして、解体、撤去をしていくという考えです。","voiceIndex":111,"id":"exchange-019"},{"speaker":"ゆきた委員","kind":"確認","question":"こちら、図面を確認しますと、体育館が２階に計画されているのが確認できますが、体育館は避難場所として開設して、開放されることになると思われます。２点目として、すまいるスクールの位置が確認できなかったので、こちらも分かれば教えていただければと思います。","respondent":"森学校施設担当課長","answer":"すまいるスクールなのですけれども、今現在検討している段階でございまして、１階の多目的室のところか２階かというところで今、検討しています。すまいるスクールがないということはございません。","voiceIndex":114,"id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、問題は、非常に騒音とそれから臭いがすごくしてきて、授業についても差し支えがあるということなのですが、そういうご意見を持たれた方はどこにどういうふうに、教育委員会事務局でいいのか、その辺確認させていただきたいのですけど、いかがでしょうか。","respondent":"森学校施設担当課長","answer":"基本的には騒音、振動が少ない重機を使ったりですとか、臭いの少ない材料を選定してはいるのですけれども、どうしても近いところで工事を行っておりますので、そういう問題も起きてしまう場合もあるかと思いますけど、その際は庶務課のほうにご連絡いただければ対応いたします。","voiceIndex":117,"id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問","question":"分かりました。それで、具体的にはなるべく騒音がないような形でという一方、やはり工事ですからどうしても騒音はね、だからその方もそれは想定しておられるのですけど、具体的にもお子さんが授業の声が聞こえないと。もっと詳しくは当事者の方にご相談するように言いますけれども、もし、今の段階でご見解とか何かあれば伺いたいと思いますが、いかがでしょうか。","respondent":"森学校施設担当課長","answer":"今、工事期間中でもコロナの対応で、もう今は減ってきているはずなのですけど、窓を開けていたりということもあったのかなというふうに思ってあります。","voiceIndex":119,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"設計などは順調にいくと思うのですけど、工事がどうしてもずれ込んだりしていると思うのですが、現在工事を３校でやられているのですけど、それぞれどれぐらい工事がずれ込んでいるか、計画どおりいっていれば計画どおりなのですか。そして、今後の見込みをそれぞれお願いします。","respondent":"森学校施設担当課長","answer":"細かいところでいきますと、２週間ほど遅れていたりというのはありまして、それにつきましては、基本的には土曜日、日曜日、祝日休みなのですけれども、少しその辺は作業をさせていただいて、工期を巻き返すような努力をしているような状況です。","voiceIndex":122,"id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"確認","question":"ということは、ここで資料いただいた校舎完成など、事実上校舎が完成することがやはり、在校生にとっては日常の授業の確保になるので、ここの浜川小学校、第四日野小学校、浜川中学校、校舎の完成はこの予定どおり、現状で考えるといけるということで確認、もう一度お願いします。","respondent":"森学校施設担当課長","answer":"委員のお見込みのとおりです。","voiceIndex":124,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"は小学校なのですけど、クラスの標準の３５人学級よりも細かく分ける措置をしているのが第四日野小学校ということですね。逆に、クラスを増やさなかったのが八潮学園と。昨年までは、三木小学校で３５人学級からさらに細かく、小さいクラスにしていたのですが、それは何かなくなってしまいました。そういう弾力的運用を申請というか相談してきた学校というのはほかにはなかったのか伺いたいと思います。","respondent":"柏木学務課長","answer":"八潮学園ですが、こちらは年度当初に急な転入がございまして、そのため、本来ならば学級増なのですけれども、学級の整備に時間を要するということで、学級数を増やさない弾力化という形を申請してまいりました。ほかに申請があったのかということですが、ほかにはございません。","voiceIndex":130,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"そうですか。何でこんなにそういう申請が少ないのか伺いたいというのが１つ。先生の負担も重くなりますし、教育環境の向上の点では、これは、保護者の立場としてもクラス分割してほしいと思うのが当然だと思うのですけども、なぜこうした選択になるのか、この選択についてはどういう理由でこういうふうにしているのか、つかんでいらっしゃいますでしょうか。","respondent":"柏木学務課長","answer":"弾力化の件ですが、こちらは当然全ての学校が知っています。その上で、学校の実情に応じてですので、学校の実情として細分化の必要がないという判断をしているから申請がないものと考えております。教育委員会で何校までということを決めているということはございません。","voiceIndex":132,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"私自身もそう思います。それで、伺ったのは、なぜ、この全ての学校でこういうふうな選択をしているかというのは、特に、学級数を増やさなかったところというのは、区教委としてその理由をつかんでいますか、知りたいのですけど、という、それぞれつかんでいたら教えていただきたいと思います。","respondent":"柏木学務課長","answer":"ただ、学校の考え方としては、学級増を選ぶところもありますし、加配のところもありますけども、加配のところはある意味、フリーな教員がいて、いろいろ、担任としてではないけれども教科担任とかという関わりの中でいろいろ動けて、子どもたちの相談に乗ったりとか。","voiceIndex":134,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は今、議員として話をしていますけども、保護者の立場からすると、何で自分の子どもがもっと緊密な、少人数学級の関係の中で日々の教育を受けられるべきところが受けられないのかなというのは、私はちょっと理解ができないので、保護者が分かるように、そこは少なくとも、どんな実情があるのかというのをきちんとつかんで報告をしていただきたいというふうに思いますので、今後ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-028"}]},{"id":"topic-05","title":"します。 ──────────────────────────────────────────── (5) 令和５年度 新入学学校別増減要因一覧について 次に","agenda":"します。 ──────────────────────────────────────────── (5) 令和５年度 新入学学校別増減要因一覧について 次に","exchanges":[{"speaker":"せお委員","kind":"意見","question":"ちょっと１点だけ、この指定校変更についてなのですけど、これ、言える範囲でいいのですが、結構私としては数多いなと思ったのですけど、学校別とかではなくてどういった理由があるのかというのを、もしお話しできましたらお聞かせください。","respondent":"柏木学務課長","answer":"指定校変更の理由は様々ございまして、指定校変更の許可基準というのが５つあります。","voiceIndex":141,"id":"exchange-029"},{"speaker":"せお委員","kind":"質問・要望","question":"すみません、突然聞いたので。私も以前から、委員会などで要望しているというか、指定校変更の品川区の基準は、今おっしゃったとおり５つあって、それがもう何十年と変わっていないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-030"}]},{"id":"topic-06","title":"令和５年度（６年度採用）品川区立学校教育職員採用候補者選考日程","agenda":"令和５年度（６年度採用）品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨年が４名程度採用をして、３０名を目指して採用したという報告が昨年もあったのですが、今回５名採用ということなのですが、これは３０名の目標を超えて採用するということなのでしょうか。それとも、やはり途中で退職されたりという方がいらっしゃった、あるいは４名の採用ができなかったということなのか、伺いたいと思います。","respondent":"中谷指導課長","answer":"今年度４月１日で２名の固有教員を採用しています。前年度末に退職者が３名おりました。したがいまして、現在、在籍者数が２５名というところになっておりまして、今回、５名程度を採用するという流れで進めしています。","voiceIndex":152,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、今なかなか、学校教員をめぐる環境は厳しいということで、別に区の採用に限らないのですけど、途中でやはり辞めざるを得ないという方も出てくる深刻な状況だと思います。採用を進めるのは結構なのですけども、やはり今は学校で働く教員の皆さんが長く続けられるような、そういった待遇面もそうですし、あとは働き方改革という点でも頑張っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、その次の段階として、区のほうの努力で、教育委員会の努力で、管理職に区独自の先生がなれる道筋をつくっていただいたのですけど、その次、つまり、校長先生、そこへの流れというか、現状、どのような、区として働きかけていく、東京都の考え方とか、あるいは法律との関係もあるのですが、その点の展望についていかがでしょうか。","respondent":"中谷指導課長","answer":"こちらのほうに、今一番候補となる方々が副校長先生でもいらっしゃいますので、こちらのほうに選考を受けていただくというところで進めていきまして、やがてはこちらの職になって、また。","voiceIndex":156,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"意見","question":"統括副校長先生になっていただくような選考ということで、すみません、私、分からないのですが、校長先生というランクの仕事というか職名との関係はどういうことになるのか、ちょっと分からないので。","respondent":"中谷指導課長","answer":"これまで、この校長という役職名をつけたいというところもありまして、東京都教育委員会のほうとの調整が非常に必要な案件でございまして、かなり、粘り強く、まずその６級職イコール校長というところで交渉をずっとやっておったのですけども、最終的には。","voiceIndex":158,"id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"意見","question":"いろいろありがとうあります。都との調整をしていただいて、そこまでのところまで来ているということですので、今後も期待するということで、東京都のほうの統括校長先生の仕組みというのに近いと言ったらあれですけど、そういうことを想定しているのだなと思います。今後も、都との調整はあれですけど、独自教員の先生方のキャリアの目標になるような仕組みが整備されていることを期待します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-035"}]},{"id":"topic-07","title":"令和２年に区立学校で発生したいじめの重大事態への対応","agenda":"令和２年に区立学校で発生したいじめの重大事態への対応","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"本当に大変重大な問題だなと。今回、いじめの重大事態の発生ということなのですけども、本区では、２０１２年の痛ましい、いじめによる自殺も起こっておりますが、その後このいじめの重大事態ということは発生していなかったという認識でいいのか。新たに、今年の５月にも重大事態だという報告があったということなのですけれども、こちらはどういうような事態なのか、これを簡単に教えていただきたいです。","respondent":"丸谷教育総合支援センター長","answer":"新たに、令和５年５月、今年の５月に起こったいじめを重大事態として認定したということですけれども、今後、調査が行われますので詳細は控えしますが、法に基づいて対応しています。","voiceIndex":168,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"いじめの重大事態という定義について、改めて区教委のいじめの重大事態とは何なのかと考えているかというのを教えてください。これはちょっと今資料ないのですけど、そういうふうに聞いています。そういう資料もいただきました。この区教委としては、区長部局にいじめの専門部署の構築をするということについては、どのように認識して評価しているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"対応する部署が、教育委員会だけではなくて区長部局にも設けられるということは、相談窓口が増えるということ、対応窓口が増えるということで、こちらとしては児童・生徒のためになるものというふうに考えております。","voiceIndex":170,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。ちょっと今後の対応、区教委の対応のところを見ますと、これを読みましたけども、これ自体は必要ではないとは言いませんし、必要なことだと思うのですけども、アとイとウですか。もちろん目指すべきです。いじめをしている子がいじめをしなくなるには何が必要なのか、この視点というのを対策の一番に入れるべきだと私は思うのですけども、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そのとおりだと思いまして、いじめはどんな理由があっても許されないという意識の向上というところに含まれると考えておりまして、まず、児童・生徒が、いじめの定義、いじめとはどういうものなのかというのを理解した上で、もしいじめ行為を行ってしまったら。","voiceIndex":172,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"それで、このアの部分だと思うのです。」と。それだけにいじめをやめるようにするには、こういうこの宣言とかで、いじめは駄目ですよ、と幾ら繰り返しても、いじめをやっている子どもがいじめをやらないようになるとは思えないのですけども、この点、なぜいじめ根絶宣言の決定が、子どもがいじめをしなくなることにつながるのか、そうなるのか、認識を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"この宣言を基に、各学校独自にいじめ根絶宣言というものを児童・生徒会を中心に考えておりまして、そういった取組をいま一度、また新たに充実させていくことで、教員だけではなくて、子どもたち自身も。","voiceIndex":174,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"これはまだ、中身は理解したかもしれませんが、こういう事態を何回も繰り返して徹底しても、いじめはなくならないのではないかなというふうに思っています。ですから私、言っているのです。この伺いたいのは、この説諭というのは一体これ、実際何が行われているのか。その説諭というのをもう少し中身を伺いたいですし、そして、ここにあまり書かれていないのはなぜなのか、併せて伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"こういったいじめ予防プログラムを改めて学校に周知しながら、実施の徹底を図っていきたいというふうに考えているところです。","voiceIndex":176,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"今ちょっとご紹介ありましたけども、その辺がここに書いてないというのはなぜなのか、伺いたいというのを伺ったので、聞かせていただきたいですし、もう少し、そういった内容がほかにもありましたら教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちへの教育的な視点で学校は対応してきましたので、できることならば、物理的な対応、対策、机の棚を外すとか、そういうことはしたくなかったのですけれども、加害の行為が止まらないということで、やむなく実施したという経緯もあります。","voiceIndex":178,"id":"exchange-041"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そんな中で、親だったり、警察を巻き込んで考えていかなければいけない時期に来てしまったのかなと思うので、教育委員会としてもそこは大きく政策判断をしていただいて、もちろん、学校に警察が入るというのはやはり異様な風景だと僕は思うのですけど、その異様な風景を生徒たちが見ることによって抑止力にもなってくる可能性も十分あるし、そのぐらい本当に、本気で解決をしていくという姿勢を教育委員会が。","respondent":"丸谷教育総合支援センター長","answer":"ですので、教育委員会としても、保護者にどういうふうに働きかけを行えばいいか、保護者、地域も含めて、いじめに対応できるかということは今後、課題というか検討して進めていきたいと思っています。","voiceIndex":181,"id":"exchange-042"},{"speaker":"せお委員","kind":"質問・要望","question":"ちょっと何点か。今、いろいろお話、質疑あって、ここに書かれている対策などはもう本当に、もちろんやっていただきたい。３点目、最後に、ＨＥＡＲＴＳなのですけど、以前は、ＨＥＡＲＴＳ全員、会計年度任用職員だったというお話を聞いていますけども、今どういう状況になっているのか教えてください。","respondent":"丸谷教育総合支援センター長","answer":"必要に応じて、関係の各所と協議をしながら、活用については、検討していきたいと考えております。","voiceIndex":184,"id":"exchange-043"},{"speaker":"せお委員","kind":"意見","question":"ＨＥＡＲＴＳに関しては、もちろん、会計年度が多いからといって成り立たないとは思わないですけど、でも、一応１年契約とかで皆さんがやっている中で、ＨＥＡＲＴＳという中での連携は取れるのかなというのは疑問に思うことがあって、もちろんＨＥＡＲＴＳを強化していくことが全てではないのですけど、一つの支援としてＨＥＡＲＴＳはすばらしい、皆さん助けられている機関ですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それが一番、防犯カメラというのは監視するのだったらもう絶対それは必要なことだと私は思っているので、ぜひ、今後そういうふうに含めて、やっていただきたい。それとあと地域です。地域によっても、品川区も当然地域性があると思いますけども、地域とＰＴＡ含めて、もう本当、協議体をつくって深掘りをしていただきたいと思います。私からはあれなのですが、もし何かあったらご答弁お願いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"やはり学校としては、組織的な対応ということが大切かというふうに考えておりまして、この引継ぎ事項、特に学年が上がるときとか、例えば小学校から中学校に校種がまたがるような事案も含めまして、引継ぎはしっかり行っていくということで周知徹底を図ってまいります。","voiceIndex":188,"id":"exchange-045"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今後、この令和２年の事案が解決とは言えないですけども、終わったと、一旦節目を終えて、品川区として、この傷があった、精神的にダメージのあった、この被害があった生徒に対して、今後他区に行ったから終わりではなくて、この生徒に対して今後どういうふうに対応を取っていただくのかといったところも、お考えがあればご回答いただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今後どういう対応を行っていくかというところですけれども、今後、区長部局のほうにも調査委員会が立ち上がって調査が始まりますので、そういったことも踏まえながら、真摯に対応していきたいというふうに考えております。","voiceIndex":191,"id":"exchange-046"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"この事案に対して、一番の問題といったところが、期日が空き過ぎているというところが問題だと思います。今後対応取るというような回答いただいていますけれども、真摯に対応していただくということはもちろんスピードだと感じていますので、こういった対応についてもスピードを持って対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それからもう一つは、いじめ防止対策推進条例第２１条の中で、区長部局に報告するという文言もあるわけですから、そのこと自体が念頭になかったのか、あるいはそれがあるけど、何らかの事情で報告が、重大事態という認定が遅れたのか、また、もう一つ、報告が遅れたのか、ちょっとそこの理由が、ご説明をいただいてないので、その点はいかがですか。","respondent":"丸谷教育総合支援センター長","answer":"区長部局への報告の不備ですけれども、区長への報告が必要ということは認識しておりまして、念頭にございました。事務手続が漏れていたということで、文書での報告ができていなかったです。","voiceIndex":195,"id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"確認","question":"それで、いじめ対策委員会の報告によると、公文書が４月１３日付の何号というふうにあるので、ここで正式に示されたと私は思うのですが、ホームページとそのいじめ対策委員会の不備があるということ自体から何か、いわゆるコンプライアンスというか、そこについてちょっと、現在もホームページに載っています、そういうのがあって、そういうところから、私さっき。","respondent":"丸谷教育総合支援センター長","answer":"教育長から品川区いじめ対策委員会の諮問の日付ですけれども、令和４年７月１３日ということで間違いはございません。ホームページにあります日付のほうは、確認をさせていただきまして、必要があれば修正します。","voiceIndex":197,"id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、しつこくて。今年の令和５年の３月２９日に総合教育会議も開かれていまして、そこで、教育委員会と区長部局、区長とお話しているわけです。その中の議題にないのです。というところも、非常に、両者が密接に語っていくというところがないので、そこでも報告はなかったのですか。これちょっと、総合教育会議の所管が違うからお答えできないのかもしれませんけども、お答えできる範囲で。","respondent":"宮尾庶務課長","answer":"総合教育会議、令和４年度は１回、ちょっと日にちまでは思い出せませんが３月に、区長部局と実施をしております。そのときに、特にこの議題に限ってというか、いじめに関する議題というのはありませんでした。","voiceIndex":199,"id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"提案","question":"令和５年３月２９日です。そこで、教育委員会としては、ここにあるように、大きな問題で、いろいろな課題をいじめ対策委員会のほうから提案されたわけです。なぜそのときに、教育委員会として説明や開催をその時点でなされなかったのかというところが、私は非常に疑問があります。その後、５月になって、区長と一緒に記者会見を開いたわけですけど、そこの経緯をちょっとご説明いただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"その後、区長への報告という段階になりまして、定例記者会見が５月にあるので、そこで併せて報告しようという流れでございまして、教育委員会独自に開催するというような、その時点では考えはございませんでした。","voiceIndex":201,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうではなくて、３月２９日に答申をもらって、教育委員会でも区長へ報告したわけですよね。教育委員会がこうやってきちっと対策も、いろいろ課題はありましたけどいじめ対策委員会も開き、こういう問題があって指摘を受け、今後も、冒頭おわびされていたようにしっかりやっていくというお話しているわけですから、私はそのこと自体は何ら責めるつもりはないです。すみません、もう１回お願いします。","respondent":"米田教育次長","answer":"その時点におきまして、教育委員会といたしましては、報告をまず、きちんとしようというようなところがございましたので、正直なところ記者会見というところの認識までにはその当時は至っていなかったというようなものです。","voiceIndex":203,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問","question":"だから、その独立性を持たなければいけないのに逆に、区長部局への報告が遅れるという、変な独立性とは言っていないのですけど、そこのところはそれを言ってはしようがないのですけど、ぜひ、教育委員会としての独立性を持った、そういう、特に発表のところ、聞いてもお答えいただけないのでしょうけど、教育委員会だけで発表をしないというふうに決めたのはなぜですか。そこは最後お聞きします。","respondent":"米田教育次長","answer":"お答えになっているかどうかあれですけれども、教育委員会といたしましては、きちんとこの問題について対処をしていこうということについては認識はしていたところですが、先ほど申し上げましたように、まずは、様々な関係者に対してのご説明を先にということで、ご指摘が。","voiceIndex":205,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、長くなりました。記者会見を教育委員会としてやらなかったかという話ではなくて、記者会見ではなくても発表の方法はあったので、教育委員会として、ぜひ、区長と一緒ではなくて、していただきたい教育委員会としての矜持というか、それを示していただきたかったと思って、すみません、長くなりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-054"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、いじめの認定というのは、訴えがあれば、基本的にはもういじめはあったとして認定されたという理解でよろしいでしょうかという確認が１つ。先ほどは、いじめは素早く認定されているので、現在、その重大事案に当たらないけれども把握しているような数が、教育委員会事務局としても把握されているようであれば、教えていただきたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"重大事態についても、この法令に基づいて、判断をその学校いじめ対策委員会、もしくは、こちらの設置者のほうで判断するということになっています。","voiceIndex":209,"id":"exchange-055"},{"speaker":"吉田副委員長","kind":"質問","question":"今のご答弁の中には、では今、いじめとは認定しているけど重大事態には至っていないというようなものの把握について言及がなかったのですけど、その辺についていかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"その中で重大事態に当たるか当たらないかの判断については、このいじめ防止対策推進法の２８条に照らして判断していくわけですけれども、今回、令和５年５月にそういった事案が発生しましたので、報告をしてこの後、調査報告に当たるという事例が１件あるです。","voiceIndex":211,"id":"exchange-056"},{"speaker":"吉田副委員長","kind":"質問","question":"結局重大事態かどうかも、学校の中でまず、判断があって上がってくるということでよろしいのですね、というのと、それから、そのいじめというものだけれども重大事態まで至らないというものについての、いじめと認定した段階でのその後の対応のやり方というのも、やはりこの学校のいじめ対策委員会の中で共有されて、教育委員会事務局にも報告が上がってくるという理解でよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"は学校での判断ということになりますが、学校から上がってくる報告を教育委員会で点検をしながら、これは重大事態に当たるおそれがある、疑いがあるというところでの、こちらの把握しながら学校と、校長とセンター長で話をしながらという仕組みを今つくっているところです。","voiceIndex":213,"id":"exchange-057"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"分かりました。これまでも、このいじめに限らず、やはり、子どもが安心して自分の立場に立って相手は聞いてくれるというような第三者的な機関というものの設置を求めてまいりました。それから、やはり、究極のところ言ったら、警察との協力というのは素早くやっているわけです。すぐに警察にということなのですが、警察でやったのは結局いじめ行為の停止という感じで、教育的視点は警察に求めるのは難しい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-058"},{"speaker":"高橋（し）委員","kind":"意見","question":"先ほどちょっと、最後聞き忘れたのですけれど、いじめ防止対策推進条例２１条で、重大事態が発生した旨を区長に報告しなければいけないというのですが、その区長部局の窓口はどこの所管になるのかということが１つ。それから、先ほどセンター長が、認識はしていたが文書での報告を怠ったというお話だったのですが、ということは、口頭での報告をどの時点でお話しされていたのかということをお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"区長部局への報告の窓口となるのは総務課です。今回新たな事案も総務課に書面で報告を上げております。当時文書報告を怠った、失念していたということでございまして、口頭でというところにつきましては記録が残っておりませんので、控えさせていただきたいと思います。","voiceIndex":217,"id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"確認","question":"総務課のほうが、今回も、次の調査委員会のほうの所管にもなっているので、そこと協力体制というのをしっかりとつくっていって、先ほどの、今後のということをやっていかなければいけないのですが、文書での報告は失念していました、口頭での報告は記録が残っていないので分からないというご答弁と確認させていただいてよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"そのとおりです。","voiceIndex":219,"id":"exchange-060"}]},{"id":"topic-08","title":"令和５年４月入園申請状況等","agenda":"令和５年４月入園申請状況等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それで聞きたいのですが、例えば、求職活動、求職というのは求めるほうです、この活動を休止している者ということで、保育園に入れないがために求職活動を休止した方は何名だったのか。育児休業を延ばした方は何人だったのか。認可外保育園、助成は受けているけど、認可外保育園に入っているから待機児とはみなされない方、何人なのかというのを伺いたいというのが１つ。五反田地区も多いほうですか。","respondent":"石井保育支援課長","answer":"続いての、保育提供区域別申請状況で、多い所と少ない所、それぞれありますけれども、不承諾者数の多い少ないということは申請者数の増減とかもありますので、そういったところが影響しているところではないのかなというふうに考えてあります。","voiceIndex":229,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"最後２点、お伺いして終わりにしますけど、ちょっとごめんなさい、特定の保育園等のみ希望している者で、全体というのですか、特定の保育園のみ希望している者という定義の中で全体の数は何人ですかということと、それと、来年、新年度に新たに、あるいは今年度途中でもいいのですけども、今年度途中あるいは来年の４月に新規増設する認可保育園の園数と定員数というのは。","respondent":"石井保育支援課長","answer":"続きまして、今年度の新規開設予定園ですけれども、現在相談を受けているところでございまして、決まりましたら改めて、この文教委員会の場でご報告をさせていただきたいと考えています。","voiceIndex":231,"id":"exchange-062"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今入っている方の対応というのでしょうか、そこをどのようになされているのか、行き先がなくて困ってしまうとか、そういうことはないのか、伺いたいと思います。","respondent":"石井保育支援課長","answer":"一方で、１歳児クラス、０歳児クラスにつきましては、転園の手続をこれから進めてまいるのですけれども、指数の２点加点ですとか、あとは、こちらのほうでもきめ細かな相談に乗りながら、行き先がなくならないよう努めてまいりたいと考えています。","voiceIndex":237,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、行き先がなく困らないように、ぜひ対応、相談など精いっぱいやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-064"},{"speaker":"安藤委員","kind":"意見","question":"児童相談所の件で、来年いよいよ１０月に開設なので、やはりちょっとしっかり調査していく必要があるかなというふうに思います。それと、あと、不登校の対策というか支援といいますか、ちょっとやはり、いじめと並んで、今の学校の一つの子どものつらさの反映かなと思っていますので、そういったところも調査できたらなというふうに希望したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":241,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどもちょっと、コロナの学級閉鎖の話ありましたけど、東京でも増えて、４週連続で定点観測が増えていますし、全国的にも同様なので、ちょっと感染状況を見て、その日程ですとか、あるいは開催の有無も含めて、機敏に正副委員長には柔軟に対応していただきたいと、今から増えた場合の中止の検討も含めて、その辺についてはお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":80359,"voices":244}},{"id":"r05-20230612-5","meetingId":"r05-cm06","date":"2023年6月12日","dateIso":"2023-06-12","committee":"総務委員会","time":"午後 １時００分～午後 ３時２９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。簡単に概要について伺いたいと思います。それが１つです。区民からも、議員からも、質問項目や、羽田のことが５問で、区政全般のことが５問など、概要の説明がありましたけれども、どのような設問になるのか。ぜひ、議会や区民のいろいろな意見を反映していただきたいと思うのですけれども、それぞれいかがでしょうか。","respondent":"佐藤（憲）企画課長、辻広報広聴課長","answer":"１点目のご質問にお答えいたします。区政運営会議の中身というご質問です。以前は、委員ご指摘のとおり、経営会議という名前で行っておりましたけれども、森澤区長就任に伴いまして、中身の方を改めて整理したというところです。全体としましては、８月ぐらいには発送して、調査を開始したいという希望で、今のところ、そのような予定でいるところです。","voiceIndex":76,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"区政運営会議は、森澤区長になって、その後、扱う事務が変わって、名前も変わったということですか。総務部ですけれども、これは課長に聞くのもどうかなと自分で思いながら聞くのですけれども、秘書担当課長というものができました。全国的にも、１自治体が制度としてここまで進めているというのはまだまだ珍しいという話も伺っておりますので、変わった理由や、何がどう変わったのか、伺いたいと思います。","respondent":"岡秘書担当課長、崎村人事課長","answer":"それと、区長が代わってということで、対外的調整ということにも力を入れていこうという形で、そういった対応でやらせていただいております。給与の部分については、２３区統一交渉事項ということもありますが、この３月に、例えば、退職手当や扶養手当といった手当の関係についても、このパートナーシップ関係の相手方を加えるということで労使合意がなされましたので、この先。","voiceIndex":79,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"引き続き、誰もが自分の能力を発揮できる職場や社会になるようにお願いしたいと思います。秘書担当課長、もう一言だけ。トップマネジメントとは何なのですか。その上で、ここがトップマネジメントの課というのは、私自身、なるほど、そのような考えなのかというと、とても端的な答弁でよかったと思うのですけれども、端的過ぎてしまってよく分からなかったので、最後にもう少しご説明いただきたいと思います。","respondent":"岡秘書担当課長","answer":"基本的に企画課、財政課といった課がありますので、区長が思ういろいろなトップマネジメントでやっていきたいことを企画課だったり、財政課だったり、それぞれ所管する課にスムーズにつなげていくところの調整だと考えています。","voiceIndex":82,"id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"企画部の組織を拝見すると、一番下のほうにデジタル庁と東京都デジタルサービス局というものが派遣という形であろうかと思います。ここは一体どういうものなのかということをご説明いただいてよろしいでしょうか。","respondent":"横田情報推進課長","answer":"昨年度からデジタル庁に１名、今年度から東京都のデジタルサービス局に１名派遣しています。デジタル庁の派遣につきましては、国のいろいろな動き、例えば、システム標準化などの動きがありますので、その辺りの調整をしております。","voiceIndex":85,"id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"どちらかというと、研修とまでは言わないですけれども、向こうに行ってもらって、帰ってきたときに、より品川区のＤＸなどの関係に資するような人材を育成しているという形でいいのでしょうか。","respondent":"横田情報推進課長","answer":"委員のおっしゃるとおりで、東京都やデジタル庁で学んだことを品川区に活かしていただくという目的で、派遣を実施しております。","voiceIndex":87,"id":"exchange-005"}]},{"id":"topic-02","title":"コンビニ交付障害等の経過と区の対応","agenda":"コンビニ交付障害等の経過と区の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"マイナンバーに関わってトラブルが続いているということで、多くの不安の声も伺っておりますし、やはりこういうトラブルは、人間が創り出した様々な技術やシステムですから、必ず起こり得るという立場でマイナンバーカードは普及すべきでない、やめるべきだということは、この間、述べてきたことです。少しその辺を伺いたいと思います。国の動きも併せてご説明いただきたいと思います。","respondent":"横田情報推進課長","answer":"その辺りの公表の時期になりますが、いつそのような公表があるかということは、まだ国から公表されていませんので、分かり次第、委員にお知らせいたしたいと思います。","voiceIndex":93,"id":"exchange-006"},{"speaker":"中塚委員","kind":"確認","question":"１つの事例として、ログアウトまで確認をしていたので、品川区では起きなかった。せめて国の対応策が出るまで、一旦中止というか、停止というか、コンビニ交付も含めて、区では問題は起きていないということですけれども、国の対応が示されるまで、一旦中止や停止をするという考えはないのか、伺いたいと思います。中止や停止のところだけ、質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"人的作業ということは、ミスがつきものなので、できるだけ保険証も併用してしばらく使えるとか、区としても、区民サービスを考えたときに心配だということを申し上げていただいて、すぐに変換するのではなくて、徐々にマイナンバーカードにひもづけするようなことを、しっかり区から国に言っていただきたいと私は思います。そういう問題まで起きている。これは大変な社会問題になると思うのです。意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"少し気になるのが、この公金受取口座は、例えば、奨学金などの受取りでも利用できて、そのように考えると、１種や２種の奨学金は、品川区は関係ないと思うのですけれども、品川区でも公金受取口座を世帯ではなくて個人で使っている場合があるとするならば、少し問題が出てくるかなと思うのです。今のところ、品川区としては、この公金受取口座を使ったものはないという理解でいいのでしょうか。お願いします。","respondent":"横田情報推進課長","answer":"そのカスタマイズをやる時間がないと言われていまして、前進できていない状況にあります。ですので、今、品川区におきましては、使っているものはないという答えになります。","voiceIndex":100,"id":"exchange-009"}]},{"id":"topic-03","title":"令和２年に区立学校で発生したいじめの重大事態への対応","agenda":"令和２年に区立学校で発生したいじめの重大事態への対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ご説明いただきました。区長部局としては、教育委員会の独立性については、どう担保しているのか。その独立性についての考えを伺いたいと思います。別の言い方をすると、区長部局が上で、教育委員会が下で、それに従うべきものという考え方では、お互いの役割を発揮できないと私は思っているわけですが、区長部局が設置する、いじめ問題調査委員会について、その位置づけを改めて伺いたい。","respondent":"勝亦総務課長","answer":"そういったものの中で、必要があると認めるときには、自治体の長は調査を行い、結果を議会に報告するという定めが法律にあります。そういった中で、教育委員会の独立性の部分はありますけれども、こちらにつきましては、法律の定めるところにのっとって設置し、行うものです。","voiceIndex":107,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"最後のところです。教育委員会の独自性はあるものの、法の定めによって設置するものだ。区としては、そこをどう考えているのか、もう少し伺いたいのですけれども、今、法律にのっとった設置だということは、ご説明で分かりました。どういう考えなのか。区の考えを伺いたいと思います。ただ、教育委員会の独立性については、区長部局はどう思っているのかというのを改めて伺いたいと思います。","respondent":"勝亦総務課長","answer":"教育委員会の独立性については、法の定めるとおりです。こちらの法に定める調査委員会ですけれども、そちらについては、教育委員会、区長部局がそれぞれの権限と責任の中で必要な措置を講ずるためのものです。","voiceIndex":109,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"それが法律で定められているということでいいのか、最後にその点を伺いたいと思います。でも、遅れの原因の解明だけで、子どもがいじめをやめることになりますかということを伺いたいのです。私は、子どもがいじめをしなくなるには、自分の行為を改めることが必要であって、遅れの原因に特化している理由、これで学校からいじめがなくなると区長部局は思うのか、そこを伺いたいと思います。","respondent":"勝亦総務課長","answer":"そういった中で、何でこういったことが起きたのかということに、今、問題意識が保護者の方は向いているということで、そのような形で、委員会のほうは対応を考えてあります。いじめの根本的解決につきましては、まず、学校・教育委員会において実施するべきものと考えています。","voiceIndex":111,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"なぜいじめが起きたのか。その答えの問いに、どうすればいじめをしなくなる、子ども自身の成長や、いじめをしている子どもがいじめをしなくなる。自分の行いを間違いだと認めることですから、「それは駄目だよ」、「はい、分かりました」と、そんな簡単な話ではないのが学校だし、教育だと思うのです。それだけに、いじめは駄目だと言っても、残念ながら、そういう言葉は子どもの心には響かないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは文教委員会で深めていただくということで、最後、意見だけを述べます。いずれにしても、保護者の方が、なぜ起きたのかということを知りたいと思うのは当然だと思いますので、ご意見に応えていただきたい。意見を述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"さんざん教育委員会でも、品川区の中でも、行政側でも、このいじめのことは、様々な会議体で発言されて、いじめ根絶宣言ということで動いていたわけです。ただ、何でこれが教育委員会にきちんと伝わってこなかったのか。でも、これがこんなに遅れて、こんなに大きな問題になるなんて、私には想像できないのですが、そこはしっかり解明して、今後に活かしていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"教育委員会ではないので、あくまで区長部局として確認していきたいのですけれども、今回、令和２年のお話についてはこれからだと思うのですが、先ほど、令和５年６月２日付で教育長から区長へ報告があったというお話がありました。これについては、報告の遅れなどは、現状、確認できないと聞いてよろしいのでしょうか。お願いします。","respondent":"勝亦総務課長","answer":"本件につきましては、学校から重大事態として報告が入ってきたものを速やかに区長部局に報告いただいているものです。教育委員会での調査は、今後、行う形になります。","voiceIndex":119,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"その調査結果については、議会に報告があるということでよろしいのでしょうか。","respondent":"勝亦総務課長","answer":"こちらの報告については、随時、教育委員会と連携しながら報告をしていく形かと思います。","voiceIndex":121,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません。区長部局でどういうことかというのを教えていただきたいと思います。だけれども、今回の場合は、精神的に適応障害になって、転校もされたという中で、本来なら、適応障害という精神的な病院にかかられた時点で、重大事態だったと踏まえて、だけど、重大事態で報告する、しないは別としても、学校も含めて、教育委員会も対応はしていたのですか。ここら辺だけ、少し考えを教えてもらいたいです。","respondent":"勝亦総務課長","answer":"いじめ当時の学校や教育委員会の対応です。こちらにつきましては、方針に一部書かれてありますけれども、学校、教育委員会では、いじめの解消に向けて丁寧に対応しています。","voiceIndex":125,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"確かに書いてあるけれども、それはそれで、そうすると個人を責めるようになっていってしまう。報告の部分は致し方なかったから、これは素直に謝らざるを得ないけれども、そちらの部分を、先ほど言った報告書がどうということを聞いているつもりはないんだが、とにかく全体ではやっている。何でそこをもっと前面に出してくれないのかなというところだけを聞きたいです。","respondent":"堀越総務部長","answer":"それは、第三者、外部の方を入れてしっかりと調査をしていきますので、そういった視点、ご意見をいただきながらしっかり調査していくということですので、品川区がこれまでやってきたいじめ対策に加えて、我々のほうでもっと意識しなくてはいけないというか、視野を広げて。","voiceIndex":127,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"最後に１点だけ。ぜひよろしくお願いしたいのと、調査委員会が設置されました。５月に設置済みだから、設置されたということで、この出口論はどのようになるのですか。それで、保護者の方に、これでよろしいですかとご理解をいただかなくてはならないのだろうけれども、その辺の出口論についてどう考えているか、教えてください。","respondent":"堀越総務部長","answer":"１つ視野に入れているのが、例えば、こちらにも書いてありますが、区長部局での部署の設置ということで、要するに早期発見・早期解決のために、この場合、少し言葉は難しいですけれども、漏れがないようにといいますか、より相談しやすい体制を作るといいますか。","voiceIndex":129,"id":"exchange-020"},{"speaker":"大倉委員","kind":"確認","question":"確認ですが、今まで様々お話を聞いている中で、早期発見・早期解決に向けて設置をされてというところで言うと、調査内容も1)から4)とありますが、これに沿うような人選がされているという認識でいいのでしょうか。部署設置の考え方と、人材の選定の考え方について教えていただければと思います。","respondent":"勝亦総務課長","answer":"委員の選定につきましては、こちらの下に書いてあります調査内容に沿う形での人選をしています。専門部署の設置を視野に入れた人選というよりは、調査をしていくための人選という形です。","voiceIndex":132,"id":"exchange-021"},{"speaker":"大倉委員","kind":"質問","question":"そうすると、この中でしっかりと調査がされていって、このスケジュールで見ると、調査結果を踏まえて必要な事項を講じていくというところでは、今回、様々、組織的な対応が不足してしまったことについて、何らかの具体的な対応もとりながら、今後、このようなことがないように、しっかりと進めていけるところまでの具体的な案が出てくるように取り組んでいくということでいいでしょうか。","respondent":"勝亦総務課長","answer":"もちろん、こちらの調査結果をまとめていただいた上で、区の組織として必要な措置が出てくるようであれば、それに対応する形で検討していく考えです。","voiceIndex":134,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"今回のいじめ問題調査委員会が５月に設置されましたということで、先ほどの事務事業概要にも、このいじめ問題調査委員会というものが記載されていて、記述によると、区長が必要と認めた場合に設置される。今回の事案が一体どうだったのかという真相を明らかにすると思えるのですけれども、その点について、いじめ問題調査委員会がなそうとしていることの１つの目的を最初に伺いたいと思います。","respondent":"勝亦総務課長","answer":"重大事態への対処です。重大事態の対処、また、重大事態と同種の事態の発生防止のために必要があると認めるときはという形になってあります。今、申し上げた過去の事案を再調査という意味では、今回の事態の報告について検証していくという考え方です。","voiceIndex":137,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"どういう位置づけになるのか。いじめ対策委員会との関係がどうなるのか。その上で、これまでの質疑の中でもいろいろ取り沙汰されているところはあるのですけれども、改めて、もう一度、もし区長部局がこういったいじめの専門部署を設置するとすると、教育委員会との関係性や位置関係、立ち位置の関係はどのようなものが適切と考えるのかということを伺いたいと思います。","respondent":"勝亦総務課長、堀越総務部長","answer":"先ほど、総務部長からございましたけれども、教育委員会で学校のいじめ対策については、従来もやってまいりましたし、今後も継続していくものです。そのような事例も研究しながら、今回の調査委員会の意見を伺いながら、よりしっかりとした対応を有機的に行っていくにはどうすればいいのかということを考えたいなというのが、今回。","voiceIndex":139,"id":"exchange-024"}]},{"id":"topic-04","title":"教育委員の公募","agenda":"教育委員の公募","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１つ目は、完全に私の不勉強で申し訳ないのですけれども、この教育委員の公募についても文教委員会に報告されているのですか。報告される予定だと、予定表を見たのですけれども、総務課が教育委員の公募について、ここで報告をする立ち位置が、私自身、分からないもので、今日は事務事業概要だから、総務課のところを見て、総合教育会議などが入っているから、まず、そこを少し説明いただけますか。","respondent":"勝亦総務課長","answer":"教育委員の選任につきましては、区長が選任いたしまして、議会にその同意を求めるものです。そういった意味で、議会等の対応を所管しております総務課で準備を進めてあります。","voiceIndex":147,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"この報告について質問したいのですけれども、今回、教育委員の公募をするということです。これまでの経過ということで、今まではこのような決め方をしていた。今回、それを公募にした。今までどのような決め方をしていたのか、改めてご説明いただきたいと思います。２３区、東京都、全国、よく分かりませんけれども、他の自治体の様子もお伺いできたらと思います。","respondent":"勝亦総務課長","answer":"そちらが参画する関心を高められるです。公募している自治体ですけれども、把握しております最新の情報ですけれども、文部科学省で発表しているものがございまして、全国で約４０自治体と聞いてあります。２３区で実施しているところはございません。","voiceIndex":149,"id":"exchange-026"},{"speaker":"中塚委員","kind":"提案","question":"今までどうだったのかのところだけ、もう一度ご説明いただきたいのです。もちろん知見のある方が任命同意として提案されて、議会でも議決してきたと私も思います。今までどのような方だったではなくて、任命同意を求めるに当たって、区長がどういう選考過程でその方をお選びになったのか。誰が選ばれたというよりも、どのような手順で、今まで任命同意を議会に求めてきたのか。改めてご説明いただきたい。","respondent":"勝亦総務課長","answer":"委員につきましては、地方公共団体の長の被選挙権を有する者で、人格が高潔で、教育・学術および文化に関する識見を有する者のうちから、地方公共団体の長が議会の同意を得て任命すると書いてあります。そういった形で、それに見合う方を選任してきたです。","voiceIndex":151,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も不勉強でごめんなさい。私もここのところ、ずっと総務委員会にいなかったので、分からないのですけれども、総務委員会には、必ず教育委員の公募が出ていたということですか。私のイメージでは、出ていたというイメージがなくて、今度、４０自治体で初めてこのような公募をしたということですか。そのやり方は変わっていないのだろうけれども、その部分の公募をしたというだけのことですか。","respondent":"勝亦総務課長","answer":"そういった中で、現状です。令和５年１０月１０日に、保護者で入っていただいております、冨尾委員が教育委員としての任期が満了いたします。そういった中で公募をするものです。","voiceIndex":154,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、冨尾さんで分かったのだけれども、今度、冨尾さんを代えるときに、今まではこのように総務委員会で出てきたのですか。公募はなかったと思っていて、先ほどの４０団体というのは、２３区では全くやっていないけれども、品川区としては、それを公募にします、それでやっていきます。だから、これはこれでいいではないですか。この目的のとおりなのです。","respondent":"勝亦総務課長","answer":"品川区としては、新たに公募を始めるということでの本日のご報告です。","voiceIndex":156,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません。２回目ですが、選考過程ですけれども、資料にあるとおり、一次選考を小論文、二次選考を面接とあります。この小論文を選考する人や面接をする人は誰なのか。候補者決定にあたって、選考委員会が開かれるのか。選考委員会のメンバーはどういう構成になるのか。この選考に関わって、メンバーや構成をご説明いただきたいと思います。","respondent":"勝亦総務課長","answer":"選考過程の委員につきましては、現在検討中ですけれども、人事、任用に関することですので、基本的には、公開していくものではないかなと考えています。","voiceIndex":159,"id":"exchange-030"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"皆様のご意見も、ぜひ伺いたいと思うのですけれども、先ほどの報告で教育委員の公募について、２３区では初めて、全国では４０自治体だということで、既に取り組んでいるところの事例や状況を、所管事務調査のテーマにすると、理解が深まるかなと思いました。教育委員の公募も１つの案かなと思いますので、ご検討ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、この行政評価は今ではないと思っていて、今やる話ではないと思っています。この辺のところは、質問でもやるつもりでいるのだけれども、ぜひ委員会としても、行政の方、職員の方が、もっとやる気を持って区民のために働けるような環境づくりを作るべきだと思っていて、そういうものを取り上げてほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ、すみません。やはり人事について、品川区もこれからＤＸ等々が進んでいくと思うのです。今回、国の職員採用に当たって、前倒しでやったにもかかわらず、あまり応募がなかったということを思うと、やはり何か取組を考えないと、多くの区民の皆様のサービスを守るためには、私は改善をしていかなければいけないと思いますので、ぜひ人事のほうをやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"少しいいですか。すみません。大井競馬場にいつも視察へ行くのですけれども、毎年、売上げが上がって、利益が上がって、もう我々が視察するに及ばないのではないかなという気がするのです。でも、委員長にお任せするしかないので、一応、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひ私は視察をお願いしたいと思っているし、もう一段、もしよければ、事前に１回、委員会の後でもいいので、ＴＣＫの副管理者とは言わないけれども、総務部長ぐらいはここに来ていただいて、総務部長でも、課長でもいいけれども、一緒に来ていただいて、特に今、現状はどうで、例えば、アニメのスタジオを造るとか、今度の駐車場はどのようにしていこうとか。","respondent":"せりざわ委員長","answer":"最後、行政視察についてです。今年度の行政視察の調査事項、視察先、日程等について検討していきたいと考えています。参考資料として、過去の視察先、調査項目についてまとめたものを事前にお配りしております。","voiceIndex":180,"id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"大都市の中で活動するという意味で、区民を見守っている品川区とすれば、やはり大都市の行政で様々な問題を抱えていると思うのです。そういう意味で、やはり近くの横浜、それから、千葉もそうですが、近々でそれぞれの行政の様々な問題を研究するということを、私はこれからやっていかなければいけないと思うのですが、一応、意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-036"},{"speaker":"中塚委員","kind":"意見","question":"今のコロナの感染拡大が、今後、どうなるのか。今、少しずつ増えていることもありますし、実施時期にどういう感染状況になるかは、なかなか見通せない部分もありますので、十分警戒をしながら、また、規模や日程についても、必要な感染症対策は講じながら、自分達で警戒をしながらやっていくという視点を持って、最終的には委員長の判断でよろしいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":183,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。そういう中で、議会は議会だけれども、経済効果、区内業者も含めて、民間も含めて、コロナが５類になった途端、基本的には、みんなどこも積極的。いろいろなところが全て積極的。それを超えてでも、経済効果がある、まちを盛り上げていくということは、積極的にやっていくべきだというのが、私の今の思いです。もちろん議会もそうしてほしいというのが私の考えです。それをお願いしたいと思います。","respondent":"せりざわ委員長","answer":"この委員会だけではなくて、全体を通して感染状況の様子は見て考える話だと思います。","voiceIndex":184,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":50244,"voices":188}},{"id":"r05-20230613-14","meetingId":"r05-cm06","date":"2023年6月13日","dateIso":"2023-06-13","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時２９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"新庁舎整備と庁舎跡地等の活用について、お伺いしたいと思います。それと、品川区庁舎跡地等活用検討委員会ですけれども、確認させていただきたいのですが、これは当然公開されるものということでよいのか、議事録も後に公開されるものということでよいのか、パブリックコメントは行うということでよいのか、そこを確認させていただきたいと思います。以上幾つか伺いましたが、よろしくお願いいたします。","respondent":"大友新庁舎建設担当課長、泉広町事業調整担当課長、山下新庁舎整備課長","answer":"二次審査につきましても、同様に２社で実施したところです。パブリックコメントですけれども、当委員会の内容につきましては、区民の意見をまずは広く受け止めまして、区民のニーズを整理するというところ、また。今回設計事業者として選定した事業者との契約の件数といったご質問だったかと思うのですけれども、今回設計事業としての契約は当然初めてということでして。","voiceIndex":45,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと裏面で、ワークショップを開催したということですけれども、この中身については、策定委員会の報告を検討していくと説明がありますけれども、３日間のワークショップでどんな意見が挙がったのか、どんな施設の要望があったのか、ご答弁いただきたいし、私も知りたいと思います。いずれにしても、このワークショップでどんな施設のご要望があったのか、それはちょっとご説明いただけたらと思います。","respondent":"大友新庁舎建設担当課長、泉広町事業調整担当課長、吉岡政策推進担当課長","answer":"この事業者の選定に当たりましては、評価の公平性であったり、透明性を確保するために、複数の外部有識者から意見を聴取し。今回ご説明申し上げました今年度から来年度の初めまでで行っていく検討の中では、区民の意見を広く受け止めまして、区民のニーズを整理するとともに。質問は前後いたしますけれども、こちらで挙がった資料、ワークショップの実施結果についてですけれども、こういった資料も公開をしますので。","voiceIndex":49,"id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"ですから、そこが基本設計に選定されるということは、あまりにも癒着が甚だしいと指摘しておきたいと思います。だからといって自分の個人情報がほかに流用されたり、悪用されたり、ましてや知らないところで使われていたりすることは決してあってはいけないと思いますので、デジタル化と併せて個人情報の保護について徹底していただきたいと要望して終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"私も以前から行財政改革特別委員会、また策定委員会等に関わらせていただいて、今回の外部有識者、恐らく大学の先生等については、審査の委員ではないけれども、オブザーバーとして意見を聞くという、ちょっと分かりにくい構造になっていたと思うのですけれども、まず伺いたいのは、大学の先生が何人でどなたなのかということを教えてください。","respondent":"大友新庁舎建設担当課長","answer":"続きまして、芝浦工業大学建築学部の村上教授は、建築の環境であったり設備、そういったところを専門とされている有識者となります。計４名の有識者にご参加いただいたという状況です。","voiceIndex":56,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"設計というのは非常に重要だと思いますし、これから５０年、１００年使っていく庁舎を誰が設計するのかということで、非常に重要なので、しつこく確認をしますけれども、ここに選定理由として、優れた提案であったということが３つ並んでいます。ですから、ある程度もうちょっと細かい情報を区民に対して、また我々に対して提供していただきたいと思いますが、いかがでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"公表につきましてですが、今回の結果は、明日からホームページにて、事業者名と選定理由を公表していく予定です。","voiceIndex":58,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＣＭの意味を、全くという言い方はちょっと適切ではないかもしれない、ＣＭとしての機能を果たしていないのではないのかなと思うのですが、まず、今回のＣＭは同じタイミングで選定されましたが、設計業務にも関わるということでいいのかどうか、今回三菱地所設計が取りましたけれども、今後こういうことが起きない、これから先、もし関わるのであれば、設計事業者、そして建設事業者に、品川区の意思。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"それを公表していくという前提でのプロポーザルを実施していないこともあり、公表は考えてございません。委員から最後にございました、しっかりと意思疎通を図った上で設計に臨んでいく、ＣＭを有効に活用していくという点につきましては、今後課を挙げてその体制で臨んでまいりたいと考えています。","voiceIndex":60,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。同じことはもう言わないので、区民の理解、また議会の理解を得られるようにご努力いただきたいと思います。最後に、ＤＸについてもう一問だけ質問します。もう一つ、この調査というのは事業者に委託して活用について調査をしていくということなのか、その点を確認させてください。","respondent":"河西情報戦略担当課長","answer":"そういった３つの点に注意してルールを検討し、品川区としては業務の利活用、業務効率化のツールとして利用できるよう検討を進めてまいります。","voiceIndex":63,"id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"一応確認も含めて質問なのですけれども、新庁舎整備の建設費４００億円、なるべく区民負担を削減していくというようなご答弁があったかと思うのですけれども、それに関して、庁舎跡地等の活用に向けた検討状況についてという資料で、１番の事業目的で、新庁舎整備に際する区民負担の軽減を目指しと書いてあるのですけれども、新庁舎の整備費４００億円の削減を、庁舎跡地の活用によって削減していく。","respondent":"泉広町事業調整担当課長","answer":"先ほど申し上げました新庁舎整備に４００億円以上の事業費がかかるですけれども、ここに際しまして、今後官民連携手法を導入して財源を生み出してまいりますが、それを直接的に新庁舎整備のほうに充てていけるのかといったところは、今後検討するといったところになってあります。","voiceIndex":66,"id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。新庁舎建設費そのものの区民負担の軽減策というのも、今後検討していくということでよろしいのでしょうか。","respondent":"山下新庁舎整備課長","answer":"今のご質問の新庁舎の整備、建設に当たっての費用削減という視点で申し上げますと、今後設計をしていく、またＣＭといったところで、管理支援を行っていくというところで、コスト自体の低減というのは当然努めていく考えです。","voiceIndex":68,"id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"品川区庁舎跡地等活用検討委員会とか、旧荏原第四中学校の策定委員会とかがありますけれども、こうした委員会を設けるということは、法令で何か決められていることなのでしょうかということと、この委員会での審議結果はどの程度の拘束力というか、今後行政に与える効果はどの程度のものなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今回我々がやってまいります庁舎跡地等活用検討につきましては、まず区民の方々のニーズをしっかり把握していくというところと、民間事業者に対する対話型市場調査の結果を参考にしながら、幅広く検討していくものということで考えてございまして、今後の検討に当たりましては。","voiceIndex":70,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"最後にＤＸのほうで質問させていただきたいと思うのですけれども、デジタル人材の育成・確保ということが書いてあるのですけれども、現在職員採用、情報戦略担当係長級、システム標準化担当係長級の方を募集しておりますけれども、これもデジタル人材育成・確保の一環ということでよろしいのでしょうか。","respondent":"河西情報戦略担当課長","answer":"実際にデジタル化を行うに当たりましては、目利きするだけではなくて、デジタルツールを使いこなせるスキルが必要になりますので、外部に募集しているデジタル人材というのは、デジタルツールを使いこなせる人材ということでご認識いただければと思います。","voiceIndex":72,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。これは要望というか、お願いです。よろしくお願いします。今まさにゾーニングと構造設備のところが主立ったところなのですけども、スケジュールを見ますと、９月以降から外観の検討が入る。そうすると、恐らく景観審議会はこれから設置をするのですか。これは都市計画課ですよね。これから有識者、あるいは公募区民を募っていくということでよろしいのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"そこの会に新庁舎の外観等についても議題として載せていくという形になるのですけれども、我々といたしましては、できるだけ早い段階で一度景観審議会のほうに、たたき台ではないですけれども、概略的なものをお出しさせていただいて、ご意見をいただいて。","voiceIndex":75,"id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問","question":"先ほどの各課デジタル化推進委員ですね。不勉強でごめんなさい。これは、例えば、総務課、防災課、そういうところに、各課にデジタル化推進委員という方が、今実際もう何人かいらっしゃって、結局業務のデジタル化の目利きの人材を育成するために、効率化するデジタルツールとか、種別、それを教える人をこれから入れていく、そういう形でいいのですか。","respondent":"河西情報戦略担当課長","answer":"役割がございまして、今ＤＸで進めて、中心になっているのは、我々情報推進課の情報戦略担当なのですけれども、各課の業務を全部理解しているかというと、理解できておりません。","voiceIndex":78,"id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"分かりました。子どもたちもなかなか高齢者と交わる機会がないし、人に教える子どもの喜びと、おじいちゃん、おばあちゃんも孫世代に教わる喜びというのは、マッチしていて、とてもいい取組だなと思っていたので、そういう教室だけの広がりではなく、要は学校に拡充するとか、やっぱり地域と書いてあるのなら、もっと地域に下ろしていくといった大きな流れというのは考えているのでしょうか。","respondent":"河西情報戦略担当課長","answer":"今ご意見をいただきましたように、子どもと高齢者、シニアの皆さんが交流できる機会にもなると思いますので、今の意見をいただきまして、今後所管の皆さんと検討を進めていきたいと思います。","voiceIndex":82,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"１つは、公募区民が１８歳以上の方で７名ということなのですけれども、例えば、様々なご意見を得られるためには、年齢別で分けたほうがいいのではないかなというふうに思っているのですけれども、区としてどのような形で選考されるのかというお考えを分かる範囲で教えていただきたいのと、もう一つが、令和５年８月から令和６年６月まで全５回の検討委員会が開催されるということですが。","respondent":"泉広町事業調整担当課長","answer":"アンケートにつきましては、今年度の１月から３月頃にかけて行う予定としています。こちらも今後、秋に行う区民ワークショップの内容を踏まえた上で、庁舎跡地等活用検討委員会の中で議論してまいる予定としています。","voiceIndex":85,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"採点の基準が示されているかと思うので、応募された各企業が一体何点なのかということは全部把握されていると思うのですよね。総合点だけだとよく分からないので、各審査基準に対して何点だったのかということを公表して、ここがよかったのだなということが区民に分かるようにするというのは情報公開として大事ではないかと思うのですが、この点はいかがでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"お話しいただいたとおり、点数をつけているですけれども、こちらのほうにつきましては、それぞれの企業のところで、実際にはかなりの点数差があるところもありますので、実際に応募した会社で悪いところ、こんな悪過ぎるところがあるとかというところも。","voiceIndex":89,"id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"今の点はよく分からないのが、応募した企業の企業名、ほかの自治体を見ていても、最終的に淘汰というか、採用された企業の名前は公表されますけれども、それ以外の企業を公表しないというやり方もあって、公表せずにＡ社、Ｂ社、Ｃ社という形で、各企業の採点結果を出すというやり方はあると思うのです。今のご答弁はなかなか理解できないところなので、もう一度お願いできますか。","respondent":"大友新庁舎建設担当課長","answer":"今回業務遂行能力であったり企画提案であったりという項目ごとに、それぞれ点数をつけているところですけれども、点数のみの公表で、どの分野が特に高かったというところにつきましては、コメントに集約されているところもあり。","voiceIndex":91,"id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"これはどういう基準で選ばれたのか分からない、今、不透明というふうな話も周囲から聞こえているのですけれども、そういう批判が出てもやむを得ないのかなというところがありますので、これは本件だけではなくて、品川区は、ほかの件でも情報公開が少ないのかなというふうに思っていて、今日は個別の話ではないということなので、逆に一般的な話でお伺いしたいのですけれども。","respondent":"大友新庁舎建設担当課長","answer":"実際にお示しいただいたとおり、品川区の簡易プロポーザル方式実施要綱に基づいて、我々所管のほうで要領を作成し、実施しています。要綱の改正になりますと、所管が契約というところになりますので、今回の答弁では、お答えはちょっと難しいかと思います。","voiceIndex":93,"id":"exchange-019"},{"speaker":"松本委員","kind":"提案","question":"分かりました。何となく問題点は分かりましたので、また引き続き、他の部署でもご提案をさせていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"１点だけ、庁舎跡地等の活用に向けた検討のところで、今後の予定、(3)の対話型市場調査というのが出てきています。品川区でこういう手法を取られるのは初めてでしょうか。お聞きしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査に関連するご質問です。対応型市場調査につきましては、品川区におきましても、これまで実績はあります。これまでやったことがあるです。","voiceIndex":96,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。今回サウンディング市場調査というのを導入するに至った、区長の意向というのは多分あるだろうというのは認識しているのですけれども、その上で効果というか、どういうところを狙ってこういう手法を取ろうとしているか。官民連携という一般的な話はあるのですけれども、そこはちょっと踏み込んだ形であえてこの手法を採用した狙いというところについて、お伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"こちらにつきましても、検討委員会の中で検討する内容です。","voiceIndex":98,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。検討委員会の中でも検討されるということで今お聞きしたので、当然この議会においてもその報告があるということで認識いたしました。その中身については、またそのときにということでまた今後質問させていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"庁舎跡地等の活用について何点か教えていただきたいと思います。それから、この委員会は、令和６年の６月まで全５回をやった後、検討事項答申を受けたその後のスケジュール、新たな委員会をつくるとかのお考え、そして、建物完成までの工程、スケジュールが決まっていたら教えていただきたいと思います。","respondent":"泉広町事業調整担当課長","answer":"この検討委員会は６月までとしていますが、その後のスケジュールにつきましては、今申し上げました区民のニーズですとか、対話型市場調査に伴う事業スキームによって、様々なケースが考えられますので、そういったところを整理しながら。","voiceIndex":102,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"旧荏原四中のワークショップも、３６名の方の意見をお聞きになっていますけれども、利用されるのはもっともっと多くの方々になると思いますし、より幅広い方々の意見を吸い上げていただきたいという要望です。ぜひ幅広い業種の皆様からのいろんな意見を調査いただきたいと考えています。そしてまたその内容について、ぜひご公表いただきたいと考えています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２回目になりますけれども、先ほど松本委員の質問にもプロポーザルのところで確認があって、もう一回確認というか、どうしても言っておかなければいけないと思ったのが、今日の委員会の報告を受けて、この結果についてはこれからホームページ等で報告をされると。別に社名を出さなくてもいいですよ。そこについてもう少し踏み込んだ選定理由の説明を公開していただきたいと思いますが、いかがでしょうか。","respondent":"大友新庁舎建設担当課長、黒田新庁舎整備担当部長","answer":"しかしながら、ここが優れているという選定理由につきましては、今後概略プランとか、様々な形で区民の方に周知をしていく過程の中で、事業者選定について。課長からご答弁申し上げたとおり、私どもは区の簡易プロポーザルの要綱に基づいて進めてまいりましたが、選定結果の公表につきまして、要領の中で何か工夫ができることがないかということも検討しまして。","voiceIndex":106,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど対話型市場調査についてやり取りがあって、何点かまとめて伺いたいのですけれども、これは区民ではなくて、民間事業者と対話して市場を調査するということだったのですね。庁舎の跡地に関わることですから、そこを改めて明確にしていただきたいのと、その調査の結果をこの委員会にもホームページにも公表していただきたいと思うのですが、その２点、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"民間事業者の提案内容は、独自のノウハウ等が含まれておりまして、公表に関しましては、提案者へ確認を徹底いたしまして、留意して適切に実施してまいるです。","voiceIndex":110,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"つまり、新庁舎に関する区民負担の軽減を目指しに関わっているということは、庁舎跡地で民間企業がどれだけもうけることができるかということを調べるための調査だということになりますね。その点、もうかる、別の言い方をすれば、利益を上げる、会社の利益になる、やっぱりもうかるということですよね。それを調べるための調査だということでいいのかを最後に伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査につきましては、今申し上げました民間事業者との連携に伴う財源の確保のほかにも、今後実施してまいりますワークショップですとか、アンケートに伴う区民ニーズと、民間事業者の提案をどの程度すり合わせることができるのかといったところの材料にもなりますので。","voiceIndex":112,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":27959,"voices":116}},{"id":"r05-20230614-19","meetingId":"r05-cm06","date":"2023年6月14日","dateIso":"2023-06-14","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時２０分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今回この今年度修正前に、昨年、令和４年度に事前検討をしているということで、これもどういった体制で検討してきたのかというところを伺いたいということと、また、検討してきたのかということと、また、その検討内容、理解を、私も含め、委員の皆さんの理解を深めるためにも、今後の委員会で報告をしていただきたいと思うのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"令和４年度の事前検討につきましても、こちらの検討体制、あくまで庁内のところ、これまで庁内の様々な部局がいろいろ防災についての活動を行ってきた、そういったところの取組を確認し、どういったところを進めていくべきか、そのようなところの話合いを進めてきて。","voiceIndex":32,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"それと、この間取組で、住宅などは結構建て替えなど進んできて、まだ不十分なところもありますけれども、オフィスビルが、この耐震化、建て替えも含めてなかなか進んでいないということが報道などでもされておりましたが、この間の委員会でも、その支援をどうしていくのかというところで質問をしたところ、東京都などの様子を見ながらやっていくということで説明があったのですけれども。","respondent":"平原防災課長","answer":"それともう１点は、緊急輸送路の沿道のところにつきましては、東京都の条例に基づきまして耐震化施策が進んでいるところですので、そのような東京都と、私どもの今後定めてまいります地域防災計画での取組、それをしっかりと連携させていきながら。","voiceIndex":34,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。環境のところで伺いたいと思います。それと、続けて質問します。３点目が再開発の問題なのです。そうすると、やはり実際超高層になったら、床面積的には２倍や３倍では済まないということになりますので、本当に排出量が増えるということを、やはりこれは規制していくべきだと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"そうしたところから、まずは側面援助から入っていくと同時に、様々な補助金などを用意しながら、規模によってはいろいろ難しいところもあるかと思いますが、そういった助成をしながら、中小企業に向けての支援をいろいろ進めてまいりたい。","voiceIndex":36,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"だから、その技術がなくても５０％削減をしていく、こういったロードマップをつくって、その技術革新が起これば、それは情報をしっかり入れていただいて、さらにそれを活用していくというように進めていかなければ、この５０％削減というものがしっかり実現していかないのではないかと思いますけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"個々の機器に頼らずとも、主電源が脱炭素エネルギーであるということから脱酸素の可能性もあるというところで、そういったものを組み合わせるということで、総務省のほうからも脱炭素ドミノというような表現をされておりますが、そういったものを見合わせる中で。","voiceIndex":38,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"総合的に進めていただくことはいいのですけれども、やはりそれが、技術革新が起きなければ５０％削減できないということになってしまったら意味はないわけですから、それはしっかりと、この２０３０年に５０％削減していけるということで、しっかりロードマップをつくっていくべきだと、これは要望しておきたいと思います。それが削減にもつながっていくと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"その中で環境技術もしっかりつながりながら、東京都、区にいたしましても、そういったものを進めているところです。活用事例はたくさんありますので、そういったところから、最適解を導きながらやることが大切と考えているところです。","voiceIndex":40,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"この超高層再開発は、やはり、ひとまず今の現時点では、ＺＥＢ Ｒｅａｄｙが大体、そこまでしかできないという状況ですから、排出量が増えるということになると思いますので、それは超高層再開発は規制をしていくべきだということを意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"最初の防災のところで、受援体制について伺いたいのですけれども、この令和３年６月の品川区災害時受援計画というものについて深く認識があるわけではないので、もしかして重ねての質問になってしまうかもしれませんが、今ちょっと概要を見たのです。これではいろいろなところからボランティアが来たときに、とても混乱すると思いますというお話を伺ったのです。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"徐々にそういったところの練度も高まっているものというように認識しております。私からは以上です。さらに今年度ですけれども、民間の大型倉庫を確保いたしまして、支援物資の物流が滞留した場合、その民間倉庫に一時的に物流を流して、混乱が起きないような体制もまた取っているところです。","voiceIndex":44,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。それを公に発信することで、やはりそのボランティアにいらっしゃる方の、何というのか、心構えというものも変わってくると思いますので、その辺については、分担をするのは大変結構だと思うのですが、それも含めた全体像を示していただきたいと思います。これは今後に向けた要望にとどめておきます。本当に善意なのです。何かコメントがあったらお願いします。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"ボランティアのところですけれども、これは人的・物的、両方含めてなのですが、しっかりと、先ほど説明させていただきました地域防災計画の中にまず全体像を含めさせていただいて、こちらの計画、当然全区民といいましょうか。物資につきましても、様々災害の状況によって必要なものというのは異なってくると思いますので、そのときそのときでニーズをしっかり把握して、情報発信していきたいと考えています。","voiceIndex":47,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"エコルとごしの講座、６０講座、予定ですか、予定として上がっているのですけれども、講座の主体、いろいろな、このような環境の講座をやっている団体などあると思うのですが、そのような方たちに委託をするとか、それからそういう方たちが講座をやりたいと言ったときの選択といいますか、そのようなことについて何か計画やルールなどあるのでしょうか。教えてください。","respondent":"河内環境課長","answer":"このテーマですが、やはり環境基本計画の中身に沿うというところで、今回脱炭素系が非常に多く報告されておりますが、そのほかにも様々、生活にまつわることなどいろいろありますので、ぜひまたお聞きいただければと思いますけれども。","voiceIndex":50,"id":"exchange-009"},{"speaker":"吉田委員","kind":"確認","question":"そうしたら、例えばいろいろな、本当にいろいろなところが講座を主催しておられると思うのですけれども、そのような人たちはエコルとごしのほうにそのような受入れ窓口というか、そこの、何というのでしょう、選別という言い方はよくないですかね。そのように、ここにはお願いしようとか、ここを会場にしようとか、そのような窓口がエコルとごしの中にあると考えてよろしいのでしょうか。確認させてください。","respondent":"河内環境課長","answer":"したがいまして、エコルとごしのほうにお申し込みいただくような形で、さらに、いろいろな中身の状況といいますか、行うことが適切かどうかというものにつきましては環境課のほうにご相談ありますが、基本的にはこの環境基本計画の中に基づきまして。","voiceIndex":52,"id":"exchange-010"},{"speaker":"鈴木副委員長","kind":"質問","question":"環境のことで少し伺いたいのですけれども、エコルとごしのところで、令和４年のときはＺＥＢ普及支援のところで、セミナーが、説明会３回やっているものが、今年は２回に減っているのですけれども、これはなぜ減っているのかということが１つです。","respondent":"河内環境課長","answer":"現在、第１世代と言われるＺＥＢですので、今後ハイドロＺＥＢなどいろいろなＺＥＢが展開されるということで、日経などでにぎわせているところはあるのですが、そういったことを鑑みながら、きちんとこれも進化させていきながらやっていきたいと考えているところです。","voiceIndex":55,"id":"exchange-011"},{"speaker":"鈴木副委員長","kind":"質問","question":"そのようなことなので、一般的にこれとこれとこれをやりますというだけでなく、このことをやったことによってこれだけ削減できる、そして、その削減するためにどういう制度をつくるかという、そこまでやって検証していくという、そのような方法が必要ではないかなと思ったのですけれども、その点についても伺います。","respondent":"河内環境課長","answer":"そうしたところで、どの仕様をどう入れていくかという情報、そういったものも投資の中で非常に大事になってまいりますので、併せてこういったところで推進していくことが重要かと考えております。こういったところで推進してまいります。以上です。","voiceIndex":57,"id":"exchange-012"},{"speaker":"鈴木副委員長","kind":"質問","question":"もう１点お聞きしたいのが、ＣＯ２の排出量と、それから植林や森林管理などによる吸収量を差し引いてＣＯ２の合計を実質ゼロにするというようなことになっていると思うのですけれども、そのようなところでいうと、品川区の中で、私は公園を増やすとか、緑をもっと増やすということの計画が、この環境計画の中にどこにどのようにあるのかなということがよく分からなかったのですが、その辺のところは。","respondent":"河内環境課長、溝口防災まちづくり部長","answer":"一方で、河川下水道課などでは、高知県とのカーボントレードで、そういったものも運用というところですが、日本全国で考えますと、どこかのものをどこかに持ってくるだけで、日本全国としては減っているわけではございませんので。緑についてなのですけれども、昨年度改正しました水とみどりの基本計画・行動計画、そういったものをまた別に持っていまして、その中で公園を増やしていったり、また緑の保全。","voiceIndex":59,"id":"exchange-013"},{"speaker":"鈴木副委員長","kind":"意見","question":"本当に品川区は公園も少なくて、何回も取り上げさせていただいているのが、町会の中に１か所も公園もなくて、一時集合場所もなくて困っているという、そのようなところもたくさんありますので、そのような点でも、本当に品川区自らが町会にも支援をしていただきながら、公園を町会の中につくって、そしてまた緑も増やしていくというところで、ぜひ取り組んでいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"防災のほうなのですが、避難計画の備蓄のほうで、前年度民間事業者と協定して、まず管理から始まって、今年、年度でいうと前年度ですけれども、輸送も含めた協定ということでされる中で、その備蓄品、これ区民のほうにはローリングストックなど周知啓発があるのですが、区で持っている備蓄品のローリングストックというか、その活用というのでしょうか、仕方は、例えば町会の。","respondent":"羽鳥防災体制整備担当課長","answer":"先ほど備蓄のローリングストックについてご質問いただきました。こちらですけれども、令和４年度に進めました管理体制のところで、ローリングストックの目的までは特に示してはおりません。","voiceIndex":64,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"判断というのでしょうか。要はその備蓄品の活用というものが、いろいろな形で今、何というか、まさに活用されていることが多々ある中で、それは災害時にはもちろん避難していただく、避難されている方たちの食料などの提供となるのですけれども、まさに入替えのときにそのものの活用の仕方というものが、今どうなっているのかということを改めて教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"現在、計画的に有効活用して物資のほう入替えをしていて、廃棄するものゼロを維持しておりますので、現状の取組をそのまま進めていきたいと考えております。","voiceIndex":66,"id":"exchange-016"},{"speaker":"つる委員","kind":"確認","question":"それでいいのかという、もう１回確認と、例えばそういったときに、いわゆる環境的な視点ですとか、備蓄品を活用した、何というか、新たな展開、例えば障害者就労につなげるなどいろいろあるのです。備蓄品を活用して。なっていくのか。そこのところをもう１回教えてください。","respondent":"羽鳥防災体制整備担当課長、河内環境課長","answer":"有効活用するものの、その目的については、システムの中では管理しておりませんで、区のほうで判断して活用できるという体制を取っております。備蓄品などにつきましてはいろいろな一定の制約があって、やはり環境面だけではというところもあろうかというところも、環境課としては認識しつつも、やはり、例えば食料品でありますとか。","voiceIndex":68,"id":"exchange-017"},{"speaker":"つる委員","kind":"確認","question":"それで、環境のほうでは１点、先ほどご答弁あったかもしれないのですが、今日のまさに概要というところなので、これ大きく３つの中で、環境の、それこそ基本計画で盛り込んでいただいたサステナブルファッション、これずっと言っていますけれども、このイベント実施だとか、先ほど指定管理という中での選定、講座の選定やイベントの選定ということがあったのですが、区環境課としての。","respondent":"河内環境課長","answer":"今後世の中の、何といいますか、意識の醸成といいますか、そういったものに勢いがないと、なかなか慣れ切った衣食住の、何といいますか、ルーチンが変わってきませんから、若い世代の声も活かしながら、そういったものを今後も進めていきたいというところで、関係性については。","voiceIndex":71,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"すみません、２点確認します。ちょっと時系列を確認したいのですが、民間事業者から避難所への支援物資が届くという流れがあるかと思います。その前に、まず区民避難所での物資があります。この評価というか、どのように受け止めているのかということと、あとこの来館者数の約２２万人のうちの、品川区民と、また区外の方、その内訳が取れているのかというところ、そこを教えていただきたいと思います。","respondent":"羽鳥防災体制整備担当課長、河内環境課長","answer":"こちらから順次補給していくという形になろうかと思います。４日目以降ですけれども、国等から支援物資が届くようになります。その際には、支援物資は、先ほど申し上げました京浜トラックターミナル、こちらで一度受けます。そのやり方など今後検討していって、今後よりよい、また環境学習を進める上での参考にしたいかなと考えています。アドバイスありがとうあります。","voiceIndex":74,"id":"exchange-019"},{"speaker":"新妻委員","kind":"確認","question":"再度ここを確認させてください。ですので、今後、また品川区民に対しての、どなたが、他区の方も来ていただくことは大歓迎と思うのですけれども、さらに区の施設として、品川区民がどれだけ利用していて、区民に対しての意識向上がどれだけ図られているのかということは、１つまたどこかの、何か仕組みをつくって、確認ができるようなことも必要ではないかと思いますが、ぜひご検討をお願いしたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"先ほどの質問で、支援物資が避難所には届くけれども、備蓄倉庫には、災害対策備蓄倉庫には届かないのかというお話でございましたが、区民避難所に必要なものは直接届けられます。","voiceIndex":77,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"前地震が、この東京でも震度５ですか、何か来たときに、本当にあれだけ車が動かなくなって、皆そこへ止めていっていいのですよね。それから、今３日以内は区のほうで対応するというお話ですけれども、では本当に運転手を確保できるのですかという問題も、今度出てきますよね。全然。だって、いっぱい行政で様々なことをやろうとしたって、各会社、事業所が動かなかったら何もできないではないですか。結局。","respondent":"河内環境課長","answer":"そういった需要があるかないかということは、皆さん一人ひとりのそういった買物の行動によって起こるというところがありますので、そこは委員おっしゃるとおり、なかなか難しいというところも認識はしているところでありますが、一方でそうしたところから。","voiceIndex":79,"id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問","question":"防災に関することで、ちょっと備蓄のお話が出ていたので、併せて伺いたいと思うのですけれども、今支援の仕方というものはとても分かりやすくお伺いできたのですが、この物品の内容というものは、多分ここを見ていくと、区では１日分備蓄して、１日目で放出というように書いてあって、ホームページを見ていくと。","respondent":"羽鳥防災体制整備担当課長","answer":"先ほど、もう一つのご質問ですけれども、区民の方の声が反映できるのかですが、こちらは有効活用する際に、皆様に区が備蓄しているものを実際使っていただいて、そういったときに声を聴かせていただいて、今後の備蓄物資の改善につなげていければと考えております。","voiceIndex":82,"id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問","question":"具体的に施設などの運用に、多分渡された人たちなどがいて、そのような方々から、これはちょっとというような感じを直接区議として聞かせていただけるのですけれども、そのような声というものは、どこかにお伝えするというときは、担当の課長にお伝えすればいいということですか。","respondent":"羽鳥防災体制整備担当課長","answer":"そういった利用された方の声に関しましては、防災課のほうにご連絡いただければ対応させていただきたい、検討していきたいと考えておりますので、よろしくお願いいたします。","voiceIndex":85,"id":"exchange-023"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"急に情報だけ下さいというと、やはり区民も何だよという話になると思うのですが、物資を渡すというタイミングで、本人確認というか、情報を品川区側も集めていくということが、１つ情報の収集としては、そのタイミングで、場合によっては、この避難場所が空いていますから、何か困った場合には来てくださいねというような情報の発信というものもできると思いますし。","respondent":"平原防災課長、河内環境課長","answer":"今委員からご質問いただきました情報の収集・発信というところで、お話の中では物資というようなところで例示でいただきましたけれども、そこも含めてなのですが、これまでは委員ご指摘のとおり、区が情報を集めて。エコルとごしの多目的ホールはどうしても、定員が１００名というところもございまして、なかなか難しい点もあるのですが、今後の視野といたしましては、例えばスクエア荏原、きゅりあんなど、そういったところも含めまして。","voiceIndex":88,"id":"exchange-024"},{"speaker":"西村委員","kind":"質問","question":"環境について、リサイクル・プラスチック削減について１点だけ伺います。さらなるごみの分別の周知や、資源回収品目の拡充を進める必要があるなと思っておりまして、先日鎌倉市のほうでお話を伺ったときに、リサイクル率が５０％を超えると伺いまして、ここまで高いリサイクル率が実現できるのだなということと、あと市民の意識が大変高いことが印象的でした。","respondent":"品川品川区清掃事務所長","answer":"現状リサイクル率は、大体２５％程度になっております。今後計画の中で、いろいろなリサイクル品目を増やしていかないと、多分リサイクル率は上がらないと考えています。大体、おおむね計画の中で決めておりますのが、今後１０年間で１０％上げていきたいと考えております。","voiceIndex":92,"id":"exchange-025"},{"speaker":"西村委員","kind":"質問","question":"私も新しい取組が、この目標を達成するためにも必要だろうなということをこれまでの資料も見て思っておりまして、リサイクル手法の確立や、あと何ごみか分からないからそのまま燃やすごみに捨ててしまうということが、もう多々あると思いますので、その場で、チャットですとか、アプリですとか、そういったものでも分別方法がすぐに分かるという、何か取組はできないかなと思っておりまして。","respondent":"品川品川区清掃事務所長","answer":"いろいろこのような技術を活用して、啓発のほうを進めていきたいと考えていますので、今後も頑張ってまいりたいと思います。","voiceIndex":94,"id":"exchange-026"},{"speaker":"こしば委員","kind":"質問","question":"ご説明のほうありがとうあります。防災に関すること等でお伺いをいたします。やはり防災、地域の防災、当然地域と行政が連携をしていかなければならないところで、特に最近私も憂いておるのが共助、今後の大震災、大災害が起こったときに、この共助の体制がしっかり機能していくのかということは大変憂えています。","respondent":"平原防災課長","answer":"ただいま委員ご指摘のとおり、共助の体制には地域の方々の力が非常に重要になってくるところですが、一方で、ご指摘のような課題があるということは、私どもも十分認識しております。","voiceIndex":97,"id":"exchange-027"},{"speaker":"こしば委員","kind":"質問・要望","question":"多分課長のほうも、もう既にご存じだと思うのですけれども、そういった取組をされている町会・自治会をぜひ、既に周知はされておることだと思うのですが、またその話も、大井だけでなく、品川区全体のほうにも広めていただきたいなと思うのですが、その辺のお考えをお聞かせください。","respondent":"平原防災課長","answer":"様々なところで、やはり先行事例というものが存在しておりますので、それを横展開という言葉でしょうか、そういったところを広く紹介させていただきながら、ほかの地域での参考にしていただいて、全体的な底上げが図られるよう。","voiceIndex":99,"id":"exchange-028"},{"speaker":"澤田委員","kind":"質問・要望","question":"先ほど西村委員からもありましたが、ごみの分別、ごみの分別の中で、私も２月にＡＩチャットボットやアプリの活用などを要望してみたのですが、現在進んでいるのでしょうか。ちょっと進捗状況を聞きたいなと思いまして、よろしくお願いいたします。","respondent":"品川品川区清掃事務所長","answer":"チャットボットのほう、いろいろと今、ほかの自治体の例を見ながら、どのようなものがいいかというところは検討しています。","voiceIndex":102,"id":"exchange-029"},{"speaker":"澤田委員","kind":"意見","question":"少しずつ進んでいるような、前向きに進んでいるような感じがして、とてもうれしいなと考えています。西村委員が先ほど言っていた鎌倉市の５０％、私は知らなかったのですが、本当にすごいなと思っていまして、少しでもそこに近づくというか、リサイクル率が上がっていくといいなと考えていますので、どうぞ、さらに進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-030"}]},{"id":"topic-02","title":"それでは、「ゼロカーボンシティしながわ宣言」","agenda":"それでは、「ゼロカーボンシティしながわ宣言」","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"それと、このゼロカーボンシティ宣言、２３区の中では何区宣言をされているのか伺います。それと４点目が、この次第のところで、区長と議長がこの宣言文に署名をするということが書かれているのですけれども、この議会の中で、署名することについてどこかで確認されたということがあったのかどうかお伺いをします。","respondent":"河内環境課長","answer":"４点お伺いです。なぜ今かという点です。品川区のゼロカーボンシティ宣言ですが、他の自治体によりますと、宣言だけを先行いたしまして、その後の内容を含んだ計画です環境基本計画を、かなり後から出してくるというもので進めております。","voiceIndex":109,"id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"議会のところでは、確かに昨年議論はしてきたわけなのですけれども、そこで直接的に議会として署名するということは確認されなかったというような認識があるのですが、もちろん反対するものではないのですけれども、そういった、議会としてこれを署名していくということになるので、そこはちょっと議会の確認を取っていく、どういった段階でということがあるとは思うのですが。","respondent":"河内環境課長","answer":"一方で議会の論議の中では、やるかやらないか、どうやるかという論議も含めまして、様々の論議があったところですが、やはり議長、住民の代表たる区議と連携して発信することが大事であるという考えに基づきまして、このような形で発信していくものです。","voiceIndex":111,"id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"宣言がちょうどあしたですか。やるということで、同日に本庁舎の懸垂幕ということなのですけれども、懸垂幕はあそこ、品川区は３本あって、私も懸垂幕は詳しくないのですが、３本ある中でどこの、優先順位などはあるのですか。右、左、真ん中とありますけれども。","respondent":"河内環境課長","answer":"経理課に問い合わせたところ、特に順位はつけていないですので、ご指定した、空いているところに掲げていただきたいということで、そこに掲げする予定です。","voiceIndex":114,"id":"exchange-033"},{"speaker":"つる委員","kind":"意見","question":"そうすると、どこでもいいというところで、よく表彰台などだと真ん中が１位だったりしますよね。その順番は関係ないでしょうけれども、今１本は左側に、ちょっと忘れてしまいましたが１本かかっていて、あした設置するのですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-034"},{"speaker":"つる委員","kind":"質問","question":"今確かに一番目立つ真ん中は工事中なのです。懸垂幕が壊れてしまっているのです。ゼロカーボンシティを目指すのに、懸垂幕、ある程度ずっと掲げると思うのだけれども、懸垂幕でもいろいろ、何というのか、その後の活用とか、それこそ無駄にしないというか、そのような素材のものもあるのですが、今どのような懸垂幕でもう既に作ってあるのか、その素材などを教えてください。","respondent":"河内環境課長","answer":"いろいろな素材、委員おっしゃるとおりで、使い捨てのプラスチックのものから様々あるのですが、環境課が掲げるものが環境によくないということもあれですので、そういったものにこだわりまして選出いたしました。","voiceIndex":119,"id":"exchange-035"},{"speaker":"鈴木副委員長","kind":"確認","question":"例えば「非核平和都市品川宣言」などは宣言文がありますが、そのような宣言文はないのかということを伺いたいと思います。それから、先ほどの議長による宣言文の署名というところは、やはり議運の報告なり、何らかの形で報告をして、どこかで確認ということが私は必要だったのではないかなと思います。ちょっとその宣言文のことをお願いします。","respondent":"河内環境課長","answer":"そこを掲げて、より一層区民と行政が一体となって取り組むことを本日ここに宣言しますというところで、実際のところ自由度はそれほど高くないのですが、やはりそういったところで、その自治体らしさを出しながらやっていくものというものです。","voiceIndex":122,"id":"exchange-036"},{"speaker":"鈴木副委員長","kind":"意見","question":"そのような宣言文があるということでしたら、ちょっと報告の中にも、せっかくつくられた宣言文ですので、この報告のところにぜひ入れていただきたかったなと。今後、もしもそのような何かの宣言があるようなときには、ぜひ宣言文も入れていただけたらなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-037"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"ご説明ありがとうございました。ご報告ありがとうあります。それと、この被害の中に、強風で空き家のところが壁が剥がれ落ちてしまったり、また、民間事業者のお店のところでも少し壁が剥がれていたというようなこともあったのですが、そのようなことがここには掲載されていないのはなぜかというところをちょっとお伺いしたいと思います。","respondent":"平原防災課長","answer":"もう一つございました空き家等々につきましてなのですけれども、こちら私どもで把握できているところを現在計上していますので、今後、例えばこういったところにも被害が実際発生しています等々のところ確認ができましたら、現地調査させていただきまして。","voiceIndex":129,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"今回、避難場所５か所と避難施設が１か所開設されたということで、そこでの対応などについて伺いたいのですけれども、今回は簡易間仕切りや簡易ベッドなどというものは設置がされたのかどうかというところと、あと、たしか今避難所には、携帯の充電をするものがあると思うのですけれども、そういった対応なども今回されたのかどうかというところを伺いたいということと、実際に避難されてきた方。","respondent":"平原防災課長","answer":"つい最近も、５月に風水害の避難施設の開設訓練を行ったところですけれども、その開設手順の検証、こういったところを随時検討させていただきまして、よりスムーズに開いて、そういったところを今後も展開できるようにしてまいりたいと考えているところです。","voiceIndex":133,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"間仕切りは今回使ったということで、そういった使用していく、訓練の一環としても、ぜひそういったことをやっていっていただいて、できるだけ、今回人数が少なかったので対応はしやすかったのかと思いますけれども、避難施設、避難場所も含めて、世界的なスフィア基準に近づけていくようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-040"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"１点だけお伺いします。浸水のところで、土のうを使っての浸水の防止というものが１つやり方としてあると思うのです。そういった方々に対してというのは、区としてどういった案内をされているのか、お聞かせいただきたいと思います。","respondent":"平原防災課長","answer":"それともう１点、周知の方法の別の方法としては、土のうだけではなくて、例えばしながわ防災学校では水のう、ポリ袋に水を入れたものが簡易土のうのようなものになるということで、ご自宅にあるようなものが緊急時には土のうになるようなもの等々もありますし。","voiceIndex":138,"id":"exchange-041"},{"speaker":"せりざわ委員","kind":"意見","question":"いろいろご検討いただければと思うのですが、１点だけ、前も感震ブレーカーのときに同じようなお話をさせていただいたのですけれども、今２月にポスティングがあったということで、多分予算の関係だとは思うのですが、時期が、逆に感震ブレーカーのときは、寒い時期にヒーターなどを使うので、ぜひ寒い時期にやってくださいという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営のところで１つ、今後防災のところで要配慮支援者の問題など扱ってくると思うのですけれども、その際には関係する高齢者福祉課長や障害者福祉課長も、ぜひ出席させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6634#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":49169,"voices":143}},{"id":"r05-20230616-10","meetingId":"r05-cm06","date":"2023年6月16日","dateIso":"2023-06-16","committee":"議会運営委員会","time":"午後 １時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"せりざわ委員","kind":"質問・要望","question":"２件目の要望としては、選挙に関する要望を書かせていただきました。３件目が環境の要望です。４）のところで、品川区だけでなくて、まだカーボンニュートラルができていない自治体もありますので、しっかりと日本全域で同じ目標を掲げる、そしてそれに向けて、実現するために補助をしていただきたいという旨の要望を書かせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"},{"speaker":"こんの委員","kind":"質問・要望","question":"公明からは、大きく３点です。その要望の１つとしては、給食費を時限的ではなくて、恒久的に事業を進めていただきたい、その財源確保についての要望です。４点目が、こども家庭庁が子ども施策の司令塔になりますので、子ども・若者の意見を政策に反映するために、子ども・若者の意見を継続的に聴く仕組みづくりをぜひ進めていただきたいという要望です。続きまして、３点目が、国だけに要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"しながわ未来としての議長会への要望事項をご説明申し上げます。国と都の双方への要望が５項目あります。国のみへの要望が３項目あります。いずれも当会派として要望したい事項となりますが、中でも、物価高騰に対する経済支援及び経済対策、少子化対策及び子育て・教育支援、医療・福祉、それから気候変動対策・防災対策の４項目については、特に重要課題として強く要望したいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"東京都には緊急に、特別支援学校を含む都立学校を無償化するよう求めるものです。同じく国の責任で無償化することを求めるとともに、東京都には、公明の要望にもありましたけれども、３年経過後も財政措置の継続を求めるものです。最後は、気候危機への対応ということで、２０５０年カーボンゼロへ、２０３０年までの１０年間の取組が重要だと指摘して、目標の設定と取組を求める内容になっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"区の要望もあり、ある程度聞き入れられるが、都の要望や個々の教員の要望も取り入れられるため、教育者としてふさわしくない方や、精神的に教壇に立つことができない方まで区に派遣されており、教育の質が落ちていると。感染症などの大勢の感染者が生まれた場合に、対応する医療従事者等の宿泊できる施設など、上記の場合に備えて、必要な設備を持った大型施設をつくることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"議長会への要望事項というのは、数の制限などはあるのでしょうか。例えば、各区からは何件などという制限はあるのでしょうか。","respondent":"工藤区議会事務局長","answer":"要望事項の数のご質問です。制限はございませんが、結果として、大体毎年、東京都、国、それぞれ１０本前後に絞られているです。２３区として都や国に出す総本数が、です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"山本委員","kind":"提案","question":"状況を理解いたしました。せっかく考えた内容ですので、皆様が広く合意できることであれば、多く提案するというのもいいのではないかというのが感じたところです。最終的に絞られるのは、議長会となるので、品川区議会としてより多く提案できるのであれば、それもいいのかなと思った次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"せりざわ委員","kind":"意見","question":"進め方は例年どおりでいいと思うのですが、なるべく多くの合意が得られる項目から決めていただければと思います。その意味で補足というところで、我々の会派も特段、項目としては今年は載せませんでしたが、前年度も載せてきた物価高騰などは、多くの会派も出ているので、これはぜひ我々も賛同しておりますということだけ、意見として伝えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"議会として多く一致できる内容を中心にまとめていただくというのがよいなというのは、一つあります。一方で、共産としてはどうしても一致できない要望というのも指摘しなくてはいけないなと思っていまして、例えば自民のマイナンバーカードでのオンライン投票なのですが、今これだけ問題も噴出しているときに、提案すべきではないかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"今のまとめ方については異論はないのですけれども、先ほど提案した資料の扱いの件なのですが、それは検討していただけるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"もう一度確認してもいいですか。３項目について、もう一度おっしゃっていただいてもいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"その３点でもちろん異論はないのですが、福祉とか医療の領域のところも、大枠でかなり合意できている事項かとは思うのですけれども、その点はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"}]},{"id":"topic-02","title":"その他の(1)議長会等の報告","agenda":"その他の(1)議長会等の報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨日、議長がカーボンゼロシティしながわ宣言に署名を行ったのです。宣言自体はいいものですし、私たちももちろん歓迎する立場なのですけれども、議会運営の筋としては、例えば議会運営委員会などに諮って、意見を聞く場を設けた上で署名を行うというのが必要だったのではないかと思うのです。なぜそうならなかったのかなというのを議長に伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"そういった中で、議会運営全般、あるいは議員提出の条例案の提出、その他運営に関わる様々なことを行うところであると考えていますので、今おっしゃった部分は、当たらないのではないかと考えているところです。","voiceIndex":53,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"何か議長からあれば伺いたいのですけれども、今回、非常にいい内容なのですが、私は今の事務局長の説明では、納得はできないです。議会としての正式な意思決定になるわけですから、今後の運営なのですけれども、丁寧な進め方といいますか、必要な手続きなど、議会運営委員会で諮っていただくことは、今後ぜひそういった留意をお願いしたいと、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16373,"voices":57}},{"id":"r05-20230628-10","meetingId":"r05-cm06","date":"2023年6月28日","dateIso":"2023-06-28","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、予定表の順番を入れ替えまして、予定表の２、令和５年第２回定例会についての(1)理事者から発言を求められている件","agenda":"はじめに、予定表の順番を入れ替えまして、予定表の２、令和５年第２回定例会についての(1)理事者から発言を求められている件","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点だけ質問させていただきたいのですけれども、専門性という点では、行政運営に長く携わっていた方なので十分だと思うのですけれども、監査基準の中で、独立的かつ客観的な立場で、公正不偏の態度を保持し、その職務を遂行する者ということも一方であるのですけれども、そういう点では、同じ都内の自治体ですし、東京都と品川区とは日頃から連携や関係も深い間柄なので、既に退職したとはいえ、あえて今回。","respondent":"森澤区長","answer":"島田委員の任期満了に伴って、どういった方がいいのかということは、様々検討をさせていただきました。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点だけいいですか。要望事項、ありがとうございました。物価対策もすごく重要ですし、おおむね一致するところでまとめていただいたと思います。ただ、介護士の待遇改善について、３会派から共通して出されていたので、数が増えてしまうかもしれないのですけれども、それもまとめてもよかったのかと思いました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":8944,"voices":46}},{"id":"r05-20230703-6","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"区民委員会","time":"午前１０時００分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５８号議案、品川区の特定の事務を取り扱う郵便局の指定","agenda":"第５８号議案、品川区の特定の事務を取り扱う郵便局の指定","exchanges":[{"speaker":"山本委員","kind":"質問","question":"１点質問させてください。今日から地域センターなどでも新たにできるように広げていらっしゃる中で、なぜにこの荏原郵便局を追加されることになったのか。例えば立地上のもので、このエリアの方は行きにくいからここに設置したとか、その背景について教えていただけますでしょうか。","respondent":"吉野戸籍住民課長","answer":"令和３年度の交付が７万３,０００件、こちらの電子証明書の更新が令和８年になりますので、今後のことを見据えまして、やはりこういった区民の方の利便性のことを考えまして、要は手続きができるところを増やしていきたいと考えた次第です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"せらく委員","kind":"質問","question":"私もマイナンバーカードを持っているのですけれども、まだ更新の手続きをしたことがなく、更新手続きについてお伺いしたいと思うのですが、マイナンバーカードのホームページを見てみると、今、スマホだとかパソコンと郵送で更新手続きが可能というところで、この地域センターや郵便局でできる手続きについて、郵送手続きとかパソコン、スマホで手続きした方は。","respondent":"吉野戸籍住民課長","answer":"マイナンバーカードをお持ちということで、更新という形になるのですけれども、電子証明書の更新はまだオンラインといったことはできません。全て窓口での手続きになります。ただ、例えばカードの発行と再発行に関しましては、オンライン申請でできるというような形になります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"荏原郵便局となっていて、私の地元に近いので、地域の辺りの利便性がすごく高くなるなと思ったのですけれど、郵便局を品川、大崎を含めていくのかなと思ったら、その中で荏原が選ばれたという状況で、郵便局以外で今後、どこかそういった業務提携していくようなお考えの施設はあるのか、教えてください。","respondent":"吉野戸籍住民課長","answer":"郵便局自体も法律で決まっておりまして、今回、ＬＧＴａｌｋというものを使いまして、私どももリアルタイムで本人確認をしますので、そういったことの業務ができるところとなりますと、やはり自治体であったりとか、こういった特定の郵便局という形になりますので。","voiceIndex":12,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"区民の方の利便性が高まっていくということで、ぜひ進めていただきたいと思っているのですけれども、幾つか確認だけします。それをお聞きする背景としては、例えばヒューマンエラーですとか、あとはシステムの障害みたいなものというのは、本当に可能性があるので、そうした危機管理の観点で、どういった連携をされる予定でいるのかというところを確認させてください。","respondent":"吉野戸籍住民課長","answer":"実際に機器配備が終わった後に、そちらのほうでも、いわゆる研修というのをする予定です。それから、連携なのですけれども、先ほど言いましたＬＧＴａｌｋというのはチャットでつながっておりまして、もうリアルタイムで行います。","voiceIndex":15,"id":"exchange-004"},{"speaker":"横山委員","kind":"確認","question":"そのような形で密にリアルタイムで連携を取るということで、大変安心いたしました。何か起きた際にもすぐ連絡を取り合ってやっていただけるということで、ダブルチェックの体制が取れているということを確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"地域センターはともかくですが。それと、この地域センター８か所でやるというのも今回初めて出てきたと思うのですけれど、こちらについては区の職員だから、本人確認は地域センターの職員の権限でやるということで、これはそういう端末で結ぶということはしないのか、そこについて教えてください。","respondent":"吉野戸籍住民課長","answer":"ですので、データ流出はまず起こり得ない環境になります。地域センターに関しましては職員ということで、こちらの本人確認ができますので、そちらにはＬＧＴａｌｋは置かないということになります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどのお話のとおり、これから先、５年後、今回、去年、一昨年と多分爆発的に交付数が増えたというところで、やっていく必要があるということから、それは品川郵便局とか大崎郵便局とか、もしくは、いわゆる地域の郵便局等でもできるような、特定郵便局等でもできるような、そういう形にしていくのか。していっていただきたいという趣旨の質問なのですけれど、この辺りについてはいかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"郵便局のほうの事情もありまして、やはり先ほど言ったいわゆるＣＳ端末とかといった端末を置かなければいけないと、ある程度の広さがないとできないというところで、それで１回断念した郵便局もありますので、そういったところがもし可能であれば。","voiceIndex":23,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"ごめんなさい、最後と申し上げたのですけれども。今、ＣＳ端末という言葉が出てきたのですが、それは先ほどおっしゃっていたＬＧＷＡＮとはまた別のものということですか。","respondent":"吉野戸籍住民課長","answer":"それで、ＬＧＴａｌｋというのはあくまでも本人確認用の、いわゆる通信のものになりますので、全く別のものになります。","voiceIndex":25,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"令和２年が約４万件、令和３年が７万件ぐらいの交付があったので、更新が令和７年、令和８年でこれだけの方が更新してくるというところは分かるのですけれど、とはいえ２年後なので、今の段階で進めるというのはなぜなのかなというのを伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"令和２年、令和３年なのですが、電子証明書は、先ほど委員の質問にもありましたとおり、とても根幹な部分ではありますので、やはり、令和７年に急に始めてミスがあったら、というところもありましたので、なるべく早めに。","voiceIndex":29,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"しかも４例しかなくて、ということで、こうしたさらなる推進というところでは、私たちは、すべきではないなという思いです。様々窓口が増えるということですから、利便性が高くなるということですけれども、その窓口がどこになるのかというところでは、もう少し慎重にすべきではないかなというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"}]},{"id":"topic-02","title":"第５９号議案、指定管理者の指定","agenda":"第５９号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この、五反田産業文化施設、旧ゆうぽうと跡地ということですけれども、今回、指定管理者の指定ということで、株式会社マグネットスタジオということですが、以前の議事録等も読ませていただいて、このマグネットスタジオはＳＨＩＰのホールも運営されているということで、それで、その「ホールをどのように運営していくか。","respondent":"小林商業・ものづくり課長","answer":"この施設の検討に当たりまして、やはり同種の施設、例えばどのような建物を造って、どのような運営が可能かというところで、やはり運営実績があるというところで、マグネットスタジオに一定のデータの提示ですとか、検討の依頼を行ったところです。","voiceIndex":46,"id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"そういうところで、マグネットスタジオにとっては有利だったのではないかなと感じるのと、本来中小業者とのコミュニティの場を広げていく場にしていくのに、力のある事業所がほかにももっとあったのではないかなと感じるのですが、この３社というところでは、当時の商業・ものづくり課長は、かなりの数の応募が来ると考えているというふうにおっしゃっていたのですが。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問です。今回、選定結果に載せている、つまり最終的に提案書を出して、データも含めて提出してきたのは３社ですけれども、事業者説明会の段階では６社出てきたところです。","voiceIndex":48,"id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"指定管理というところで、今回、選定結果というところではしっかりと、点数も今までは本当に、情報公開しても黒塗りという状況でしたし、ほかの委員会では、そういう状況でどうして選定したのかが全く分からない状況ではあったのですが、今回はこうした選定結果も出していただいて、私たちにはこういうことで選定されたというところで分かるということでは、よかったなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、財務分析等についてなのですが、財務分析に関してはその会社の体力で、物すごく大事だと思うのですけれど、その結果等はどこの文章か表に表れて、この資料に発表されているのか、教えていただけますか。将来の予想ですけれども、その辺について教えていただきたい。その中に、ＳＨＩＰと同じところがやるメリット、もちろん本会議で可決されたらですけれども、その辺についても教えていただけますか。","respondent":"小林商業・ものづくり課長","answer":"災害などの緊急時にも対応できる体制であると認められる」というところがありまして、実際、これまでも、先ほどご指摘のありましたＳＨＩＰの部分ですけれども、そちらの体制でも、何か区から緊急時の情報ですとか、コロナも、あるいは災害も含めてですが、例えばいざ。","voiceIndex":52,"id":"exchange-014"},{"speaker":"横山委員","kind":"提案","question":"確認をします。区内企業等との発展および連携の促進ということに関しては、どういったイメージなのか、どういった提案があったのかというところを確認させていただけたらと思います。そのシャワー効果というところがどういったイメージなのか、私のイメージと合っているかどうか分からないので、教えていただけたらなと思います。お願いいたします。","respondent":"小林商業・ものづくり課長","answer":"もう一つのご質問です。１つ目、シャワー効果ですけれども、このマグネットスタジオの説明によりますと、今回、五反田の施設の中でも比較的、いろいろなイベントが開かれて、エンターテインメント系のイベントも開かれるであろうと。","voiceIndex":55,"id":"exchange-015"},{"speaker":"横山委員","kind":"提案","question":"イベントのご提案というところの記載であったので、そうした区内の他の地域との連携みたいなところによって、さらにその五反田のまちづくりを盛り上げていくみたいなところも私は期待をしていたところだったのですが、今回ということではなくて先々のイメージとして、そういったこのシャワー効果というところで、この記載を読んだときに思った部分があったのです。","respondent":"小林商業・ものづくり課長","answer":"３社とも、今回、ある程度の数字のシミュレーションというか、これぐらいお客さんを入れられますよという稼働率ですけれども、Ｃ社も比較的高かったのですけれども、Ｂ社がより、これは、１年、２年、３年と年度ごとに稼働率が少し変わっていくのですが。","voiceIndex":57,"id":"exchange-016"},{"speaker":"横山委員","kind":"提案","question":"短期的な視点だけではなくて、中期、また長期の視点も、区と一緒に考えていったり、共に成長していくという姿勢が確認できたので、非常によかったなと思っています。ぜひ先んじた営業努力といいますか、時代を見据えて一緒に、区と共に進んでいっていただきたいというふうに思います。要望で終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"詳しい選定結果の報告書で非常に分かりやすいなと思ったのですけれど、すごく基本的なところを伺いたいのと、もしかしたら所管が外れてしまうのかなと思ったのですが、こういう指定管理者の候補の選定に、予備委員会と選定委員会の２つが行われているのですけれど、これはなぜ１回ではないのかという。","respondent":"小林商業・ものづくり課長","answer":"２点のご質問がございました。予備委員会と本委員会です。品川区の場合、この２段階でやるという形が基本になっておりまして、ただ、事業者の負担ということもありますので、実際にヒアリングをやってプレゼンテーションをやっていただくのは本委員会のほうです。","voiceIndex":61,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"意見","question":"９ページでいうと、すごく点差が、４００点満点で１００点以上の差がついているというところで、多分、実際にそういう評価が、このＢ社については高かったのだろうなということで、よかったのかなとは思うのですけれども、その予備委員会で指摘をされたこと、懸念事項が、実際のこの本審査のほうで非常に改善されているのは、これ、逆に見るとＢ社だけなのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-019"},{"speaker":"えのした委員","kind":"質問","question":"これ、評価の中には入っていないのでしょうけれども、先ほど、地域との連携を図っていくというお話がありました。同じ建物内に星野リゾートが入ってくるので、そちらと連携をしていくなどというお話があったのかなと興味がありまして、お伺いします。","respondent":"小林商業・ものづくり課長","answer":"今後、何かという部分はあるかもしれないのですけれども、審査の時点では、ひとまず、３階、４階、区立施設の中でどういう提案ができるか、サービスができるかというところに絞って評価をさせていただきました。","voiceIndex":65,"id":"exchange-020"},{"speaker":"山本委員","kind":"提案","question":"他の皆様からご質問があって、ご説明いただいておりまして、聞きたいことは大分聞いていただいているのですけれども、１点お聞かせください。「開業イベントや独自提案における事業の内容も適切なもの」だということなのですけれど、この開業イベントとか独自の提案というのはどういうようなもので、それがいいというご判断に至ったのかを教えてください。","respondent":"小林商業・ものづくり課長","answer":"独自提案といいますのは、実際の施設の利用につきまして、エンターテイメントの利用に関しては、例えば１週間丸々使っていただくような、そういうようなイベントもできるのではないかというところで、そういう場合には、施設のホールとしての利用だけではなくて。","voiceIndex":68,"id":"exchange-021"},{"speaker":"せらく委員","kind":"提案","question":"先ほど有利という話も出ましたが、今回３社ということで、評価項目だとか条件だとかは、どの程度３社に提示していたのか、伺いたいです。ＳＨＩＰの契約の２期目のときの公募が、マグネットスタジオ１社だったということを確認したのですけれども、今回の五反田産業文化施設も五、六年後にまた更新になると思うのですが、そこに対して公募が１社とならないような対策を何かされる予定があるか、伺います。","respondent":"小林商業・ものづくり課長","answer":"今回本案が議決をいただいて、また、次、４年１１か月後といいますか５年後ということになるかと思いますけれども、やはりこの施設が運営をするに当たって非常に、例えば区民の人気度が高いであるとか、使いやすい施設である。","voiceIndex":72,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"先ほど、質疑の中でも言いましたけれども、この施設は区立の産業文化施設になりますが、中小業者の営業や一般の区民の文化活動の参加支援ということではなく、やはり五反田地区への再開発を誘導していくという目的があると思うので、これも併せて、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-023"}]},{"id":"topic-03","title":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"山本委員","kind":"質問","question":"今回、ご説明にあった、商店街にぎわい創出事業で手を挙げている４商店街では、主にどのようなイベントをされようとしているのかというのを教えていただければと思います。それで、多言語対応助成事業も、２商店街が具体的にどのようなことをやろうとしているのかというのも教えてください。","respondent":"小林商業・ものづくり課長","answer":"大井銀座では、こちらはファミリー層向けの音楽イベントも含めた企画をやりたいという、まだ実施日は、いずれも１０月以降ということで、概要ですけれども、そういう話が来ております。","voiceIndex":89,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"補正予算ですけれど、もう実施する商店街が決まっているということなのです。これはもうこれで決まりということで、ほかに手を挙げるところはもうないということなのでしょうか。それともまた追加で。追加ということもないのですか、もう周知しているからこれ以上はないということでよろしいでしょうか。もしあった場合、その追加措置ということもあるのかどうか。","respondent":"小林商業・ものづくり課長","answer":"今回の補正予算は、東京都の補助も入るということで、東京都は、秋、９月を予定していますけれども、この時期に補助金の交付決定をやりたいと考えているです。","voiceIndex":93,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"こういうことを積極的に、やはり特殊詐欺防止等において、という意味で私はやるべきだと思うのですけれども、それについてどう考えるかということがまず１点。ああいう施策というのはどうなってしまったのでしょうか。いろいろな意味で、インバウンド含めて大切だと思うので、単体の施策よりも、そういう意味でつなげていったほうがいいと思うのですけれども、今どうなっているのか教えていただけますか。","respondent":"河合生活安全担当課長、小林商業・ものづくり課長","answer":"こういった各種イベントのほうに、生活安全担当として防犯啓発に積極的に参加したほうがいいのではないかというご意見、こういったイベントのときは、それぞれの主催者等からお話をいただいたり、こちらもお話しさせていただきまして。こういったところもうまく使いながら、今回の補助金も使っていただきながら、外国人へのサービスといいますか、おもてなしというか、そういうものが全体的にレベルアップしていければというふうに考えてあります。","voiceIndex":96,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今回のこの補正予算としては、イベント支援と多言語化というところではインバウンド等を見込んでということなのかなということで、やはりコロナが２類から５類に変わっていったところでの補正予算ということになるのか、伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"やはりそういう意味では、そういう２類から５類への移行というところが大きいのかなというふうに思っております。","voiceIndex":100,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"コロナの中で本当に大変だったというところではあると思うのですが、とはいえ、私たちは何度も言わせていただいているのですが、５類になったことで、感染力が弱まったということではなく、見えなくなってしまったという、毎日報道されていた感染状況がなくなって、そして私たちの目にもなかなか見えなくなってきたというところはあるのですが、感染力はそこまで弱くなっていないし。","respondent":"小林商業・ものづくり課長","answer":"我々、このイベントの支援に関しましては、区直接もありますし、あるいは商店街連合会と常々本当に、日々綿密なコミュニケーションを取っておりますけれども、いろいろまた、第９波が、などというようなお話もいろいろありますので。","voiceIndex":102,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはりそうしたところを見ると、これまでの反省も含めて、感染を繰り返してきた国の施策等も責任があると思うのですけれど、そういったところでは区としてはぜひ、今、第９波ということも言っていただいたので、そこを警戒しながら、ちょっと緩んできてしまっているのですけれど、緩むことなく、そういう立場と姿勢でやっていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2960#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":30066,"voices":118}},{"id":"r05-20230703-7","meetingId":"r05-cm07","date":"2023年7月3日","dateIso":"2023-07-03","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"では、(1)第４２号議案、品川区社会福祉基金条例の一部を改正する条例の審議でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)第６０号議案","agenda":"では、(1)第４２号議案、品川区社会福祉基金条例の一部を改正する条例の審議でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)第６０号議案","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"私はこれを検討するに当たり、今の説明は本当に簡単な説明ですし、報告書が出されているわけですから、この報告書に基づいてももう少し説明をすべきだと思います。これは透明性、公平性が求められると思うのですけれども、これが担保されるというのがきちんと判断できるような資料も私は委員会の資料として出されるべきだと思うのですが、その点も伺いたいと思います。伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"指定管理者の候補者につきましては、品川区指定管理者制度活用に係る基本方針、こちらにも記載されておりますとおり、選定結果等の公表につきましては、選定予備委員会・選定委員会の会議録を公表するということで、この報告書をもって報告をしています。","voiceIndex":13,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので一々質問しなければならないということになるわけですけども、ぜひ資料は、議会が議決する、その責任がある。１か所しか応募がなかったとしたならば、なぜ１か所ということになったのか。それを区としてどう考えているかも伺いたいと思います。取りあえずその点をまず伺って、次にもまた詳しく聞いていきたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今回、１者だけしか応募がなかったということについてのご質問ですけれども、説明会としては６者の法人にご参加いただきました。結果としては１者にとどまる形となりましたけれども、理由としては、回答いただいた法人からは、現場としては応募したかったと。","voiceIndex":15,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"提案","question":"この公募要領のところから伺っていきたいのですけれども、公募要領の８ページのところには企画提案書類一覧というのがありまして、２３項目にわたって企画提案が出されているわけです。それから、利用者の満足度を向上させる取組というのも項目としてあるのですけれども、これはどんなことなのか、伺います。重度の方の受入れというのはどういう状況になるのかも伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"離職率が高い場合は、この比率が低い可能性が高いですので、ここからも認識できると思います。","voiceIndex":17,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"その点、人数と専門職の配置状況というのについて伺いたいと思います。それから、今の離職率というものの意味がよく分からなかったのですけれども、７４％というのは、離職率何％というのも出ているのではないかと思うのですけれども、７４％と離職率というものの関係はどういうことなのか、よく分からないので、もう少し説明をお願いしたいと思います。","respondent":"川崎障害者施策推進課長","answer":"人員体制ですけれども、提案として体制は、今、管理者兼サービス管理責任者常勤１人、世話人兼生活支援員が常勤９人、生活支援員が非常勤が２人、また、夜間については、夜勤１人、宿直１人という提案をいただいておりますけれども、利用者の状態像によって、勤務形態であるとか。","voiceIndex":19,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"提案","question":"ということは、離職率が何％というのは、法人としては出ていないということなのですか。それ以外は資格はないし、資格がある人というのは、介護福祉士の資格ということでの人員配置なのか。その点も確認させていただきたいと思います。それから、報告書の２ページのところで、様々な提案を受けたということで書かれているのですけれども、これは具体的にどんな提案を受けているのかを伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、やはりこちら、重度化、高齢化に対応した施設になりますので、相応の方が配置されると見込んでおります。長岡福祉協会の提案としては、ポイントとしては、やはり地域生活支援拠点として、そこをメインとして、地域共生社会の実現としての提案がございました。","voiceIndex":21,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今おっしゃられた地域生活支援拠点等の機能を担う知的障害者グループホームということでも、区としても求めているわけですよね。この地域生活支援拠点というのは、具体的にどのような機能になっていくのか、伺いたいと思います。それは地域拠点相談支援センターとは全く別なのか。地域生活支援拠点というものの位置づけというのがよく分からなかったので、それも教えていただきたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今回、こちらの地域生活支援拠点としてのグループホームですけれども、まず、短期入所、こちらの施設があるということが大きなポイントになります。機能の充実として、短期入所、２部屋を設けています。","voiceIndex":23,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この体験の利用ができるというのは、ずっと皆さんからも要望が出されていたことなので、これができるというのは本当によかったと思います。この地域生活支援拠点というのは、品川区内のほかにもこういう位置づけのところはどんなところがあるのか、これも教えていただきたいと思います。どこが低い配点になっているのか。ここは少し心配だというところがないのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"これはごくごく自然のことだと考えております。今回の得点率、差としては４８点、率にして１２％ですけれども、選定委員会におきましても、ほぼ７割取得しております。この候補者が指定管理者として適格であるとの選定委員会の判断というのは妥当であると考えております。","voiceIndex":25,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今みたいに、本当に議会が議決するわけですから、これは指定管理者というのは、議会で議決されなければ指定管理者になることはできませんというのも、この公募要領に書いてあるわけですよね。そういうところで言えば、議会が責任を持って選定できる、議決できるように、私は資料をできる限り出していただきたいということは改めて求めておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１点質問なのですけれども、その前に、私もこの点数を見たときに、この点数はどうやって出てきたのかというところと、どこが高くてこの業者に決まったのだろうというところがすごく気になっていたところですので、そこを開示することによって、区民の皆様も納得感を持って、この業者でよかったと思えると思いますので、その点については適宜情報も見せていただきたいというところがあります。","respondent":"川崎障害者施策推進課長","answer":"人材確保面での安心感というところなのですけれども、本部から直近で、この二、三年、６名の方が首都圏に異動しております。その方も見据えて、今後、障害者グループホームに人員を配置していきたいという提案がございました。","voiceIndex":29,"id":"exchange-009"},{"speaker":"ひがし委員","kind":"意見","question":"６名来てくれたという実績があるからということで、何もつながりがないよりも、専門学校とかと提携して、こういうところを造るからということで新規の方を入れるというのはとても重要なことかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほど鈴木委員からご指摘がありましたけれども、報告書の内容が若干薄いのではないかみたいなお話がありましたが、それはもともとこのぐらいの内容で大丈夫なのかという判断なのか、もしくは、皆さんやはりお忙しくて、なかなか報告を上げる人員的な問題で、本当はもう少し充実させたいのだけれども、これぐらいになってしまったという結果なのか、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"先ほども申しましたように、品川区指定管理者制度活用に係る基本方針というものがございまして、こちらのほうに選定結果の公表ということで、応募事業者の名称や候補者選定方式・理由、選定委員の名簿等、公開すべき必要項目というのが載せてあります。","voiceIndex":33,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問","question":"今回選定して、１者に決まったということですけれども、説明会には６者来て、それで公募されたのが１者だといったところで、先ほどの説明で選定されたということでした。１者で競争倫理が働いていないという中で決まっていくというのは、プロセスは先ほどお聞きしたのですけれども、その辺はどのように考えて、１者だったからここで仕方なくというのも変ですけれども、決まっていったのか。","respondent":"川崎障害者施策推進課長","answer":"１者の応募しかなかったから選ばざるを得なかったということではなくて、公正に審査、そして選定をしたものと認識しております。","voiceIndex":36,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"それは体験のをつくるとか、あるいは、重症化している方の受入れをどうするかとか、その辺をもう少しほかのいろいろな事業者、プロポーザルとしてプロポは受けていませんでしたけれども、この辺がこのようによかったのだ、いわゆる受入れとして、うちとしてそういうことで、例えば重症支援の方を受け入れる、ここだなと決め手になったあちらのプロポはどんな感じだったのか、その辺を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"実際、バックアップ施設がある首都圏事業部では高齢者の施設がありますので、介護福祉士、それから理学療法士と、身体面での介助とか、あと、医療的なリハビリテーションということで、専門的な専門家との連携というのが受けられる、アドバイスを受けられるということは。","voiceIndex":38,"id":"exchange-013"},{"speaker":"こんの委員","kind":"提案","question":"体験のほうはどういう感じですか。体験できる施設についてのあちらの提案、こういう形で体験をできるようにしますという、あちらの提案はどんな様子だったのでしょうか。決め手となったあちらの提案理由というのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"体験利用としては、区としては今回初めての利用の施設になります。体験利用の空き情報も提供して、積極的に受け入れて、地域移行支援の拠点となるように努めていきたい、そして、ほかの事業所ともそこの辺りを情報提供しながら、積極的に受け入れていくという提案がございました。","voiceIndex":40,"id":"exchange-014"},{"speaker":"こんの委員","kind":"確認","question":"いわゆる先ほどの重度化している方とか、高齢化している方の受入れの体制、これについてのご説明は、いろいろな専門家のアドバイスも受けながら、そういうサポート、バックアップと言っていいのでしょうか。そういうこともあるといったところでも、港区での実績などがそうした選定の一つになったのかというのが１つ確認です。その辺を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"その通過として一つ体験利用というのは必須の施設だと考えていますので、そういった方を柔軟に受け入れて、親御さんも安心していただいた上で、グループホームや地域で一人で生活していく。こういった一つの通過点になればということは考えております。","voiceIndex":42,"id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"初めての事業者というところなので、都内あるいは関東近県で実績のある事業者だというところなのですが、品川区としては初めての事業者なので、より細かく確認をしていますけれども、今回、このグループホームを造るに当たって、西大井三丁目の地域の方、それから近隣の大井七丁目地域の方、いろいろな声が当時上がりました。その辺を伺いたいです。","respondent":"川崎障害者施策推進課長","answer":"港区のほうでも展示会を開催したりして、１階が体育館になっていますので、年間を通じて障害者の方の展示をしたりとか、また、あそこの体育館は選挙にも使われていたり、投票所にもなっておりまして、そういった形で地域に様々な形で貢献していく。","voiceIndex":44,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"必要な施設ですし、どなたかが、どこかの事業者に、やはりあそこの施設を有効活用するためには、していただかなければいけないですし、その中で、先ほどほかの委員からもありましたけれども、厚生委員会でも視察をしていたという事実もあるということなので、一定の議会としての、ここの委員会のメンバーではないにしても、厚生委員会としてそうした見てきたという、過去にあったということですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"おぎの委員","kind":"質問・要望","question":"質問というよりも要望なのですが、こちらの業者の説明の資料を見まして、私もホームページ等でこちらの会社を拝見させていただきました。選定の経緯に関しましては、先ほどから意見がありますように、点数の内容などを少し教えていただけるとうれしいです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど来から、報告書の説明が不足しているのではないかというような、委員からのご質問がありましたけれども、３ページの評価項目・配点で条例規定項目というのがあるのですけれども、この条例というのは、品川区立高齢者多世代交流支援施設条例のことでよろしいのかという確認をまずさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"配点は、この比重は条例とかの中で決まっているのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"特に決まってはございません。","voiceIndex":56,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"この配点にした理由というのはあるのですか。特に４番目の、十分な能力を有しているというのが大きなあれになっているのですけれども、配点の比重の、こうした配点にした理由というのはあるのですか。","respondent":"川崎障害者施策推進課長","answer":"今回の障害者グループホームは、先ほども申したように、地域生活支援拠点、この機能の充実を図る障害者グループホームですので、４番の(1)のところ、この配点が大きいのは、地域生活支援拠点としての設置目的を満たす内容になっているか。","voiceIndex":58,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"それは区側としてその項目を重視したというのがあったということでよろしいのかということと、あと、点数なのですけれども、委員の点数の合計により審査を実施したということで、合計点が載っているのですけれども、各委員が何点つけたのかというのは、これは公表しないという理由があるのですか。","respondent":"川崎障害者施策推進課長","answer":"項目、配点等、こちらは区のほうで部として決定をしたということになります。そして、点数につきましても、基本方針に基づきまして、採点表、総合得点のみとなっております。","voiceIndex":60,"id":"exchange-022"},{"speaker":"こしば副委員長","kind":"確認","question":"今回、指定管理ということで、当然に実際現場で働く方の採用基準、人事権というのは、指定管理者の長岡の方針になるという認識でよろしいですか。その確認だけ。要は、採用基準とか採用人数、人事権というのは指定管理者にあるのかどうかという。","respondent":"川崎障害者施策推進課長","answer":"人員体制ということのご質問でよろしいですか。","voiceIndex":63,"id":"exchange-023"},{"speaker":"こしば副委員長","kind":"提案","question":"この法人は長岡のほうで専門学校を運営されているということなのですけれども、そうすると、分からないですが、専門学校からいらっしゃる方もいらっしゃるかもしれません。人事権は品川区にあるわけではないわけですけれども、そこはぜひ要望といいますか、提案をしていただきたいと思いますけれども、その辺のお考えを教えていただきたい。検討しているのかどうかも含めて。","respondent":"川崎障害者施策推進課長","answer":"あくまでも人員については、向こうも介護専門学校がありますので、そちらの学校を卒業された学生もちろん実地の研修が必要ですので、港区なり首都圏のほうで勤務を経た後に、出石のほうにも配置を順次していくような形になるかと想定しております。","voiceIndex":67,"id":"exchange-024"},{"speaker":"こしば副委員長","kind":"提案","question":"私が聞きたかったのは、品川区の介護福祉専門学校のほうから、あくまでも人事権は向こうにあるのは分かっておるのですけれども、そういうのを区のほうで提案をしていただくことはできるのかどうかという話なのです。","respondent":"川崎障害者施策推進課長","answer":"品川区の介護福祉専門学校のほうにもこの法人の周知はしておりますので、今後そういった形で事業者を周知しながら、体制を整えていければと思います。","voiceIndex":69,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"意見","question":"賛成です。グループホームは、当事者や家族からはとても待ち望まれている施設であり、それができるということは本当に期待できるところです。その中でも体験施設ができるということも、当事者から本当に喜ばれるものだと思います。今回の指定管理は、障害者福祉の運営でも経験豊かな長岡福祉協会が指定管理者になるということで、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-026"}]},{"id":"topic-02","title":"第４２号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"第４２号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"この寄附を頂いた方からは、高齢者福祉の進展のために使ってもらいたいということで寄贈を受けたということであるのですけれども、どんなことに使うかというのは予定されている、考えられていることがあるのか伺いたいと思います。この高齢者福祉の進展ということ以外の要望というのは出されていないのか、その点についても伺います。","respondent":"東野福祉計画課長","answer":"どういったものに充てていくか、どういったものを寄附をいただいた方の意向に沿った形で使っていくかにつきましては、十分な検討をしていきたいと考えています。","voiceIndex":84,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"確認","question":"その場合、例えば、亡くなられた家族の方とか、そういう遺族の方とかに、使う前にそういうことは確認を取ってから使うのか、そこのところだけ伺います。","respondent":"東野福祉計画課長","answer":"これまでの社会福祉基金などにつきましては、ご寄附された方に対して、事前にこういったものに使いますという形でのご説明はしていないと聞いております。","voiceIndex":86,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう遺族の方から納得いかないみたいな声も、品川区のほうに伝えたかどうか分からないのですけれども、そういうことがないような形で、ぜひ意思を活かされるような形での、ただ税金で決まったものを置き換えるみたいな、そういうことではなくということを遺族の方から伺いましたので、そういう声も踏まえた形で、ご寄附をいただいた方の思いが活かされるような形での検討を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"１つ、条文の中の私の理解を深めたいというか、今回、高齢者福祉基金は初めてできたというか、今までに今年の３月にできたものなので、あれなのですが、この条文の中で、すみません、高齢者福祉基金というのと、その上に高齢者用社会福祉基金という言葉が出てきているのですけども、参考までに、高齢者用社会福祉基金というのはどういったもので、これまでどういったものに活用されたのか。","respondent":"東野福祉計画課長","answer":"そのときに使った言葉として高齢者用となっておりますが、今回といいますか、第１回定例会で設置したときにつきましても、同じような目的のもの、ただし、お名前は伏せてくださいということでしたので、高齢者福祉基金ということで使わせていただいたもので、高齢者用。","voiceIndex":90,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"分かりました。そうすると、ここで条文の中では立て分けて書かれているのですが、活用するとなると、高齢者福祉基金、高齢者用社会福祉基金の方が寄附されたものと、今回創設されたものとは、使うときにというか、活用されるときには一緒に活用するという考え方もできるという理解でいいのでしょうか。その辺のこの基金の使い方というか、その辺も少し教えていただきたい。","respondent":"東野福祉計画課長","answer":"先にありました高齢者用、こちらはお名前が入っているものですので、今出ている矢部様から頂いたものに対しましてはこういったものに使いました、それから、今回積立てをした高齢者福祉基金につきましては、お名前が入っていないものとしてということになりますので。","voiceIndex":92,"id":"exchange-031"},{"speaker":"こんの委員","kind":"確認","question":"もう一つは、個人情報なのであまりあれですけれども、この寄附をされた方、お一人の方は亡くなられた方で、もう１人の方はご健在だという中で、これまで、今回のこの高齢者福祉基金ということでのお二人ですけれども、そうではない形のときには、過去には社会福祉として事業者も寄附をされているということもありまして、個人の場合というのは、いわゆる現役世代の方なのか、それとも。","respondent":"東野福祉計画課長","answer":"個人情報になりますので、あまり詳しくはというところなのですが、公正証書に書かれているですと、一定程度、そういったことを予想されていた方かと思われますので、ある程度お年を召した方になるかと思われます。","voiceIndex":94,"id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"区民の方の思い、寄附をしてくださった方の思いというのは形に、寄附をされた方が今現在いらっしゃる方もいらっしゃらない方も含めて、この基金が有効にその方の思いがきちんと区民の方への使われ方になるように、今後、使い道はこれからだということですので、ぜひ有効に使わせていただくよう、感謝して使わせていただくよう、中身を検討をしていただきたいと。このように要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"別表の記載について伺いたいのですけれども、矢部久子高齢者用社会福祉基金から今回の高齢者福祉基金まで、基金の額について、５条の規定により処分した額を減じた額と書いてあるのですけれども、それと比べて、武田みつ社会福祉基金から城南信用金庫創立五十周年記念事業社会福祉基金は、５条の規定により処分した額を減じた額というのは書いていないのですけれども。","respondent":"東野福祉計画課長","answer":"品川区の社会福祉基金条例の第５条は、当該基金の目的に必要な場合、その全部または一部を処分することができるとしております。","voiceIndex":98,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、城南信用金庫の福祉基金から上の５つの基金は、使う予定というのはあまり想定はしていないということなのでしょうか。","respondent":"東野福祉計画課長","answer":"今回はあくまでも高齢者福祉基金についてということになりますが、それの上、障害者福祉基金、社会福祉基金、いろいろありますが、社会福祉基金条例の中のものの一つという形になりますので、まだ積立てはしていますけれども、これを特別充ててあるということではないです。","voiceIndex":100,"id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問","question":"すみません。この基金というのは今どれぐらいたまっていらっしゃいますでしょうか。","respondent":"東野福祉計画課長","answer":"この後また補正予算のほうでもご説明しますが、社会福祉基金積立ての見込額ですが、令和５年度末で３億６,６０８万６,０００円です。高齢者福祉資金につきましては、１,８００万円です。","voiceIndex":105,"id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"質問","question":"高齢者福祉基金は１,８００万円で、直近で活用した実績というのはないのでしょうか。","respondent":"東野福祉計画課長","answer":"直近の活用実績はございません。","voiceIndex":107,"id":"exchange-037"}]},{"id":"topic-03","title":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第３５号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"返還額が１億７,０００万円という、すごく額が大きいと思うのですが、国庫の補助金と実績額の差が出た理由というのを教えていただきたいです。","respondent":"豊嶋生活福祉課長","answer":"こちらは、実は令和３年度から続いているものでございまして、年度をまたいでいる関係でかなり複雑なのですが、既に返還が済んでおります令和３年度のものからご説明しますと、実は一番最初の令和３年度に実施しました給付金が、２月３日から。","voiceIndex":125,"id":"exchange-038"},{"speaker":"ひがし委員","kind":"質問","question":"ということは、今の説明でいうと、事務費のほうが前半のほうでたくさんかかっていて、後半はかからなかったから、その分金額が大きくなっているという理解で間違いないでしょうか。","respondent":"豊嶋生活福祉課長","answer":"委員ご指摘のとおりです。","voiceIndex":127,"id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問","question":"(1)と(2)のところの事業費のところで、９,９０９世帯に支給と、３万５,９５３世帯に支給とあるのですが、このうち家計急変世帯がそれぞれ何世帯かが分かったら、教えてください。","respondent":"豊嶋生活福祉課長","answer":"家計急変世帯です。(1)番のほうの家計急変世帯は、支給数が３６３世帯、それから、電力・ガスのほうになりますが、家計急変世帯の支給数は３２６世帯です。","voiceIndex":130,"id":"exchange-040"},{"speaker":"こんの委員","kind":"質問","question":"これ、実績のほうで、事業の実績として、今、世帯数が２つ、(1)と(2)で出ていますけれども、おおよその内訳を参考までに伺いたいと思います。いわゆる保護受給者、保護外の非課税の方、今、家計急変は数字をいただきましたけれども、その辺の世帯の内訳と、あと、おおよそ申請者の見込みはどれぐらいを見込んでいたのか。その辺を伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"現在、およそ４,３００世帯の方が生活保護を受けていらっしゃいますので、その差額分が非課税世帯の方というふうに、こちらのほうでは認識をしております。","voiceIndex":133,"id":"exchange-041"},{"speaker":"こんの委員","kind":"質問","question":"よく分かりました。そういったことも、住民基本台帳上では、この方かという予測は立てているものの、今、ご説明いただいたようなケースもあって、そうした方々が返還の対象となるということは、おおむね申請をする対象の方は行き渡っている、ここでよろしいですかね。対象の方が漏れなく給付を受けられるようにしていただくのが大事だったかと思いまして、その辺はどんなことをされてきましたでしょうか。","respondent":"豊嶋生活福祉課長","answer":"今回の本件とは関係ありませんが、令和５年度の給付金の準備をしている最中です。今回はこれに加えまして、申請をされていない方には勧奨はがきを郵送することも検討しておりますので、その辺りも含めて今動いているところです。","voiceIndex":135,"id":"exchange-042"},{"speaker":"こんの委員","kind":"意見","question":"家計急変の家庭を特定してこちらでお声をかける、なかなか難しいことではあるので、あらゆる媒体を使って、周知というか、声かけをしていくという形で、今おっしゃってくださった、令和５年度では勧奨もしてくださるということですので、また、今年度の給付、国からの１世帯３万円というものについては、これまで給付金の申請をされた方には、申請の口座が変わらなければ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-043"},{"speaker":"筒井委員","kind":"確認","question":"基本的な確認になるかと思うのですけれども、国庫補助金と実績額に差が出たら国に返還するというのは、これは決まりというか、法的根拠は何かあるのでしょうか。","respondent":"豊嶋生活福祉課長","answer":"各給付金が始まる前には、給付金の交付について、国から通知、事務連絡等々がやってまいります。そちらのほうに全て細かい、いつまでに返還をしなさいというものが書かれているものです。","voiceIndex":139,"id":"exchange-044"}]},{"id":"topic-04","title":"令和５年請願第６号、補聴器購入費助成制度を求める請願","agenda":"令和５年請願第６号、補聴器購入費助成制度を求める請願","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"今年度の予算なのですけれども、補聴器購入助成制度、今年度の予算額と、あと、算出の根拠を教えていただきたいという点が１点。もう一つが、現在、対象者が高齢非課税者となっているのですが、高齢非課税者の品川の割合と人数も教えていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"うち、購入費の助成につきましては、非課税の方を対象として、３万５,０００円×８０人分を対象として予算を立てております。２点目のご質問についてです。高齢者の非課税のおおよその人数ですが、こちらの手持ちの資料で調べた結果、４万人ほどです。","voiceIndex":156,"id":"exchange-045"},{"speaker":"ひがし委員","kind":"質問","question":"今、一般的に言われていることなので、詳細はあれですけれども、耳の聞こえづらさを感じている高齢者は３人に１人と言われておりまして、今、非課税の高齢者の人数が４万人。単純計算すると１万３,０００人、その対象になるであろうたちがいるということで、今のところ８０名分の予算が組まれている。今後の見通しという区の考えも教えていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"今の段階で、申請件数につきましては、まだ助成そのものは実施をしていないのですが、紙ベースで受付をしていただいている高齢者の皆様２０件ほどありますので、そこからその方が医療機関を受診して、確実に補聴器が必要だとお医者様に判断していただきまして、そして。","voiceIndex":158,"id":"exchange-046"},{"speaker":"ひがし委員","kind":"質問","question":"今の現時点だと、予算と対象者の人数が大きく乖離があると実感しております。資料も取ってきたのですけれども、すごく分かりやすく内容が書いてあると思うのですが、また、認定補聴器技能者が在籍する店舗というのが７軒ほどあるみたいなので、ここと連携しながら、この制度というのを進めていく予定ということで間違いないのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"今の委員ご指摘のとおり、７店舗ございまして、技能者の方と、この間、全て７店舗、職員で回ってまいりまして、ご挨拶含めて、今後の連携方法については、引き続き行っていくというふうに話をしています。しっかりと連携を取っていきたいと考えています。","voiceIndex":160,"id":"exchange-047"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今言った連携というのがとても大切なことだと考えていますので、職員の方々がこの７店舗を回られたということで、いいことだと考えています。この結果を踏まえて、区民の方々にも実施状況というのを適宜お知らせいただけると、区民の納得感と安心度も高まるのではないかと思いますので、その点は要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの請願の２番の聴力検査の件でお伺いします。もし国保のそういった検査項目等で入れられない、そういった一括で一斉検査ができないということでしたら、検査をされた方に助成金を出すなど、そういった予定等はないのでしょうか。","respondent":"池田国保医療年金課長","answer":"助成金につきましては、他区でやっているところもありますけれども、現在、品川区としましては、難聴の部分の検査ということについて、まだ深いところまで研究していないところでございまして、今のところ、すぐにというところではご答弁はできないところです。","voiceIndex":164,"id":"exchange-049"},{"speaker":"やなぎさわ委員","kind":"質問","question":"区内の認定補聴器技能者というのは７店でいらっしゃるということなのですけれども、人数としては総勢何名いらっしゃるのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"認定補聴器技能者の人数、在籍店舗にいらっしゃる人数です。７店舗合計で１５名の技能者の方がいらっしゃいます。","voiceIndex":168,"id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"質問","question":"こういった技能者の方は、補聴器を買いたいという購入を希望している方のご自宅に伺ったりとか、そういうサービスとかというのはあったりしますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"訪問のサービスの有無につきましては、各店舗の状況等、こちらから確認はしていないので、ここでは申し訳ないのですけれども、私が聞いている範囲では、お店に行っていただくというところで、その店舗の中には、店舗で用いている聴力検査であるとか。","voiceIndex":170,"id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"質問","question":"つまり、聴力検査の機器というのはなかなか持ち運びが難しいという解釈でよろしいですか。","respondent":"川原高齢者地域支援課長","answer":"訪問サービスでの営業販売というところではなく、きちんとした店舗での営業販売というところ、また別であると考えていますので、まずは店舗に出向いていただいて、きちんと予約をしていただくことが望ましいと思っていますが。","voiceIndex":172,"id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"提案","question":"私自身、介護職を１３年していて、難聴の高齢者の方といろいろお話しする機会が多いのですけれども、高齢者の方というのは、やはり出向くのが大変だったりする方が結構いらっしゃって、それで、これはあくまで提案なのですけれども、要は、いろいろ会社、メーカーによって、自分の耳に合う合わないという相性があったりとか、もしくは、そのメーカーの中でも、高い、普通、安いみたいな値段設定の中で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":174,"id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"補聴器補助制度ということについては、共産党としてはずっと、都議団としても２０１２年から聞こえの支援に関しての提言を出して、支援を求め続けてきましたし、区議会でも、２０１９年６月に一般質問で私が取り上げたところから始まって、区民の皆さんからも、この請願にも書かれているように、既に８回、今回で９回目という形で請願が出され、そのたびごとに採択を求めて要請してきましたので。","respondent":"川原高齢者地域支援課長","answer":"所得制限を非課税者対象として限定しているかということにつきましては、今、私の手元にあるのが東京都の福祉保健局在宅支援課長からの補聴器に対する補助の考え方について、令和２年度の事務連絡、それ以降、まだ新しいものが出ていないので。","voiceIndex":176,"id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１,０００円で医師の意見書を書いてくれる耳鼻咽喉科というのが一覧表で書かれていると思うのですけれども、この１,０００円で意見書を書いてくださるという耳鼻咽喉科は、補聴器相談医の医療機関なのかということでも伺いたいと思います。ぜひそういうのもしていただきたいと思うのですけれども、その点についても伺います。","respondent":"川原高齢者地域支援課長","answer":"そして２点目、医師の意見書、証明書の作成料が一律対応の医療機関は、６月２６日現在では２３医療機関あるのですが、こちらも随時調査をさせていただいておりまして、日々、恐らく増えていく見込みがあるものと考えています。","voiceIndex":178,"id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから補聴器の相談医だけではなく、全ての耳鼻科のドクターであればどこでもいいということが品川区のことになっていると思うのですけれども、今回の厚労省の研究の提言のところでも、補聴器相談医や認定補聴器技能者との連携ということがかなり強調されていると思うのですが、そういうところでいえば、補聴器相談医のところに初めにかかって。","respondent":"川原高齢者地域支援課長","answer":"なぜ補聴器の相談医というふうに限定をしなかったかという点ですが、先ほど申し上げたように、まず間口を広げて、耳の聞こえに不安を感じたら、医療機関、耳鼻咽喉科のお医者様にかかっていただきましょうという普及啓発も含めてお声がけをしているところでございまして、ただし。","voiceIndex":180,"id":"exchange-056"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、どれだけの年金かというと、１２万円少しなのです。そのようなところで、私は非課税から課税者までしたとしても、区の負担では十分にできる、そういう額ですから、非課税者だけでなく、課税者まで対象にするというところで、どれぐらいの人が課税者なのかというのは、高齢者の実態というのも見ていただいて、ぜひ検討をしていただきたいということで、これは強く要望をしておきます。","respondent":"川原高齢者地域支援課長","answer":"今、委員ご指摘のとおりです。購入に際して、認定補聴器技能者、または言語聴覚士が在籍する店舗でのみ購入可能という形にしております。","voiceIndex":182,"id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問・要望","question":"認定補聴器技能者なのですけれども、先ほど区内に１５名ということだったのですが、ホームページで認定補聴器技能者検索システムというところで見ると、品川区は３７名ということで、名前とどこでやっているかということで３７名書いてあって、すごく品川区は認定技能者が多い区なのだと思ったのですけれども、これと１５名というのは差があるのですが、それはどう考えたらいいのか。","respondent":"川原高齢者地域支援課長","answer":"委員ご指摘のホームページの検索システムによると、三十数名という人数が出てくるのですけれども、今回、この助成の要件として掲げている認定補聴器技能者在籍店舗、こちらの店舗にいらっしゃる方が１５名という形になってございまして。","voiceIndex":184,"id":"exchange-058"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。それなので、やはり補聴器というのは本当に高額ですので、そこに近づけるという形では、今後というか、ぜひ検討していただきたいと思うのですけれども、その引上げについてはこれからも検討していくということで考えられているのかも伺いたいと思います。そこの仕組みが分かったら、教えていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"必要な非課税の方にしっかりと丁寧な対応を寄り添って行うというところを注視してまいりたいと思ってありますので、都の補助金の要綱、要領ですとか、他区の自治体の動向を引き続きしっかりと情報収集しながら研究してまいりたいと考えています。","voiceIndex":186,"id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もう一つ、健診制度なのですけれども、これは私も１９年のときにこの補聴器の質問をしたときにも、健診の中に聴力検査を入れてほしいということで要望したのですが、そのときは、高齢者の聴力低下は自覚ができて、家族など周囲が気づくので、実施する考えはないという答弁だったのです。","respondent":"若生健康課長","answer":"難聴に関しての健診制度では、以前、私どものほうの答弁としては、身の回りのご家族ですとか、あるいはかかりつけの医療機関等で気づけるというようなところでの認識でお答えしたところでございまして、それについては、現時点でもそういう状況というのは間々あるかと思います。","voiceIndex":188,"id":"exchange-060"},{"speaker":"鈴木委員","kind":"提案","question":"この当時からやはり加齢性難聴は気づかないうちに進行するというのが、本当に様々な論評の中、そのようなことがたくさん出ていて、それが当たり前という捉え方だったと思いますので、まずは健診が必要だ、それで、医師会の先生からもずっと求められておりましたので、ずっと提案もしてきたわけですけれども、そういうところでは早期に発見して、早期に補聴器を装用して、そして、進行して。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-061"},{"speaker":"こんの委員","kind":"質問・要望","question":"今回７月からスタートして、こちらは皆さんの要望でもあったことが実現して、本当によかったと思います。そのときに、まずは非課税世帯から始めたのですけれども、確認ですが、先ほど都の補助金も使って、あるいは国の動向も見てということですけれども、この先、いわゆるこれでおしまいではないですよね。これをまず確認させてください。","respondent":"川原高齢者地域支援課長","answer":"今ようやく、先ほど申し上げたように、スタートラインに立ったということで、まずは決められた要件の方にしっかりと助成を迅速に行っていくというところは考えて、事業を行っていきたいと思いますが、一方で、引き続きいろいろな情報収集等、都や国、自治体の状況も勘案しながら。","voiceIndex":192,"id":"exchange-062"},{"speaker":"こんの委員","kind":"質問・要望","question":"３番の、港区並みに早期に引き上げてくださいというところですけれども、確かに港区は、それぞれの自治体の財政の使い方ですから、そのように重点的にできる区もあれば、そうではないところが重点で予算を使う区もあるので、それは羨ましくはなるのですけれども、やはり品川区としての財政を使っていくという意味で、区民の方のお声をできるだけ反映できる、そうした形で今後進めていただきたい。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました。今後のアフターサービスの部分に関してなのですけれども、購入して助成させていただいた方へ、一定の期間を経て、アンケートを実施していきたいと考えております。","voiceIndex":194,"id":"exchange-063"},{"speaker":"こんの委員","kind":"質問","question":"２番の検査なのですけれども、まず、この請願の書かれている高齢者健康診査、これはどういったものをおっしゃっているのでしょうか。診査も「審」という字を使われているので、これは特定健診のことをおっしゃっているのか、何の健診のことをおっしゃっているのか、どういったものなのでしょうか。そこら辺をお聞きしたいと思います。","respondent":"池田国保医療年金課長","answer":"高齢者の健診です。健康診査ですけれども、私どもとしましては、高齢者の健康診査という形での診査という形で捉えておりまして、実際、身体計測、血液検査というような、健診という形で先ほどお答えをさせていただいたところです。","voiceIndex":196,"id":"exchange-064"},{"speaker":"こんの委員","kind":"質問・要望","question":"私も課長の先ほどのご答弁を伺ったときに、そのように捉えたものの、請願の項目にはこのように書かれていらっしゃるので、どこの検査のところで求められているのかというのが少し疑問でした。分かりました。","respondent":"池田国保医療年金課長","answer":"特定健診のほうでも、聴力の検査はしておりません。","voiceIndex":198,"id":"exchange-065"},{"speaker":"こんの委員","kind":"質問・要望","question":"していないということですので、ここは高齢者に限ってだけではなく、全体的に聴力検査というのは今後も必要なのかと捉えました。ですので、国のほうに、そうした年齢に限らず聴力検査というのは求めていかなければいけないことなのだろうと思います。ここの請願の内容では、高齢者という形で限っていますが、それに限ることとなく、聴力検査というのは必要なのかと捉えたところです。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"高齢の課税者の人数についてなのですけれども、６月の人口統計を見ますと、６５歳以上の方が約８万人いらっしゃるので、先ほど高齢の非課税者４万人ということで、差引き４万人が高齢の課税者という理解でよろしいのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"そのように捉えております。","voiceIndex":202,"id":"exchange-067"},{"speaker":"筒井委員","kind":"質問","question":"ということで、課税、今回の助成を広げても、４万人ぐらいが追加されるということだと考えています。先ほどほかの委員からもご質問ありましたけれども、近年は所得制限を設けないというのが、こうした助成や給付ではトレンドというか、そうした流れになってきているかと考えています。どういったお考えをお持ちなのか、お聞かせください。","respondent":"川原高齢者地域支援課長","answer":"確かに先行的に高い補助の金額を実施しているということは区としても認識してございまして、実際の港区の補聴器助成の担当にもヒアリングをするなど、引き続き情報収集をしています。それを踏まえた上で、今後の状況については検討してまいりたいと考えています。","voiceIndex":204,"id":"exchange-068"},{"speaker":"筒井委員","kind":"質問","question":"品川区として、港モデルのような、こうしたことを導入するに当たり、財政的に厳しいとか、そうした理由でなかなか港区並みにできないというのはあるのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"財政面で厳しいかというところだけを理由としているものではございませんが、まずは導入の自治体もまだ２３区中、半数以上にようやく広がったところであるのですけれども、実際に港区以外の区では、大体２万円から３万円が平均的な助成額ですので、港区だけではなくて。","voiceIndex":206,"id":"exchange-069"},{"speaker":"筒井委員","kind":"質問","question":"今年の７月からようやくこの補助事業が始まったということなので、急に港区とかに合わせるというのはなかなか難しいかと思うのですけれども、今後の他区の状況とか都や国の動向を見て、ほかの委員からもご質問ありましたけれども、完全に高齢非課税者に限って補助金額を３万５,０００円というのをずっと固定化するというか、これ。","respondent":"川原高齢者地域支援課長","answer":"先ほどご答弁申し上げたとおり、ようやく助成のスタートラインに立てたですので、まずは現行の制度に見合った、また、一人一人丁寧に対応していく中で、どのぐらいの申請件数が上がっているかというところ、申請件数等も引き続き調査をした上で。","voiceIndex":208,"id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、再三出ていることですが、ひとまず３万５,０００円非課税ということで一旦始めますと。様子を見ながら、例えば、金額を増やしたりだとか、課税者にも対象を広げるとか、そういったことを前向きに検討してくださるということでよろしいですか。","respondent":"川原高齢者地域支援課長","answer":"検討の内容については、ここまでまだ未決定の段階です。すみません、申し上げることはできないのですけれども、引き続き情報収集と、動向を注視してまいりたいと考えています。","voiceIndex":211,"id":"exchange-071"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それは営業というか、お店からのお勧めがあったりするかもしれないし、本人が何となく高いもののほうが効果があるのだろうと思ってしまっている節もあるかもしれないのですけれども、ですので、ぜひ補助金もつくということですので、そういった、変な売りつけみたいなのがないのかというようなところも、こういった制度を使われた対象者の方に、使ってみて、買ったときのお話、どういう感じだったのかとか。","respondent":"川原高齢者地域支援課長","answer":"引き続きしっかりと普及啓発を行って、正しいところで正しいものを、その方に合ったものを購入していただくというところを引き続き実施してまいりたいと考えています。","voiceIndex":213,"id":"exchange-072"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。ということで、では、例えば、この助成制度を使って購入した方が、特定の販売店のところでやたら助成制度を使った後に買換えが多いとか、そういったことが頻発されるようなところがあれば、そこはもちろん指導したりとかもしてくれるということでよろしいですね。","respondent":"川原高齢者地域支援課長","answer":"品川区の消費者センター等の管轄との連携を図りながら、そういった購入の状況、購入した後の苦情等につながるケースはないかといったところは、アフターサービスの効果検証のアンケートの部分でもしっかりと聞き取れるようにと考えております。","voiceIndex":215,"id":"exchange-073"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"分かりました。ということで、個人的には、やはり先ほど鈴木委員がおっしゃったように、課税世帯といっても裕福とは言えないので、助成額を増やしていただきたいとは思いつつも、そういったところで、あってはならないことですけれども、販売店がうまく使わないようにというか、しっかりとその制度を保てるように指導というか、注視していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-074"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"理由としましては、自民党会派のほうでも、昨年の第２回定例会で、私から一般質問で、高齢者の社会参加の促進、また、認知症予防の観点から、補聴器の購入費の助成を求めてきた経緯がございました。なかなか使いづらかったとか、そういった課題があるのも事実ですので、そういったことは慎重に、しかし、止めることなく、進めていくべき課題であると思いますので、今回の請願に関しましては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-075"},{"speaker":"こんの委員","kind":"確認","question":"本日結論を出すでお願いいたしたいと思います。先ほども質問の中で確認をさせていただきましたが、本当に７月で始まったばかり、緒に就いたばかりですので、将来的には対象拡大といったところも見据えて、都や国の動向も注視をしていくと、先ほどの答弁も捉えましたので、今回の請願については、今、このときにはなかなか難しいかと捉えております。ですので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-076"},{"speaker":"ひがし委員","kind":"質問","question":"結論を出すで、採択でお願いいたします。しかし、今年度７月からこの補聴器の助成制度が導入されたばかりということ、また、現時点でも、先ほど答弁からも伺いましたが、対象の人数と、あとは予算額に大きく乖離があるということを答弁を聞いて伺いました。そのため、我が会派としては現段階では不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区は聴力検査は必要ないということで言われていましたけれども、そういうところも少し答弁が変わってきていますので、聴力検査についてもぜひともやる方向で検討していただきたいと思いますし、港区並みに早期に引き上げてくださいという項目に対しては、私は港区並みに引き上げれば、港区が１年間で約６００人を超えてこれが助成されたと伺っていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-078"},{"speaker":"筒井委員","kind":"意見","question":"本日結論出すで、不採択とします。理由は、私としても、課税非課税を分けるというのはいかがなものかと思いますし、請願者のお気持ちも非常に分かるところなのですけれども、何より今年の７月からスタートする事業でありますし、その事業の動向を注視すべきかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":224,"id":"exchange-079"},{"speaker":"おぎの委員","kind":"意見","question":"ただ、今回７月から新しい制度が始まったばかりですので、またそれで一度広げてみて、潜在的な希望者の人数や、あと、東京都から補助金が入る、そういったことも考慮しての適切な金額の設定、また、補聴器の選択から装用後のアフターケアまで含めて、そういった方向性を適切なラインで今後進めて、さらに拡充していくために、期待を持っての不採択です。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"本日結論を出します。採択でお願いします。これからスタートする事業なのでということはよく分かるのですけれども、それにしても３５０万円という予算はあまりにも少ない。２,０００億円、品川区の予算を動かせて、そのうちの３５０万円。先ほどお話のあった、耳の聞こえの集会ですか、シンポジウムですか、そういったのも大盛況だったというお話があるぐらいなので、それだけ注目度が高まっている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-081"}]},{"id":"topic-05","title":"令和５年請願第８号、大井・西大井地域に特別養護老人ホームの建設を求める請願","agenda":"令和５年請願第８号、大井・西大井地域に特別養護老人ホームの建設を求める請願","exchanges":[{"speaker":"ひがし委員","kind":"質問","question":"説明ありがとうございました。今、特別養護老人ホームの施設数、区内１２施設、そして新たに３施設建設予定というふうにお伺いしましたが、現在の入居可能数と、また増えた場合の入居の人数というのを教えていただけますでしょうか。","respondent":"東野福祉計画課長","answer":"現在の特別養護老人ホームの定員数、入居可能数ですが、９７３名です。整備後につきましては、２４５名増えまして、１,２１８名の定員となる予定です。","voiceIndex":235,"id":"exchange-082"},{"speaker":"ひがし委員","kind":"質問","question":"この請願の中には、待機者数４００名おりと書かれているのですけれども、区としての待機者数の把握状況を併せて教えてください。","respondent":"菅野高齢者福祉課長","answer":"９月と３月に会議のほうが開かれるのですけれども、令和４年度９月は申込者３９５人、３月は３８９人と４００人弱の方が申込みをされております。そのうちの大体１４０名前後の方が入所されているので、４００名の方が待機しているという認識は、区としては持っていない状況です。","voiceIndex":237,"id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問","question":"特養ホームがこれから３か所できるということで、今、２４５名が増えるということなのですけれども、都営元芝アパート跡の特養ホームと、それから八潮南の増築と、小山台住宅跡地ということでできるのですけれども、これはそれぞれ計画したのがいつで、計画してから開設まで何年くらいかかるのかというのを、３か所それぞれお聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"開設につきましては、令和９年度の予定です。都営元芝アパート跡地、こちらも令和３年度に都からの申入れがありまして、どういった形で跡地活用するかというものを考えてまいりました。こちらの開設予定は令和７年度です。","voiceIndex":240,"id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問","question":"小山台住宅もやはり７年ぐらいかかる。それから、元芝のところは若干少なくて６年ぐらいですか。こういうことを考えると、先を見通した計画というのが必要だと思うのですけれども、そこら辺のところの考え方はどうなのかということを１点伺いたいのと、それから高齢者がこれから増え続けるわけですね。３施設ではこれからも足りないという認識はあるのか。そのことについて伺いたいと思います。","respondent":"東野福祉計画課長","answer":"そういった土地の有無等につきましても、今後区としても十分民間の土地も含めて注視してまいりたいと考えています。","voiceIndex":242,"id":"exchange-085"},{"speaker":"鈴木委員","kind":"確認","question":"ここのところをちょっと確認したいのです。家族介護というのは、もうそういうふうな状況ではないと思いますので、そういう点では本当に深刻な状況がこれから広がっていくのではないかなという懸念があるので、そこのところを確認させていただいているのですけれども、３施設以降も特養ホームを造るという、区の政策的な考え方があるのかということを改めてお願いします。","respondent":"東野福祉計画課長","answer":"特別養護老人ホームにつきましても、絶対造らないかということではなくて、限られた資源の活用の中で、そういったものが必要とされる場合につきましては十分検討してまいりたいと考えています。","voiceIndex":244,"id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問","question":"そこのところの区としての認識が、だから今のところでははっきり分からないのです。３施設では足りないという認識はないのか。そしてまたそれに対して造っていく、そういう足りないという認識の下に、これからも造る方向でも検討をしますよという、区の政策としてそういう考えなのか、このところをちょっとはっきりと伺いたいのです。何かそこのところが出てきてないので。","respondent":"東野福祉計画課長","answer":"特にやはり大きな敷地・施設を必要とするようなものになりますので、それにつきましては、先ほど委員のほうからもお話があった高齢者人口の推移ですとか、需要者がどれだけいるかという部分を捉えた上で、全体の中で考えていきたいと考えています。","voiceIndex":246,"id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問","question":"改めてそこのところはお願いしたいと思います。そのＡ・Ｂ・Ｃの判定というのは、その基準とＡ・Ｂ・Ｃそれぞれ、Ａ判定というのは何点で何人いるのか、そしてＢ判定というのはどういうことを指しているのか、またＢ判定、Ｃ判定の点数と、例えば２月締切、３月入所調整会議で行われたその方の中で、Ａ判定、Ｂ判定、Ｃ判定の点数と人数、そしてその表す意味も伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"Ｂ判定の方が６５点から６９点で、Ａ判定の入所順位の方で申込みの取下げとか入所辞退があった場合に、やはり９月３０日までに入所の可能性がありますよという説明をさせていただいて、そして６４点以下がＣ判定ということで。","voiceIndex":248,"id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、本当にＣ判定が２５１名いるわけですから、これはほとんど入れないわけですから、入れないですよということをこの場で宣言される、そういうのが私はこのＡ・Ｂ・Ｃの判定だと思うのです。こういう点数で足切りというのですか、そういうふうなことでやらないと入れないという状況に対しては、どう考えられているでしょうか。その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"お申込みの際にも状況等をお聞きして、点数がなかなか伸び悩む方などにつきましては、比較的入りやすいところをお勧めするなど、いろいろと相談には応じしていますので、一概にＣ判定だから入れていないというわけではなく。","voiceIndex":250,"id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうふうなところで、土地の確保ができればやるというところは確認させていただいていいかどうか、そこのところもちょっとお聞きしたいと思います。そういうところで、今、保健センターの建替えによって、そこを仮施設とし使うことになっていますけれども、その後、特養ホームを造っていくという、ぜひそういう方針も出していただきたいと思うのですけれども、その点についてはいかがでしょうか。","respondent":"東野福祉計画課長","answer":"第一日野小学校跡のところの計画につきましては、現在区の企画調整課のほうで跡地活用のところの検討をしています。","voiceIndex":252,"id":"exchange-090"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、一番高齢者の実態を把握しているのが高齢福祉課、それから施設計画課もそういうところで直接高齢者の実態、高齢者にも関わりながら把握をしているところなわけですから、ここから要望を出さない限りはそこの計画にはなっていかないと思いますので、ぜひ、高齢福祉課のほうからも、特養ホームの整備に使ってほしいというふうに要望を出していただきたいと思いますけれども。","respondent":"菅野高齢者福祉課長、東野福祉計画課長","answer":"第８期の介護保険事業計画の中でも、今後について、高齢者人口の推移に合わせてサービス量を適切に見込みつつ、限られた資源を十分に活用しながら計画的な整備を検討していくと記載されております。そういったところを常にアンテナを張りながら、区として土地の購入ができるかどうかにつきましては、十分所管のほうとしても考えていきたいと考えております。","voiceIndex":254,"id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私が先ほど伺ったのは、ＴＯＣに貸し出していて旧第一日野小学校の跡というのは本当に一定の広さがあるわけですから、あそこに、この先のことを考えたら特養ホームをという要望を高齢福祉課のほうから出さないと、なかなか計画を検討するということにはならないと思うのですけれども、高齢福祉課のほうから要望は出さないのですかということで伺ったので、それを伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ご質問１点目の第一日野小学校の跡地についての特別養護老人ホームの建設等につきましては、区全体で受付のことの部分につきましては、高齢者福祉課が意見ということは、入所調整会議の結果ということでお伝えすることはできますが、成否の決定はないので。","voiceIndex":257,"id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうときに、やはり本当に近くの特養ホームに入れるとその関係が維持できるというかそういうところで、自宅では介護は無理だけれども、近くの特養ホームでできる限り見ていきたいという要望がかなえられるというのをもう何人もの方で見させていただいていますけれども、そういう点からも、地域の身近なところに特養ホームをというのは、本当に地域の方の切なる願いだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":259,"id":"exchange-093"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちらの書面のほうを拝見しますと、２点ポイントがあると思います。実際足りないと言っていることと、やはりこのエリアに造ってほしいといったこの地域の希望という面ですね。長期計画の中で、こういった地域のここの辺りの人が非常にこういったものを要望しているという地域ごとのニーズを拾い上げるような考えなどがもしあれば、ぜひいただきたいと思いますが、そういったものはありますか。","respondent":"東野福祉計画課長","answer":"ただ、委員のほうからもお話がありましたとおり、当然望んでいる方もいらっしゃいますので、そういったところを全体のほうを加味した上で、必要なバランスなどは考えていくべきではないかと思ってあります。","voiceIndex":260,"id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"今回はこうした請願で、大井・西大井地域ということなのですけれども、例えばこれは先ほど課長のご説明で、やはり特別養護老人ホームですから、一定規模の定員数を確保するということになると、約３,０００m2ぐらいの土地が必要だといったところで、やはり多くの方が入っていただけるそうした施設になれば、それだけの土地が必要だとなると。","respondent":"東野福祉計画課長","answer":"では実際に出てきたかというと、なかなか難しいという側面もありますので、今後もそういったところには、民間の土地も含めてアンテナを張って考えていきたいと考えています。","voiceIndex":262,"id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"それはそのように捉えております。ですが、地域の方のご希望の気持ちもよく分かる。その辺はどういうふうにお考えなのかというのが１つです。それから、この請願趣旨の中のところ、１点確認したいのですけれども、「区の窓口に行くと、８３歳以上でないと無理と言われ」と。これは８３歳以上じゃないと駄目というルールがあるのでしょうか。ここは確認をさせていただきたいと思います。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"最初に申し上げました限られた資源をどう活用していくかというところで、施設づくりにつきましては、区として十分考えて検討していきたいと思います。年齢におきましても、７５歳から５歳刻みで５点、１０点、１５点、９０歳以上だと２０点というふうに上がっていきますので、なぜ８３歳以上でないと難しいという発言になったのかがちょっと理解が難しくて。","voiceIndex":264,"id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"８３歳以上というこのことについては分かりました。民間の土地で探していくというのもありだと思うのです。けれども、そこら辺の予算、公有地を活用するのと、民間を活用するのと、アンテナを張っていただきたいところですが、民間を活用した場合、やはりどれぐらいの予算の規模を見ていく必要があるのかというのは、公有地を活用するのと比べるとどのような感じなのでしょうか。","respondent":"東野福祉計画課長","answer":"そこを活用するにあたっても、区としてどういうものが政策的に必要なのかどうかというところの検討する期間などもかかりますし、当然、設計費用・建築費用もかかってくるということになりますので、一概にどのぐらいということでは言えないのですけれども。","voiceIndex":267,"id":"exchange-097"},{"speaker":"こんの委員","kind":"確認","question":"もう一度確認ですが、だからバランスよく配置はしていきたいけれども、品川区全体を見てこうしたものを捉えていくという考え方なのか、それとも本当にバランスを見て、ここだけにいわゆる土地を探し続けていくという考え方なのか、特養を造るときの考え方として、もう一度確認をさせてください。","respondent":"東野福祉計画課長","answer":"そういったところを考えますと、まず区内としてどれだけ整備をしていくかというところもありますし、もちろん限られた資源、こういう公有地もありますし、民間土地を購入する際に必要な政策的な考え方、そういったものを全部総合的に勘案した上で。","voiceIndex":269,"id":"exchange-098"},{"speaker":"やなぎさわ委員","kind":"確認","question":"事実確認なのですけれども、「特別養護老人ホーム施設数は２３区の中でも下から４番目と聞いています」とありますが、これはいかがでしょうか。","respondent":"東野福祉計画課長","answer":"整備率というところになろうかと思います。こちらに書いてあるとおり、特別養護老人ホームにつきましては、２３区中２０位ですので、下から４番目というところで間違いございません。〔「何月何日時点でしょうか？失礼いたしました。令和５年１月１日現在で２０位です。","voiceIndex":271,"id":"exchange-099"},{"speaker":"やなぎさわ委員","kind":"質問","question":"低いというのは間違いないと思いますので、やはり入ってはいないのだろうなという認識はまずあります。ただ、品川区としては基本計画として、在宅支援を重視しているということで、たとえ２０位であっても、それ以上に在宅支援のほうに力を入れていて、足りない施設数をそういったところで十分カバーして手厚い介護サービスを行えているという認識でよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"品川区の在宅介護支援システムについてなのですが、区内に２０か所の在宅介護支援センターを中心に、高齢者福祉課を統括型の在宅介護支援センターとしまして、きめ細やかに相談等を受けさせていただいて、必要な介護サービスにつなげるというシステムを確立させておりますので。","voiceIndex":276,"id":"exchange-100"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、ほかの自治体にはない独自の取組をされていらっしゃるということですか。もしあるなら教えてください。","respondent":"菅野高齢者福祉課長","answer":"先ほど整備率のお話をさせていただいたのですが、例えば小規模多機能型の居宅介護の施設があるのですけれども、こちらについては２３区で３位ということになっておりますので、在宅のほうで力を入れさせていただいて、ここにグループホームとセットで造ったりとか。","voiceIndex":278,"id":"exchange-101"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ごめんなさい、もう一度確認なのですけれども、品川区で具体的にこういったところを在宅支援で重視しているという具体的なものというのは、自負はあるけれども、特にないということでよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"先ほども申し上げましたが、例えば小規模多機能の居宅介護の施設が２３区では３位ということになっておりますので、こちらのほうを充実させているというところと、あとは２００人超えのケアマネジャーたちいらっしゃるのですけれども、適切なケアプランを作っていただきまして。","voiceIndex":280,"id":"exchange-102"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これから高齢化がさらに進むと。それで、先ほど鈴木委員も御指摘のとおり、施設は高齢化が進めば当然足りなくなるということで、それに合わせて、在宅支援のサービスもより充実を深めるというようなことは計画されていらっしゃるのですか。","respondent":"菅野高齢者福祉課長","answer":"それ以外の施設の充実等、先ほども申し上げましたが、第８期の介護事業保健計画の中でも、人口の推移に合わせてサービス量を適切に見込みつつ、限られた資源を十分に活用しながらというところで、施設の計画以外にも、在宅のサービスの事業者等も誘致するなど。","voiceIndex":282,"id":"exchange-103"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ケアマネジャーのケアプランの作成の研修ですか。それも少なからずプラスにはなると思うのですけれども、やはり介護事業所の誘致と最後におっしゃられましたけれども、そういったものも当然、そちらのほうがむしろ力を入れていただきたいところかなと考えておりますので、在宅支援重視でということを標榜するのであれば、その点は具体的により計画を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問","question":"保健師、社会福祉士、主任ケアマネの３職種が配置された地域包括支援センターが地域に１か所もないという、そういう状況になっているということは、在宅支援を重視すると言うのだったらばもう一日も早く解消して、保健師も配置して、社会福祉士も配置して、地域包括支援センターに在宅支援センターを格上げしていくという、それが必要ではないかと思うのですけれども、その点を一つ伺いたいと思います。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"こういったところも、他区との比較もありますが、品川区として必要な施設につきましては、十分検討をしてまいりたいと思います。私からは、１つ目、地域包括支援センターの設置についてです。令和３年度第２回の特別養護老人ホームの入所調整会議の結果としましては、入所申込者が３７２人で、入所人数は１４４人ということで。要介護度につきましては、要介護度３が１６２人中６８人、要介護度４が１２９人中５１人、要介護度５が６３人中２１人という結果となっております。","voiceIndex":285,"id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、８０代の方も９０代の方もこういうふうな形で入れない。それから、要介護４の方でも１２９人中５１人ですから、要介護５の方でも６３人中２１人ですから、３分の２が入れないという、私はこれは本当に深刻な実態なのではないかと思います。だってそれが実際にこの点数ですから。そして、ぜひとも増設に向かっていただきたい、増設という計画も作っていただきたいということを改めて申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-106"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど在宅介護支援センターがしっかり機能されていらっしゃると、地域包括支援センターがなくてもというお話が少しありましたけれども、私は現場でずっと働いていた、品川で８年デイサービスの会社をしていますけれども、お話をケアマネジャーから聞くと、結構、どうして品川区は地域包括支援センターというシステムをとっていないのだろうということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":291,"id":"exchange-107"},{"speaker":"筒井委員","kind":"確認","question":"特別養護老人ホーム入所調整基準が挙げられていますけれども、確認なのですけれども、これは利用を希望される方の資産状況とか収入状況というのは何か勘案されたりするのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"入所調整基準についてのご質問ですが、基準の中にあるものが、収入とかの基準はないですので、この部分については考慮しておりません。","voiceIndex":292,"id":"exchange-108"},{"speaker":"筒井委員","kind":"質問","question":"先ほどの土地の話なのですけれども、大井・西大井地域は現実的には公有地を活用して建てていかれるのがその流れかなと思っているのですけれども、今後大井・西大井地域に特養老人ホームの建設にふさわしい公有地というのは、今現在存在しているのでしょうか。","respondent":"東野福祉計画課長","answer":"公有地の未利用地ということでありますと、現在はございません。","voiceIndex":294,"id":"exchange-109"},{"speaker":"こしば副委員長","kind":"質問","question":"今も小山台だとか、東大井三丁目とかの国有地だったりありますので、土地自体は区の負担はかかっていないですが、例えばこれを民有地を活用するとなれば、また当然にそれは土地代がかかってくるわけですので、そうするとこの介護保険料にも少なからず影響を及ぼすものと考えますと、その辺の全体を俯瞰して見ますと、今回のこの請願については、自民党会派としては不採択でお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-110"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、これからもアンテナを張って、民有地のほうもアンテナを張ってというご答弁もありましたので、ぜひこれからも品川区全体でこうした土地利用できる、またそのときの区の高齢施策を総合的に考えて、どういうふうにこれをしていくのかということも併せて考えを持っていただいて、どうか区民の皆さんのご要望がかなえられるような状況がこの先あったならば、そうしたことも考えていくといったところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-111"},{"speaker":"ひがし委員","kind":"意見","question":"結論を出すで、不採択でお願いいたします。住み慣れた場所、また家族の近くの施設の入所というこの希望はとてもお気持ちは十分理解できるというのは、前の委員の方々に同意いたします。ただ、特定のエリアに絞って建設というのは、用地取得の問題、また区民のニーズを把握して慎重に検討していく必要があると思いますので、会派として今回は不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":300,"id":"exchange-112"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すで、採択でお願いしたいと思います。要介護度４、５の重度の方であってもこれしか入れないという、それが実態になっています。ぜひ、住み慣れた地域で地元で、本当にそれができるのが一番だと思いますし、そういうことも含めて、品川区としては特養ホーム増設という政策として持っていただいて、増設の方向を具体化していただきたいということを改めて申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-113"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論出すで、不採択でお願いします。請願された方の気持ちは物すごく分かるのですけれども、やはり何と言っても物理的に用地の確保がこの大井・西大井地域に限定するとなると非常に困難かなと考えております。一方で、そうした老人ホームに入れない方々の不安を払拭するための在宅支援の充実を求めていきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-114"},{"speaker":"おぎの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。やはり、それを持ってこられた４４６名の方の地域のニーズといったものは、見過ごすことができないものだと考えます。在宅ケアが一番理想ではありますが、もし家で見られないのであれば、なるべく住み慣れた地域に家族の近くにという気持ちは非常に私もよく分かります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":303,"id":"exchange-115"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"品川区は２３区中２０位ということで、恐らくお話を聞いていると、区の方針としては別にこれを上位にしていこうというつもりはないとは思いますけれども、さすがに２０位は低いと思いますので、その辺は適時施設を造っていただきたいと思いますし、何より在宅支援重視ということで、品川区は以前からも、そして今後も介護システム、介護サービスを行っていくということですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3662#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":72236,"voices":310}}]);
